import smbus
import time
import sys

# ADS1115 constants
I2C_BUS = 1
I2C_ADDR = 0x48

# Register addresses
REG_CONVERSION = 0x00
REG_CONFIG = 0x01

# Config register bit fields
CONFIG_OS_SINGLE = 0x8000      # Bit 15: Begin single conversion
CONFIG_MUX_OFFSET = 12         # Bits 14:12: Input multiplexer
CONFIG_PGA_4_096V = 0x0200     # Bits 11:9: PGA gain = ±4.096 V
CONFIG_MODE_SINGLE = 0x0100    # Bit 8: Single-shot mode
CONFIG_DR_128SPS = 0x0080      # Bits 7:5: Data rate = 128 SPS
CONFIG_CQUE_NONE = 0x0003      # Bits 1:0: Disable comparator

# Timing
CONV_TIMEOUT_S = 0.1
SCAN_DELAY_S = 0.05
NUM_CHANNELS = 4


def _swap_bytes(word: int) -> int:
    """Swap the two bytes of a 16-bit word (ADS1115 is big-endian over SMBus)."""
    return ((word & 0xFF00) >> 8) | ((word & 0x00FF) << 8)


def _build_config(channel: int) -> int:
    """Build the 16-bit config word for a single-ended channel (0-3)."""
    if not 0 <= channel <= 3:
        raise ValueError(f"Invalid channel {channel}; must be 0-3")
    return (
        CONFIG_OS_SINGLE
        | (CONFIG_MUX_OFFSET + channel) << CONFIG_MUX_OFFSET
        | CONFIG_PGA_4_096V
        | CONFIG_MODE_SINGLE
        | CONFIG_DR_128SPS
        | CONFIG_CQUE_NONE
    )


def _read_config(bus: smbus.SMBus) -> int:
    """Read the 16-bit config register (big-endian over SMBus)."""
    raw = bus.read_word_data(I2C_ADDR, REG_CONFIG)
    return _swap_bytes(raw)


def _write_config(bus: smbus.SMBus, config: int) -> None:
    """Write a 16-bit value to the config register (big-endian over SMBus)."""
    bus.write_word_data(I2C_ADDR, REG_CONFIG, _swap_bytes(config))


def _read_conversion(bus: smbus.SMBus) -> int:
    """Read the 16-bit conversion register (big-endian over SMBus)."""
    raw = bus.read_word_data(I2C_ADDR, REG_CONVERSION)
    return _swap_bytes(raw)


def read_adc_channel(bus: smbus.SMBus, channel: int) -> int:
    """
    Trigger a single-shot conversion on `channel` and return the raw 16-bit
    ADC value.  Raises TimeoutError if the conversion does not complete
    within CONV_TIMEOUT_S.
    """
    config = _build_config(channel)
    _write_config(bus, config)

    deadline = time.monotonic() + CONV_TIMEOUT_S
    while True:
        try:
            status = _read_config(bus)
        except OSError as exc:
            raise OSError(f"I2C read of config register failed on channel {channel}: {exc}") from exc

        if not (status & CONFIG_OS_SINGLE):
            break
        if time.monotonic() > deadline:
            raise TimeoutError(f"Conversion timeout on channel {channel}")
        time.sleep(0.001)

    try:
        return _read_conversion(bus)
    except OSError as exc:
        raise OSError(f"I2C read of conversion register failed on channel {channel}: {exc}") from exc


def main() -> None:
    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            readings = []
            for ch in range(NUM_CHANNELS):
                try:
                    value = read_adc_channel(bus, ch)
                    readings.append(value)
                except (OSError, TimeoutError) as exc:
                    print(f"Channel {ch}: error ({exc})", file=sys.stderr)
                    readings.append(None)

            print("ADC Readings:", end=" ")
            for ch, value in enumerate(readings):
                if value is None:
                    print(f"CH{ch}: ERR", end=" ")
                else:
                    print(f"CH{ch}: {value:05d}", end=" ")
            print()

            time.sleep(SCAN_DELAY_S)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        bus.close()


if __name__ == "__main__":
    main()

