import time
import logging
import signal
import sys
from adafruit_ads1x15.ads1115 import ADS1115
from adafruit_ads1x15.analog_in import AnalogIn
from adafruit_blinka.microcontroller.bcm283x.i2c import I2C as AdafruitI2C

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class Oscilloscope:
    """Object-oriented oscilloscope that samples two ADS1115 channels at ~10 Hz."""

    def __init__(self, i2c_bus=1, channels=(0, 1), rate=10.0):
        self.i2c_bus = i2c_bus
        self.channels = channels
        self.rate = rate
        self.i2c = None
        self.ads = None
        self.channel_objects = []
        self.running = False

    def initialize(self):
        """Open I2C bus, configure ADS1115, and create AnalogIn objects."""
        try:
            self.i2c = AdafruitI2C(self.i2c_bus)
            logger.info("I2C bus %d opened.", self.i2c_bus)
        except Exception as exc:
            logger.error("Failed to open I2C bus %d: %s", self.i2c_bus, exc)
            return False

        try:
            self.ads = ADS1115(self.i2c, address=0x48)
            self.ads.gain = 1
            self.ads.mode = 0
            logger.info("ADS1115 initialized at address 0x48, gain=1, continuous mode.")
        except Exception as exc:
            logger.error("Failed to initialize ADS1115: %s", exc)
            self._close_i2c()
            return False

        try:
            for ch in self.channels:
                obj = AnalogIn(self.ads, ch)
                self.channel_objects.append(obj)
            logger.info("AnalogIn objects created for channels %s.", self.channels)
        except Exception as exc:
            logger.error("Failed to create AnalogIn objects: %s", exc)
            self._close_ads()
            self._close_i2c()
            return False

        return True

    def run(self):
        """Sample both channels at ~10 Hz and print CSV rows until interrupted."""
        if not self.initialize():
            logger.error("Initialization failed; cannot start sampling.")
            return

        self.running = True
        logger.info("Oscilloscope started sampling at %.1f Hz.", self.rate)

        try:
            while self.running:
                timestamp = time.monotonic()
                values = []
                for obj in self.channel_objects:
                    try:
                        values.append(obj.voltage)
                    except Exception as exc:
                        logger.warning("Read failed on channel %s: %s", obj.channel, exc)
                        values.append(None)
                print(f"{timestamp:.6f},{values[0]:.4f},{values[1]:.4f}")
                time.sleep(1.0 / self.rate)
        except KeyboardInterrupt:
            logger.info("KeyboardInterrupt received; stopping oscilloscope.")
        except Exception as exc:
            logger.error("Unexpected error during sampling: %s", exc)
        finally:
            self.close()

    def close(self):
        """Release all resources: channel objects, ADS1115, and I2C bus."""
        if self.channel_objects:
            for obj in self.channel_objects:
                try:
                    obj.close()
                except Exception:
                    pass
            self.channel_objects.clear()
            logger.info("Channel objects closed.")

        if self.ads is not None:
            try:
                self.ads = None
            except Exception:
                pass

        if self.i2c is not None:
            try:
                self.i2c.deinit()
            except Exception:
                pass
            self.i2c = None
            logger.info("I2C bus deinitialized.")

    def _close_ads(self):
        if self.ads is not None:
            try:
                self.ads = None
            except Exception:
                pass

    def _close_i2c(self):
        if self.i2c is not None:
            try:
                self.i2c.deinit()
            except Exception:
                pass
            self.i2c = None

    def stop(self):
        self.running = False


def _signal_handler(signum, frame, oscilloscope):
    logger.info("Signal %d received; stopping oscilloscope.", signum)
    oscilloscope.stop()


if __name__ == "__main__":
    oscilloscope = Oscilloscope(i2c_bus=1, channels=(0, 1), rate=10.0)
    signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, oscilloscope))
    signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, oscilloscope))
    oscilloscope.run()

