                return adc_out
        except Exception as e:
            self.logger.error(f"Error reading analog sensor {self.sensor_id}: {e}")
            return None

    def run(self):
        self.running = True
        try:
            while self.running:
                if self.sensor_type == "digital":
                    reading = self.read_digital()
                elif self.sensor_type == "analog":
                    reading = self.read_analog()
                else:
                    self.logger.error(f"Invalid sensor type: {self.sensor_type}")
                    break

                if reading is not None:
                    if (self.sensor_type == "digital" and reading == 1) or (self.sensor_type == "analog" and reading >= self.threshold):
                        msg = f"Sensor {self.sensor_id}: Sound detected (reading={reading})"
                        self.logger.info(msg)
                        if self.log_queue:
                            self.log_queue.put(msg)
                    time.sleep(0.1)
                time.sleep(1 / self.sample_rate)
        except Exception as e:
            self.logger.error(f"Error in sensor {self.sensor_id} thread: {e}")
        finally:
            self.stop()

    def stop(self):
        self.running = False
        if self.sensor_type == "digital":
            GPIO.cleanup(self.gpio_pins)
        if self.spi:
            try:
                self.spi.close()
            except Exception:
                pass

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitoring System")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"], help="Sensor type (digital or analog)")
    parser.add_argument("--threshold", type=int, required=True, help="Sound threshold (for analog sensors)")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sampling rate (Hz)")
    parser.add_argument("--log_file", required=True, help="Path to the log file")
    parser.add_argument("--gpio_pins", nargs="+", type=int, help="GPIO pins for digital sensors")
    parser.add_argument("--channels", nargs="+", type=int, help="MCP3008 channels for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed (Hz)")
    parser.add_argument("--sensor_ids", nargs="+", required=True, help="Unique sensor IDs")
    args = parser.parse_args()

    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    log_queue = queue.Queue()
    queue_handler = logging.handlers.QueueHandler(log_queue)
    file_handler = logging.FileHandler(args.log_file)
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    file_handler.setFormatter(formatter)
    root_logger = logging.getLogger()
    root_logger.addHandler(file_handler)
    root_logger.addHandler(queue_handler)

    sensors = []
    for sensor_id in args.sensor_ids:
        sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue)
        sensors.append(sensor)

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        threads.append(thread)
        thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        for thread in threads:
            thread.join(timeout=2)
        for sensor in sensors:
            sensor.stop()
        logging.shutdown()

if __name__ == "__main__":
    main()

