    camera_id = config.get('camera_id', 0)
    led_pin = config.get('led_pin', 17)
    door_pin = config.get('door_pin', 27)
    gpio_door_control = config.get('gpio_door_control', False)

    _camera = initialize_camera()
    if _camera is None:
        logger.error('Failed to initialize camera. Exiting.')
        cleanup()
        sys.exit(1)

    try:
        while _running:
            try:
                image_data = _camera.capture_array()
            except Exception as e:
                logger.error('Frame capture failed: %s', e)
                time.sleep(0.1)
                continue

            if run_inference(image_data):
                logger.info('Bird detected!')
                indicate_bird(led_pin)
                if gpio_door_control:
                    control_door(door_pin, True)
                    time.sleep(5)
                    control_door(door_pin, False)

            time.sleep(0.1)
    except Exception as e:
        logger.error('Unexpected error in main loop: %s', e)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

