import io
import time
import json
import signal
import threading
import queue
import logging
import sys

import numpy as np
import cv2
from picamera2 import Picamera2
from libcamera import Transform
from gpiozero import LED, GPIOZeroError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

running = True

def signal_handler(sig, frame):
    global running
    logging.info("Shutdown signal received. Cleaning up...")
    running = False

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        sys.exit(1)
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON format in configuration file: {config_file}")
        sys.exit(1)

def trigger_alert(gpio_pin, alert_duration):
    try:
        led = LED(gpio_pin)
        led.on()
        time.sleep(alert_duration)
        led.off()
        led.close()
    except GPIOZeroError as e:
        logging.error(f"GPIO error during alert: {e}")
    except Exception as e:
        logging.error(f"Unexpected error during alert: {e}")

def detect_motion(frame1, frame2, threshold):
    try:
        diff = cv2.absdiff(frame1, frame2)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        blur = cv2.GaussianBlur(gray, (5, 5), 0)
        _, thresh = cv2.threshold(blur, threshold, 255, cv2.THRESH_BINARY)
        dilated = cv2.dilate(thresh, None, iterations=3)
        contours, _ = cv2.findContours(dilated, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)
        for contour in contours:
            if cv2.contourArea(contour) > 500:
                return True
        return False
    except Exception as e:
        logging.error(f"Error in motion detection: {e}")
        return False

def camera_thread(camera, frame_queue, config):
    global running
    width = config.get('resolution_width', 640)
    height = config.get('resolution_height', 480)
    framerate = config.get('framerate', 30)
    queue_size = config.get('queue_size', 10)
    motion_threshold = config.get('motion_threshold', 25)
    gpio_pin = config.get('gpio_pin', None)
    alert_duration = config.get('alert_duration', 1.0)

    try:
        camera.configure(camera.create_video_configuration(
            main={"size": (width, height), "format": "RGB888"},
            transform=Transform(vflip=True, hflip=True)
        ))
        camera.start()
        time.sleep(2)  # Camera warm-up time

        prev_frame = None
        while running:
            try:
                frame = camera.capture_array()
                if frame is None:
                    logging.warning("Captured empty frame")
                    continue

                # Encode frame to JPEG and put in queue
                ret, jpeg = cv2.imencode('.jpg', frame)
                if not ret:
                    logging.error("Failed to encode frame to JPEG")
                    continue

                try:
                    frame_queue.put(jpeg.tobytes(), timeout=1)
                except queue.Full:
                    try:
                        frame_queue.get_nowait()
                    except queue.Empty:
                        pass
                    frame_queue.put(jpeg.tobytes())

                # Motion detection
                if prev_frame is not None:
                    if detect_motion(prev_frame, frame, motion_threshold):
                        if gpio_pin is not None:
                            threading.Thread(target=trigger_alert, args=(gpio_pin, alert_duration), daemon=True).start()

                prev_frame = frame.copy()

                time.sleep(1 / framerate + 0.1)

            except Exception as e:
                logging.error(f"Error in camera thread: {e}")
                time.sleep(0.1)

    except Exception as e:
        logging.error(f"Camera initialization error: {e}")
    finally:
        try:
            camera.stop()
        except Exception:
            pass

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config('config.json')
    frame_queue = queue.Queue(maxsize=config.get('queue_size', 10))

    picam2 = None
    try:
        picam2 = Picamera2()
        camera_thread_instance = threading.Thread(target=camera_thread, args=(picam2, frame_queue, config), daemon=True)
        camera_thread_instance.start()

        while running:
            time.sleep(1)

    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        running = False
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass

if __name__ == "__main__":
    main()

