import argparse
import os
import sys
import time
import signal
import threading
import traceback
from pathlib import Path

import cv2
import torch
import RPi.GPIO as GPIO
from gpiozero import LED
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.lcd.device import charLCD

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
LED_PINS = {
    0: 17,   # person  -> red
    2: 18,   # car     -> green
    3: 23,   # motorcycle -> yellow
    5: 27,   # bus     -> white
    7: 22,   # truck   -> blue
}

LCD_I2C_ADDR = 0x27
LCD_COLS = 16
LCD_ROWS = 2
I2C_BUS = 1

# COCO class labels we care about
TRACKED_CLASSES = [0, 2, 3, 5, 7]

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_camera = None
_leds = {}
_lcd = None
_lcd_lock = threading.Lock()


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _camera, _lcd, _leds
    if _camera is not None:
        try:
            _camera.release()
        except Exception:
            pass
        _camera = None
    for led in _leds.values():
        try:
            led.off()
            led.close()
        except Exception:
            pass
    _leds.clear()
    if _lcd is not None:
        try:
            with _lcd_lock:
                _lcd.clear()
        except Exception:
            pass
    try:
        cv2.destroyAllWindows()
    except Exception:
        pass


def _init_leds():
    leds = {}
    for cls_id, pin in LED_PINS.items():
        try:
            leds[cls_id] = LED(pin)
        except Exception as e:
            print(f"[ERROR] Failed to init LED on GPIO{pin} (class {cls_id}): {e}", file=sys.stderr)
            raise
    return leds


def _init_lcd():
    try:
        serial = i2c(port=I2C_BUS, address=LCD_I2C_ADDR)
        return charLCD(serial, LCD_COLS, LCD_ROWS)
    except Exception as e:
        print(f"[ERROR] Failed to init LCD on I2C bus {I2C_BUS} addr 0x{LCD_I2C_ADDR:02X}: {e}", file=sys.stderr)
        return None


def _update_lcd(lcd, stats):
    if lcd is None:
        return
    with _lcd_lock:
        try:
            with canvas(lcd) as draw:
                draw.text((0, 0), f"FPS: {stats['fps']:.1f}", fill="white")
                draw.text((0, 12), f"Det: {stats['detections']}", fill="white")
        except Exception as e:
            print(f"[WARN] LCD update failed: {e}", file=sys.stderr)


def _lcd_thread(lcd, stats_queue):
    while _running:
        try:
            stats = stats_queue.get(timeout=1.0)
            _update_lcd(lcd, stats)
        except Exception:
            pass


def _process_detections(results, stats):
    try:
        dets = results.xyxy[0].cpu().numpy()
    except Exception:
        dets = []
    for *xyxy, conf, cls_id in dets:
        cls_id = int(cls_id)
        if cls_id not in TRACKED_CLASSES:
            continue
        stats['detections'] += 1
        pin = LED_PINS.get(cls_id)
        if pin is not None:
            try:
                _leds[cls_id].on()
                time.sleep(1.0)
                _leds[cls_id].off()
