    _running = False


def _cleanup():
    global _camera, _lcd, _leds
    if _camera is not None:
        try:
            _camera.release()
        except Exception:
            pass
        _camera = None
    for led in _leds.values():
        try:
            led.off()
            led.close()
        except Exception:
            pass
    _leds.clear()
    if _lcd is not None:
