import cv2
import time
import signal
import sys
import os
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

try:
    from gpiozero import LED, Button, Servo
    from gpiozero.pins.lgpio import LGPIOFactory
    _GPIO_AVAILABLE = True
except ImportError:
    logger.warning("gpiozero not found; GPIO control disabled.")
    _GPIO_AVAILABLE = False

# Constants
FACE_CASCADE_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
RESIZE_WIDTH = 32
RESIZE_HEIGHT = 32
CAMERA_INDEX = 0
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_FREQUENCY = 50
SERVO_INCREMENT = 20
DISPLAY_WINDOW_NAME = 'Human Detection'
CAMERA_WARMUP_TIME = 2.0
POLL_INTERVAL = 0.01

# Global state for cleanup
_camera = None
_led = None
_button = None
_servo = None
_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info(f"Signal {signum} received; shutting down.")
    _running = False


def initialize_camera(camera_index=CAMERA_INDEX):
    try:
        camera = cv2.VideoCapture(camera_index)
        if not camera.isOpened():
            raise IOError(f"Cannot open camera at index {camera_index}")
        time.sleep(CAMERA_WARMUP_TIME)
        return camera
    except Exception as e:
        logger.error(f"Camera initialization failed: {e}")
        return None


def detect_faces(image, face_cascade):
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(
        gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)
    )


def initialize_gpio():
    global _led, _button, _servo
    try:
        _led = LED(LED_PIN)
        _button = Button(BUTTON_PIN, pull_up=True)
        _servo = Servo(
            SERVO_PIN,
            initial_value=0,
            min_pulse_width=0.0005,
            max_pulse_width=0.0025,
            frame_width=1.0 / SERVO_FREQUENCY,
        )
        logger.info("GPIO initialized successfully.")
        return True
    except Exception as e:
        logger.error(f"GPIO initialization failed: {e}")
        _led = None
        _button = None
        _servo = None
        return False


def set_servo_angle(servo, angle):
    try:
        servo.value = (angle + 90) / 180.0
        time.sleep(0.02)
    except Exception as e:
        logger.error(f"Servo control failed: {e}")


def process_frame(frame, face_cascade, led, servo):
    resized_frame = cv2.resize(frame, (RESIZE_WIDTH, RESIZE_HEIGHT))
    faces = detect_faces(resized_frame, face_cascade)

    face_detected = len(faces) > 0
    if led is not None:
        try:
            led.on() if face_detected else led.off()
        except Exception as e:
            logger.error(f"LED control failed: {e}")

    if face_detected and servo is not None:
        try:
            height, width, _ = frame.shape
            for (x, y, w, h) in faces:
                face_center_x = x + w / 2.0
                if face_center_x > width / 2.0:
                    current_angle = int(servo.angle * 180 / 3.141592653589793)
                    new_angle = min(180, current_angle + SERVO_INCREMENT)
                else:
                    current_angle = int(servo.angle * 180 / 3.141592653589793)
                    new_angle = max(0, current_angle - SERVO_INCREMENT)
                set_servo_angle(servo, new_angle)
                break
        except Exception as e:
            logger.error(f"Servo angle calculation failed: {e}")

    return faces


def display_frame(frame, faces, window_name=DISPLAY_WINDOW_NAME):
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
    try:
        cv2.imshow(window_name, frame)
        return True
    except Exception as e:
        logger.error(f"Display failed: {e}")
        return False


def release_resources(camera, window_name=DISPLAY_WINDOW_NAME):
    global _led, _button, _servo
    try:
        if camera is not None:
            camera.release()
    except Exception as e:
        logger.error(f"Error releasing camera: {e}")
    try:
        cv2.destroyAllWindows()
    except Exception as e:
        logger.error(f"Error destroying windows: {e}")
    if _led is not None:
        try:
            _led.close()
        except Exception:
            pass
        _led = None
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
        _button = None
    if _servo is not None:
        try:
            _servo.close()
        except Exception:
            pass
        _servo = None


def main():
    global _camera, _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    face_cascade = None
    if not os.path.isfile(FACE_CASCADE_PATH):
        logger.error(f"Cascade file not found: {FACE_CASCADE_PATH}")
        sys.exit(0)
    try:
        face_cascade = cv2.CascadeClassifier(FACE_CASCADE_PATH)
        if face_cascade.empty():
            raise IOError("Failed to load face cascade classifier")
    except Exception as e:
        logger.error(f"Error loading face cascade: {e}")
        sys.exit(0)

    _camera = initialize_camera()
    if _camera is None:
        logger.error("Camera initialization failed.")
        sys.exit(0)

    gpio_ok = initialize_gpio() if _GPIO_AVAILABLE else False

    try:
        while _running:
            ret, frame = _camera.read()
            if not ret:
                logger.error("Failed to grab frame from camera.")
                break

            faces = process_frame(frame, face_cascade, _led if gpio_ok else None, _servo if gpio_ok else None)

            if not display_frame(frame, faces):
                logger.warning("Display unavailable; continuing without GUI.")
                time.sleep(POLL_INTERVAL)
                continue

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        release_resources(_camera)


if __name__ == "__main__":
    main()

