import cv2
import numpy as np
import pyzbar.pyzbar as pyzbar
import signal
import sys

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    """Initialize the Raspberry Pi camera via the CSI bus at 64x64."""
    try:
        cam = cv2.VideoCapture(0, cv2.CAP_V4L2)
        if not cam.isOpened():
            raise RuntimeError("Failed to open camera (index 0).")
        cam.set(cv2.CAP_PROP_FRAME_WIDTH, 64)
        cam.set(cv2.CAP_PROP_FRAME_HEIGHT, 64)
        actual_w = cam.get(cv2.CAP_PROP_FRAME_WIDTH)
        actual_h = cam.get(cv2.CAP_PROP_FRAME_HEIGHT)
        if actual_w != 64 or actual_h != 64:
            print(f"Warning: requested 64x64, got {int(actual_w)}x{int(actual_h)}")
        return cam
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(cam):
    """Capture a single frame from the camera."""
    try:
        ret, frame = cam.read()
        if not ret or frame is None:
            print("Error capturing frame.")
            return None
        return frame
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def decode_qr_code(frame):
    """Decode any QR code present in the frame."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = pyzbar.decode(gray)
        return decoded_objects
    except Exception as e:
        print(f"Error decoding QR code: {e}")
        return []

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cam = initialize_camera()
    if cam is None:
        print("No QR code detected.")
        return

    try:
        frame = capture_frame(cam)
        if frame is None:
