import time
import signal
import sys
import board
import busio
import digitalio

try:
    import adafruit_bme280
except ImportError:
    print("ERROR: adafruit-circuitpython-bme280 not installed.  Run: pip install adafruit-circuitpython-bme280")
    sys.exit(1)

try:
    import adafruit_epd.epd
    import adafruit_epd.il0373
except ImportError:
    print("ERROR: adafruit-circuitpython-epd not installed.  Run: pip install adafruit-circuitpython-epd")
    sys.exit(1)

# --- Pin map (BCM numbering) ---
BME280_CS_PIN = board.D7   # GPIO7  (CE1)
BME280_SCK_PIN = board.D11  # GPIO11
BME280_MOSI_PIN = board.D10 # GPIO10
BME280_MISO_PIN = board.D9  # GPIO9

EPD_CS_PIN = board.D5
EPD_DC_PIN = board.D6
EPD_RESET_PIN = board.D9
EPD_BUSY_PIN = board.D10

# --- Globals for cleanup ---
_running = True
_spi_bus = None
_bme280 = None
_epd = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _spi_bus, _bme280, _epd
    if _epd is not None:
        try:
            _epd.deinit()
        except Exception:
            pass
    for dev in (_bme280, _epd):
        if dev is not None:
            try:
                dev.deinit()
            except Exception:
                pass
    if _spi_bus is not None:
        try:
            _spi_bus.deinit()
        except Exception:
            pass


def _init_spi_bus():
    global _spi_bus
    try:
        _spi_bus = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        while not _spi_bus.try_lock():
            time.sleep(0.01)
        _spi_bus.configure(baudrate=1000000, phase=0, polarity=0)
        _spi_bus.unlock()
        return _spi_bus
    except Exception as e:
        print(f"FATAL: SPI bus initialization failed: {e}")
        _cleanup()
        sys.exit(1)


def _init_bme280():
    global _bme280
    try:
        cs = digitalio.DigitalInOut(BME280_CS_PIN)
        cs.direction = digitalio.Direction.OUTPUT
        cs.value = True
        _bme280 = adafruit_bme280.Adafruit_BME280_SPI(_spi_bus, cs)
        _bme280.sea_level_pressure = 1013.25
        return _bme280
    except (RuntimeError, ValueError) as e:
        print(f"WARNING: BME280 not detected or init failed: {e}")
        _bme280 = None
        return None
    except Exception as e:
        print(f"WARNING: BME280 init error: {e}")
        _bme280 = None
        return None


def _init_epd():
    global _epd
    try:
        cs = digitalio.DigitalInOut(EPD_CS_PIN)
        dc = digitalio.DigitalInOut(EPD_DC_PIN)
        reset = digitalio.DigitalInOut(EPD_RESET_PIN)
        busy = digitalio.DigitalInOut(EPD_BUSY_PIN)
        cs.direction = digitalio.Direction.OUTPUT
        dc.direction = digitalio.Direction.OUTPUT
        reset.direction = digitalio.Direction.OUTPUT
        busy.direction = digitalio.Direction.INPUT
        _epd = adafruit_epd.il0373.IL0373(128, 296, spi=_spi_bus, cs=cs, dc=dc, reset=reset, busy=busy, rotation=0)
        _epd.rotation = 0
        return _epd
    except Exception as e:
        print(f"FATAL: EPD initialization failed: {e}")
        _cleanup()
        sys.exit(1)


def _read_sensor():
    if _bme280 is None:
        return None, None, None
    try:
        return _bme280.temperature, _bme280.humidity, _bme280.pressure
    except (RuntimeError, ValueError) as e:
        print(f"WARNING: BME280 read error: {e}")
        return None, None, None
    except Exception as e:
        print(f"WARNING: BME280 unexpected error: {e}")
        return None, None, None


def _update_display(temp, hum, pres):
    if _epd is None:
        return
    try:
        _epd.fill(adafruit_epd.il0373.WHITE)
        _epd.text(f"Temp: {temp:.1f} C", 0, 0, adafruit_epd.il0373.BLACK)
        _epd.text(f"Hum: {hum:.1f} %", 0, 20, adafruit_epd.il0373.BLACK)
        _epd.text(f"Pres: {pres:.1f} hPa", 0, 40, adafruit_epd.il0373.BLACK)
        _epd.display()
    except Exception as e:
        print(f"WARNING: EPD update failed: {e}")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_spi_bus()
    _init_bme280()
    _init_epd()

    while _running:
        temp, hum, pres = _read_sensor()
        if temp is not None and hum is not None and pres is not None:
            print(f"T={temp:.1f} C  H={hum:.1f} %  P={pres:.1f} hPa")
            _update_display(temp, hum, pres)
        else:
            print("Sensor read failed; skipping display update.")
        for _ in range(60):
            if not _running:
                break
            time.sleep(1)

    _cleanup()


if __name__ == "__main__":
    main()

