            self.picam2 = Picamera2()
            config = self.picam2.create_preview_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                controls={"FrameRate": self.frame_rate},
            )
            self.picam2.configure(config)
            self.picam2.start()
            logging.info("Camera started at %d fps", self.frame_rate)
        except Exception as exc:
            logging.error("Error initializing camera: %s", exc)
            raise

    def capture_frames(self) -> None:
        while self._running.is_set():
            try:
                frame = self.picam2.capture_array()
                if frame is None:
                    logging.warning("Camera returned None frame")
                    continue
                try:
                    self.frame_queue.put(frame, timeout=1.0)
                except queue.Full:
                    logging.warning("Frame dropped: queue full")
            except Exception as exc:
                logging.error("Error capturing frame: %s", exc)
                time.sleep(0.1)

    def stop(self) -> None:
        self._running.clear()
        if self.picam2 is not None:
            try:
                self.picam2.stop()
            except Exception as exc:
                logging.error("Error stopping camera: %s", exc)


class SmartHomeController:
    """Manages simulated smart-home state and cloud logging."""

    def __init__(self, cloud_data_file: str):
        self.cloud_data_file = cloud_data_file
        self.state = {"light": False, "thermostat": 20, "tv": False}
        self._lock = threading.Lock()

    def handle_gesture(self, gesture: str, confidence: float) -> None:
        if confidence < 0.7:
            logging.info("Low confidence (%.2f) for %s; ignoring", confidence, gesture)
            return
        with self._lock:
            if gesture == "Open Hand":
                self.state["light"] = not self.state["light"]
                logging.info("Light toggled to %s", self.state["light"])
            elif gesture == "Closed Fist":
                self.state["light"] = False
                logging.info("Light turned off")
            elif gesture == "Pointing Up":
                if self.state["thermostat"] < 30:
                    self.state["thermostat"] += 1
                    logging.info("Thermostat set to %d", self.state["thermostat"])
            elif gesture == "Pointing Down":
                if self.state["thermostat"] > 15:
                    self.state["thermostat"] -= 1
                    logging.info("Thermostat set to %d", self.state["thermostat"])
            elif gesture == "Peace Sign":
                self.state["tv"] = not self.state["tv"]
                logging.info("TV toggled to %s", self.state["tv"])
            else:
                logging.warning("Unknown gesture: %s", gesture)
        self._log_to_cloud(gesture, confidence)

    def _log_to_cloud(self, gesture: str, confidence: float) -> None:
        timestamp = datetime.datetime.now().isoformat()
        user_id = "user_001"
        data = {
            "timestamp": timestamp,
            "user_id": user_id,
            "gesture": gesture,
            "confidence": confidence,
            "state": dict(self.state),
        }
        try:
            with open(self.cloud_data_file, "a") as fh:
                fh.write(json.dumps(data) + "\n")
            logging.info("Logged to cloud: %s", data)
        except Exception as exc:
            logging.error("Error writing to cloud data file: %s", exc)

    def get_state(self) -> dict:
        with self._lock:
            return dict(self.state)


def main() -> None:
    parser = argparse.ArgumentParser(description="Gesture-controlled smart home")
    parser.add_argument(
        "--model_path",
        default="gesture_model_quantized.tflite",
        help="Path to the quantized TFLite model",
    )
    parser.add_argument(
        "--frame_rate", type=int, default=30, help="Camera frame rate (fps)",
    )
    parser.add_argument(
        "--frame_width", type=int, default=224, help="Model input width",
    )
    parser.add_argument(
        "--frame_height", type=int, default=224, help="Model input height",
    )
    parser.add_argument(
        "--confidence_threshold", type=float, default=0.7,
    )
    parser.add_argument(
        "--cooldown", type=float, default=2.0, help="Seconds between gestures",
    )
    parser.add_argument(
        "--cloud_data_file", default="cloud_data.json",
    )
    args = parser.parse_args()

    frame_queue: queue.Queue = queue.Queue(maxsize=10)
    stop_event = threading.Event()

    def signal_handler(signum, frame):
        logging.info("Signal %d received, shutting down", signum)
        stop_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera_handler = None
    try:
        camera_handler = CameraHandler(frame_queue, frame_rate=args.frame_rate)
        camera_handler.start()
    except Exception as exc:
        logging.error("Failed to initialize camera: %s", exc)
        sys.exit(0)

    gesture_recognizer = None
    try:
        gesture_recognizer = GestureRecognizer(args.model_path)
    except Exception as exc:
        logging.error("Failed to load gesture model: %s", exc)
        camera_handler.stop()
        sys.exit(0)

    smart_home_controller = SmartHomeController(args.cloud_data_file)

    def preprocess_frame(frame: np.ndarray) -> np.ndarray:
        from PIL import Image
        img = Image.fromarray(frame)
        img = img.resize((args.frame_width, args.frame_height), Image.LANCZOS)
        return np.array(img, dtype=np.float32)

    def inference_worker() -> None:
        last_gesture_time = 0.0
        while not stop_event.is_set():
            try:
                frame = frame_queue.get(timeout=1.0)
            except queue.Empty:
                continue
            try:
                preprocessed = preprocess_frame(frame)
                gesture, confidence = gesture_recognizer.recognize(preprocessed)
                now = time.time()
                if now - last_gesture_time >= args.cooldown:
                    smart_home_controller.handle_gesture(gesture, confidence)
                    last_gesture_time = now
            except Exception as exc:
                logging.error("Inference error: %s", exc)

    inference_thread = threading.Thread(target=inference_worker, daemon=True)
    inference_thread.start()

    try:
        while not stop_event.is_set():
            time.sleep(0.5)
    finally:
        stop_event.set()
        camera_handler.stop()
        inference_thread.join(timeout=3.0)
        logging.info("Shutdown complete")


if __name__ == "__main__":
    main()

