import json
import logging
import signal
import sys
import time
from collections import deque
from statistics import median

try:
    import RPi.GPIO as GPIO
except Exception:
    GPIO = None

# ---------------------------------------------------------------------------
# Configuration defaults
# ---------------------------------------------------------------------------
DEFAULT_CONFIG = {
    "sensor1_offset": 0.0,
    "sensor2_offset": 0.0,
    "sensor3_offset": 0.0,
    "sensor1_max_distance": 200.0,
    "sensor2_max_distance": 200.0,
    "sensor3_max_distance": 200.0,
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_running = True
_config = DEFAULT_CONFIG.copy()
_sensor_errors = {1: 0, 2: 0, 3: 0}
_sensor_enabled = {1: True, 2: True, 3: True}
_last_alert_time = None
_logger = None


def _setup_logging(log_file: str) -> None:
    global _logger
    _logger = logging.getLogger("water_level")
    _logger.setLevel(logging.INFO)
    _logger.handlers.clear()
    _logger.handlers.append(
        logging.FileHandler(log_file)
    )
    _logger.handlers.append(
        logging.StreamHandler(sys.stdout)
    )


def _load_config(path: str) -> dict:
    cfg = DEFAULT_CONFIG.copy()
    try:
        with open(path, "r") as f:
            user_cfg = json.load(f)
        for k in DEFAULT_CONFIG:
            if k in user_cfg:
                cfg[k] = user_cfg[k]
    except FileNotFoundError:
        _logger.warning("config.json not found; using defaults.")
    except json.JSONDecodeError as e:
        _logger.error(f"config.json parse error: {e}; using defaults.")
    except Exception as e:
        _logger.error(f"Unexpected config error: {e}; using defaults.")
    return cfg


def _signal_handler(signum, frame):
    global _running
    _running = False


def _init_gpio() -> bool:
    if GPIO is None:
        _logger.warning("RPi.GPIO not available; running in mock mode.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for trig in (17, 22, 24):
            GPIO.setup(trig, GPIO.OUT, initial=GPIO.LOW)
        for ech in (18, 23, 25):
            GPIO.setup(ech, GPIO.IN)
        return True
    except Exception as e:
        _logger.error(f"GPIO init failed: {e}")
        return False


def _cleanup_gpio() -> None:
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def _measure_distance(trigger_pin: int, echo_pin: int, max_distance: float) -> float | None:
    """Return distance in cm, or None on timeout / error."""
    if not _sensor_enabled.get(trigger_pin, True):
        return None
    if GPIO is None:
        return None
    try:
        GPIO.output(trigger_pin, GPIO.LOW)
        time.sleep(0.000002)
        GPIO.output(trigger_pin, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, GPIO.LOW)

        deadline = time.time() + 0.05
        while GPIO.input(echo_pin) == 0:
            if time.time() > deadline:
                _sensor_errors[trigger_pin] += 1
                return None
        pulse_start = time.time()

        deadline = time.time() + 0.05
        while GPIO.input(echo_pin) == 1:
            if time.time() > deadline:
                _sensor_errors[trigger_pin] += 1
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150.0
        if distance > max_distance:
            return None
        return distance
    except Exception:
        _sensor_errors[trigger_pin] += 1
        return None


def _read_sensors() -> list[float] | None:
    s1 = _measure_distance(17, 18, _config["sensor1_max_distance"])
    s2 = _measure_distance(22, 23, _config["sensor2_max_distance"])
    s3 = _measure_distance(24, 25, _config["sensor3_max_distance"])

    if s1 is None:
        _sensor_errors[1] += 1
        if _sensor_errors[1] >= 5:
            _sensor_enabled[1] = False
            _logger.warning("Sensor 1 disabled after 5 consecutive errors.")
    else:
        _sensor_errors[1] = 0

    if s2 is None:
        _sensor_errors[2] += 1
        if _sensor_errors[2] >= 5:
            _sensor_enabled[2] = False
            _logger.warning("Sensor 2 disabled after 5 consecutive errors.")
    else:
        _sensor_errors[2] = 0

    if s3 is None:
        _sensor_errors[3] += 1
        if _sensor_errors[3] >= 5:
            _sensor_enabled[3] = False
            _logger.warning("Sensor 3 disabled after 5 consecutive errors.")
    else:
        _sensor_errors[3] = 0

    valid = [s for s in (s1, s2, s3) if s is not None]
    if not valid:
        return None
    return valid


def _check_alerts(water_level: float) -> None:
    global _last_alert_time
    low = _config["alert_threshold_low"]
    high = _config["alert_threshold_high"]
    delay = _config["alert_repeat_delay"]
    now = time.time()
    if _last_alert_time is None or (now - _last_alert_time) > delay:
        if water_level < low:
            _logger.warning(f"LOW WATER LEVEL: {water_level:.2f} cm (threshold {low:.2f} cm)")
            _last_alert_time = now
        elif water_level > high:
            _logger.warning(f"HIGH WATER LEVEL: {water_level:.2f} cm (threshold {high:.2f} cm)")
            _last_alert_time = now


def main() -> int:
    global _config, _running
    _config = _load_config("config.json")
    _setup_logging(_config["log_file"])
    _logger.info("Water level monitor starting.")
    _logger.info(f"Config: {json.dumps(_config, indent=2)}")

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not _init_gpio():
        _logger.warning("Running without GPIO (mock mode).")

    try:
        while _running:
            readings = _read_sensors()
            if readings is None:
                _logger.error("No valid sensor readings this cycle.")
            else:
                water_level = median(readings)
                _logger.info(f"Water level: {water_level:.2f} cm (sensors: {readings})")
                _check_alerts(water_level)
            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)
    except Exception as e:
        _logger.error(f"Unexpected error: {e}")
    finally:
        _cleanup_gpio()
        _logger.info("Water level monitor stopped.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

