import os
import sys
import time
import signal
import random
import datetime
import threading
import logging
import subprocess
from typing import Optional, Tuple

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT_PIN = 4
LIGHT_PIN = 17
WAKE_WORD = "Greenhouse"
CAMERA_INDEX = 0
AUDIO_DEVICE_INDEX = None

GPIO_AVAILABLE = False
try:
    import RPi.GPIO as GPIO
    GPIO_AVAILABLE = True
except ImportError:
    logging.warning("RPi.GPIO not found. Running in simulation mode.")

try:
    import smbus
except ImportError:
    smbus = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

running = True
light_state = False
camera = None

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Termination signal received. Cleaning up...")

def init_gpio():
    if not GPIO_AVAILABLE:
        logging.warning("GPIO not available. Running in simulation mode.")
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}. Running in simulation mode.")
        GPIO_AVAILABLE = False

def cleanup_gpio():
    if GPIO_AVAILABLE:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error during GPIO cleanup: {e}")

def read_temperature() -> Tuple[Optional[float], Optional[float]]:
    if smbus is None:
        logging.warning("smbus not available. Simulating temperature.")
        return random.uniform(15, 35), random.uniform(60, 90)
    try:
        bus = smbus.SMBus(1)
        data = bus.read_i2c_block_data(DHT_PIN, 0, 5)
        if len(data) != 5:
            logging.warning("DHT11: Incomplete data read.")
            return None, None
        humidity = (data[0] << 8 | data[1]) / 10.0
        temperature = (data[2] << 8 | data[3]) / 10.0
        checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF
        if checksum != data[4]:
            logging.warning("DHT11: Checksum error.")
            return None, None
        return temperature, humidity
    except Exception as e:
        logging.warning(f"DHT11 read failed: {e}. Simulating temperature.")
        return random.uniform(15, 35), random.uniform(60, 90)

def control_lights(state: bool):
    global light_state
    if not GPIO_AVAILABLE:
        light_state = state
        logging.info(f"Simulated: Lights turned {'on' if state else 'off'}.")
        return
    try:
        GPIO.output(LIGHT_PIN, GPIO.HIGH if state else GPIO.LOW)
        light_state = state
        logging.info(f"Lights turned {'on' if state else 'off'}.")
    except Exception as e:
        logging.error(f"Failed to control lights: {e}")

def take_picture():
    if Picamera2 is None:
        logging.warning("picamera2 not available. Cannot take picture.")
        return
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture_file(filename)
        logging.info(f"Picture saved as {filename}")
    except Exception as e:
        logging.error(f"Failed to take picture: {e}")

def listen_for_wake_word() -> bool:
    try:
        cmd = ['arecord', '-D', f'plughw:{AUDIO_DEVICE_INDEX}', '-d', '5', '-f', 'S16_LE', '-r', '16000', '-t', 'raw']
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        audio_data, _ = proc.communicate()
        if proc.returncode != 0:
            logging.warning("arecord failed.")
            return False
        if WAKE_WORD in audio_data.decode(errors='ignore'):
            logging.info("Wake word detected!")
            return True
        return False
    except Exception as e:
        logging.error(f"Audio error: {e}")
        return False

def process_command(command: str):
    if "turn on the lights" in command:
        control_lights(True)
    elif "turn off the lights" in command:
        control_lights(False)
    elif "what is the temperature" in command:
        temp, _ = read_temperature()
        if temp is not None:
            logging.info(f"Temperature is {temp:.1f} degrees Celsius.")
        else:
            logging.warning("Could not read temperature.")
    elif "take a picture" in command:
        take_picture()
    else:
        logging.warning(f"Unknown command: {command}")

def main():
    global camera
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    init_gpio()
    if Picamera2 is not None:
        try:
            camera = Picamera2()
            camera.configure(camera.create_still_configuration())
            camera.start()
            logging.info("Camera initialized.")
        except Exception as e:
            logging.error(f"Failed to initialize camera: {e}")
            camera = None
    try:
        while running:
            if listen_for_wake_word():
                logging.info("Listening for command...")
                try:
                    cmd = ['arecord', '-D', f'plughw:{AUDIO_DEVICE_INDEX}', '-d', '5', '-f', 'S16_LE', '-r', '16000', '-t', 'raw']
                    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                    audio_data, _ = proc.communicate()
                    if proc.returncode == 0:
                        command = audio_data.decode(errors='ignore')
                        logging.info(f"Command: {command}")
                        process_command(command)
                    else:
                        logging.warning("arecord failed.")
                except Exception as e:
                    logging.error(f"Audio error: {e}")
            time.sleep(0.1)
    finally:
        if camera is not None:
            try:
                camera.close()
                logging.info("Camera closed.")
            except Exception as e:
                logging.error(f"Error closing camera: {e}")
        cleanup_gpio()
        logging.info("Program terminated.")

