import argparse
import csv
import datetime
import os
import signal
import sys
import time

import RPi.GPIO as GPIO
from picamera2 import Picamera2

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def parse_args():
    parser = argparse.ArgumentParser(
        description="Vibration sensor monitor with CSI camera capture on Raspberry Pi."
    )
    parser.add_argument(
        "-g", "--gpio", required=True,
        help="Comma-separated list of BCM GPIO pins for vibration sensors (e.g., 17,27,22)."
    )
    parser.add_argument(
        "-l", "--log_file", required=True,
        help="Path to the CSV log file."
    )
    parser.add_argument(
        "-i", "--interval", type=float, default=1.0,
        help="Sampling interval in seconds (default: 1.0)."
    )
    parser.add_argument(
        "-c", "--calibrate", type=int, default=5,
        help="Calibration duration in seconds (default: 5)."
    )
    parser.add_argument(
        "-p", "--picture_interval", type=int, default=60,
        help="Picture capture interval in seconds (default: 60)."
    )
    return parser.parse_args()


def setup_gpio(pins):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in pins:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        except Exception as exc:
            print(f"Error configuring GPIO pin {pin}: {exc}", file=sys.stderr)
            raise


def calibrate_sensors(pins, duration):
    print("Calibrating sensors...")
    baselines = []
    for pin in pins:
        high_count = 0
        sample_count = 0
        start = time.monotonic()
        while time.monotonic() - start < duration:
            try:
                if GPIO.input(pin):
                    high_count += 1
                sample_count += 1
            except Exception as exc:
                print(f"Error reading GPIO pin {pin} during calibration: {exc}", file=sys.stderr)
                raise
            time.sleep(0.01)
        if sample_count == 0:
            print(f"Warning: no samples collected on pin {pin}; using 0% baseline.", file=sys.stderr)
            baselines.append(0.0)
        else:
            baselines.append((high_count / sample_count) * 100.0)
    thresholds = [b + 20.0 for b in baselines]
    print(f"Calibration complete. Baselines: {baselines}, Thresholds: {thresholds}")
    return baselines, thresholds


def read_sensors(pins, threshold, interval):
    start = time.monotonic()
    high_count = 0
    sample_count = 0
    while time.monotonic() - start < interval:
        for pin in pins:
            try:
                if GPIO.input(pin):
                    high_count += 1
                sample_count += 1
            except Exception as exc:
                print(f"Error reading GPIO pin {pin}: {exc}", file=sys.stderr)
                raise
        time.sleep(0.01)
    if sample_count == 0:
        return 0
    percentage = (high_count / sample_count) * 100.0
    return 1 if percentage > threshold else 0


def capture_image(camera, timestamp):
    try:
        image_dir = "images"
        os.makedirs(image_dir, exist_ok=True)
        image_path = os.path.join(image_dir, f"{timestamp}.jpg")
        camera.capture_file(image_path)
        print(f"Image captured: {image_path}")
    except Exception as exc:
        print(f"Error capturing image: {exc}", file=sys.stderr)


def main():
    global _running
    args = parse_args()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        gpio_pins = [int(p.strip()) for p in args.gpio.split(",")]
    except ValueError as exc:
        print(f"Invalid GPIO pin list: {exc}", file=sys.stderr)
        sys.exit(1)

    if len(gpio_pins) != 3:
        print("Exactly three GPIO pins are required.", file=sys.stderr)
        sys.exit(1)

    try:
        setup_gpio(gpio_pins)
    except Exception:
        sys.exit(1)

    camera = None
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
        print("Camera initialized successfully.")
    except Exception as exc:
        print(f"Camera initialization failed: {exc}", file=sys.stderr)
        print("Continuing without camera capture.", file=sys.stderr)
        camera = None

    try:
        baselines, thresholds = calibrate_sensors(gpio_pins, args.calibrate)
    except Exception:
        GPIO.cleanup()
        sys.exit(1)

    log_file = None
    try:
        log_file = open(args.log_file, "w", newline="")
        csv_writer = csv.writer(log_file)
        csv_writer.writerow(["Timestamp"] + [f"Sensor{i+1}" for i in range(len(gpio_pins))])
        log_file.flush()
    except Exception as exc:
        print(f"Error opening log file: {exc}", file=sys.stderr)
        print("Falling back to console logging.", file=sys.stderr)
        log_file = None

    last_picture_time = time.monotonic()

    try:
        while _running:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")
            sensor_states = []
            for i, pin in enumerate(gpio_pins):
                state = read_sensors([pin], thresholds[i], args.interval)
                sensor_states.append(state)

            if log_file:
                try:
                    csv_writer.writerow([timestamp] + sensor_states)
                    log_file.flush()
                except Exception as exc:
                    print(f"Error writing to log file: {exc}", file=sys.stderr)
            else:
                print(f"{timestamp} - {' '.join(map(str, sensor_states))}")

            if camera and time.monotonic() - last_picture_time >= args.picture_interval:
                capture_image(camera, timestamp.replace(" ", "_").replace(":", "-"))
                last_picture_time = time.monotonic()

            time.sleep(0.1)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        if log_file:
            try:
                log_file.close()
            except Exception:
                pass
        if camera:
            try:
                camera.stop()
            except Exception:
                pass
        GPIO.cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

