import os
import sys
import time
import signal
import select
import logging
import threading

import cv2
import numpy as np
import pygame.mixer
import RPi.GPIO as GPIO

import config
import face

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

BUTTON_PIN = 5
LOCK_PIN = 17
AUDIO_FREQUENCY = 48000
AUDIO_SIZE = -16
AUDIO_CHANNELS = 1
AUDIO_BUFFER = 1024
CAMERA_POLL_INTERVAL = 0.1

_shutdown_event = threading.Event()


def _signal_handler(signum, frame):
    logger.info('Signal %s received, shutting down...', signum)
    _shutdown_event.set()


def initialize_audio():
    try:
        pygame.mixer.init(AUDIO_FREQUENCY, AUDIO_SIZE, AUDIO_CHANNELS, AUDIO_BUFFER)
        logger.info('Audio initialized successfully.')
    except pygame.error as e:
        logger.error('Error initializing audio: %s', e)
        raise


def load_sounds():
    sounds = {}
    for name in ('welcome', 'wait', 'later'):
        try:
            sounds[name] = pygame.mixer.Sound(config.SOUNDS_PATH + name + '.wav')
        except pygame.error as e:
            logger.error('Error loading sound %s: %s', name, e)
            raise
    return sounds


def play_sound(sound, channel):
    try:
        channel.play(sound)
    except pygame.error as e:
        logger.error('Error playing sound: %s', e)


def is_button_up():
    try:
        return GPIO.input(BUTTON_PIN) == GPIO.HIGH
    except Exception as e:
        logger.error('Error reading button: %s', e)
        return False


def capture_image(camera):
    try:
        ret, image = camera.read()
        if not ret or image is None:
            logger.error('Failed to capture image from camera.')
            return None
        return cv2.cvtColor(image, cv2.COLOR_RGB2BGR)
    except Exception as e:
        logger.error('Error capturing image: %s', e)
        return None


def detect_and_recognize_face(image, face_model):
    try:
        gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        face_coords = face.detect_single(gray_image)
        if face_coords is None:
            logger.warning('No face detected.')
            return None, None

        x, y, w, h = face_coords
        cropped_face = face.crop(gray_image, x, y, w, h)
        resized_face = face.resize(cropped_face)

        label, confidence = face_model.predict(resized_face)
        return label, confidence
    except Exception as e:
        logger.error('Error during face recognition: %s', e)
        return None, None


def process_face_recognition(camera, face_model, channel_a, channel_b, channel_c, lock):
    image = capture_image(camera)
    if image is None:
        return

    label, confidence = detect_and_recognize_face(image, face_model)

    if label is not None and confidence is not None:
        logger.info('Predicted label: %s, Confidence: %.2f', label, confidence)

        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
            logger.info('Face recognized! Unlocking...')
            try:
                lock.unlock()
            except Exception as e:
                logger.error('Error unlocking: %s', e)
            play_sound(sounds['welcome'], channel_a)
        else:
            logger.info('Face not recognized.')
            play_sound(sounds['later'], channel_c)
            play_sound(sounds['wait'], channel_b)


def main():
    global sounds

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = None
    try:
        try:
            camera = config.get_camera()
            logger.info('Camera initialized successfully.')
        except Exception as e:
            logger.error('Error initializing camera: %s', e)
            return

        if not os.path.exists(config.TRAINING_FILE):
            logger.error('Training data file not found: %s', config.TRAINING_FILE)
            return

        face_model = cv2.face.EigenFaceRecognizer_create()
        face_model.read(config.TRAINING_FILE)
        logger.info('Face recognition model loaded successfully.')

        initialize_audio()
        sounds = load_sounds()

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(LOCK_PIN, GPIO.OUT)
        lock = Lock(LOCK_PIN)
        lock.lock()
        logger.info('GPIO initialized successfully.')

        channel_a = pygame.mixer.Channel(0)
        channel_b = pygame.mixer.Channel(1)
        channel_c = pygame.mixer.Channel(2)

        while not _shutdown_event.is_set():
            if is_button_up():
                process_face_recognition(camera, face_model, channel_a, channel_b, channel_c, lock)
            time.sleep(CAMERA_POLL_INTERVAL)

            if select.select([sys.stdin], [], [], 0.0)[0]:
                line = sys.stdin.readline().strip()
                if line == 'l':
                    logger.info('Locking door via manual input...')
                    try:
                        lock.lock()
                    except Exception as e:
                        logger.error('Error locking: %s', e)

    except Exception as e:
        logger.exception('An unexpected error occurred: %s', e)
    finally:
        logger.info('Cleaning up resources...')
        if camera is not None:
            try:
                camera.release()
            except Exception as e:
                logger.error('Error releasing camera: %s', e)
        try:
            GPIO.cleanup()
        except Exception as e:
            logger.error('Error cleaning up GPIO: %s', e)
        try:
            pygame.mixer.quit()
        except Exception as e:
            logger.error('Error quitting audio mixer: %s', e)
        logger.info('Program finished.')


if __name__ == '__main__':
    main()

