import argparse
import json
import logging
import os
import signal
import sys
import time
from datetime import datetime

import cv2
import face_recognition
import numpy as np
from picamera2 import Picamera2
from gpiozero import OutputDevice

DEFAULT_LOG_LEVEL = "INFO"
DEFAULT_MOTION_THRESHOLD = 500
DEFAULT_CONFIDENCE_THRESHOLD = 0.6
DEFAULT_DOOR_OPEN_DURATION = 5
DEFAULT_DEBOUNCE_INTERVAL = 2
DEFAULT_ENCODINGS_FILE = "encodings.json"
DEFAULT_RELAY_PIN = 17
CAMERA_WIDTH = 640
CAMERA_HEIGHT = 480
CAMERA_FRAMERATE = 10
MOTION_THRESHOLD = 10
FACE_DISTANCE_THRESHOLD = 0.6
DEBOUNCE_INTERVAL = 2
DOOR_OPEN_DURATION = 5
ENCODINGS_FILE = "encodings.json"
RELAY_PIN = 17

running = True
relay = None
picam2 = None


def signal_handler(sig, frame):
    global running
    running = False


def load_encodings(encodings_file):
    try:
        with open(encodings_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Encodings file not found: {encodings_file}. Starting with empty encodings.")
        return {}
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON in encodings file: {encodings_file}. Starting with empty encodings.")
        return {}
    except Exception as e:
        logging.error(f"Error loading encodings: {e}. Starting with empty encodings.")
        return {}


def save_encodings(encodings, encodings_file):
    try:
        with open(encodings_file, "w") as f:
            json.dump(encodings, f)
    except Exception as e:
        logging.error(f"Error saving encodings: {e}")


def capture_frame(picam2):
    try:
        return picam2.capture_array()
    except Exception as e:
        logging.error(f"Error capturing frame: {e}")
        return None


def detect_motion(frame1, frame2, motion_threshold):
    try:
        diff = cv2.absdiff(frame1, frame2)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray, motion_threshold, 255, cv2.THRESH_BINARY)
        return cv2.countNonZero(thresh)
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return 0


def recognize_face(frame, known_encodings, confidence_threshold):
    try:
        rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        face_locations = face_recognition.face_locations(rgb_frame)
        face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)

        for face_encoding in face_encodings:
            if not known_encodings:
                return None

            distances = face_recognition.face_distance(list(known_encodings.values()), face_encoding)
            best_match_index = np.argmin(distances)

            if distances[best_match_index] <= confidence_threshold:
                return list(known_encodings.keys())[best_match_index]
            else:
                return None
    except Exception as e:
        logging.error(f"Error recognizing face: {e}")
        return None


def activate_relay(relay, duration):
    try:
        relay.on()
        logging.info("Relay activated (GPIO17 HIGH).")
        time.sleep(duration)
        relay.off()
        logging.info("Relay deactivated (GPIO17 LOW).")
    except Exception as e:
        logging.error(f"Error controlling relay: {e}")
        try:
            relay.off()
        except Exception:
            pass


