    parser.add_argument("--log_level", default=DEFAULT_LOG_LEVEL, choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"], help="Logging level")
    parser.add_argument("--motion_threshold", type=int, default=DEFAULT_MOTION_THRESHOLD, help="Motion detection threshold (pixel count)")
    parser.add_argument("--confidence_threshold", type=float, default=DEFAULT_CONFIDENCE_THRESHOLD, help="Face recognition confidence threshold")
    parser.add_argument("--door_open_duration", type=int, default=DEFAULT_DOOR_OPEN_DURATION, help="Duration to keep the door open (seconds)")
    parser.add_argument("--debounce_interval", type=int, default=DEFAULT_DEBOUNCE_INTERVAL, help="Debounce interval (seconds)")
    parser.add_argument("--encodings_file", type=str, default=DEFAULT_ENCODINGS_FILE, help="Path to the encodings.json file")
    parser.add_argument("--relay_pin", type=int, default=DEFAULT_RELAY_PIN, help="GPIO pin for the relay (BCM numbering)")
    args = parser.parse_args()

    logging.basicConfig(level=args.log_level, format="%(asctime)s - %(levelname)s - %(message)s")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        relay = OutputDevice(args.relay_pin, active_high=True, initial_value=False)
        logging.info(f"Relay initialized on GPIO{args.relay_pin} (active-high).")
    except Exception as e:
        logging.error(f"Failed to initialize relay on GPIO{args.relay_pin}: {e}")
        sys.exit(1)

    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (CAMERA_WIDTH, CAMERA_HEIGHT)})
        picam2.configure(config)
        picam2.start()
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        if relay:
            relay.close()
        sys.exit(1)

    known_encodings = load_encodings(args.encodings_file)
    last_trigger_time = 0

    logging.info("Starting main loop...")
    previous_frame = None

    try:
        while running:
            frame = capture_frame(picam2)
            if frame is None:
                time.sleep(0.1)
                continue

            if previous_frame is not None:
                motion_score = detect_motion(previous_frame, frame, MOTION_THRESHOLD)
                if motion_score > args.motion_threshold:
                    logging.info(f"Motion detected (score={motion_score}).")
                    recognized_name = recognize_face(frame, known_encodings, args.confidence_threshold)

                    if recognized_name:
                        logging.info(f"Face recognized: {recognized_name}")
                        current_time = time.time()
                        if current_time - last_trigger_time > args.debounce_interval:
                            logging.info("Triggering door unlock.")
                            activate_relay(relay, args.door_open_duration)
                            last_trigger_time = current_time
                        else:
                            logging.info("Debounce interval active. Skipping trigger.")
                    else:
                        logging.info("Face unrecognized.")
            else:
                previous_frame = frame

            previous_frame = frame
            time.sleep(1 / CAMERA_FRAMERATE)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Cleaning up resources...")
        if picam2:
            try:
                picam2.stop()
            except Exception:
                pass
        if relay:
            try:
                relay.close()
            except Exception:
                pass
        logging.info("Exiting program.")


if __name__ == "__main__":
    main()

