import signal
import sys
import time
import numpy as np
import pyaudio
from gpiozero import Button

# --- Configuration -----------------------------------------------------------
BUTTON_PIN = 5
BOUNCE_TIME = 0.2
SAMPLE_RATE = 44100
BLOCK_SIZE = 1024
GAIN_MIN = 1.0
GAIN_MAX = 2.0

# --- Globals for cleanup -----------------------------------------------------
button = None
stream = None
pa = None
running = True


def cleanup():
    """Release audio and GPIO resources."""
    global stream, button, pa
    if stream is not None:
        try:
            if stream.is_active():
                stream.stop_stream()
            stream.close()
        except Exception:
            pass
        stream = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None
    if pa is not None:
        try:
            pa.terminate()
        except Exception:
            pass
        pa = None


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global running
    running = False


def apply_distortion(audio_data, gain):
    """Apply gain and tanh soft-clipping distortion to a float32 block."""
    return np.tanh(audio_data * gain)


def process_audio_data(indata, gain):
    """PyAudio callback: process one block and write the result to the output."""
    try:
        if indata is None or indata.size == 0:
            return
        if indata.dtype != np.float32:
            indata = indata.astype(np.float32)
        processed = apply_distortion(indata, gain)
        if outdata is not None:
            outdata[:] = processed
    except Exception as exc:
        print(f"Audio processing error: {exc}", file=sys.stderr)


def main():
    global button, stream, pa

    # --- GPIO button setup (active-low with pull-up) -------------------------
    try:
        button = Button(BUTTON_PIN, pull_up=True, bounce_time=BOUNCE_TIME)
    except Exception as exc:
        print(f"Failed to initialize GPIO button on pin {BUTTON_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- PyAudio setup -------------------------------------------------------
    try:
        pa = pyaudio.PyAudio()
    except Exception as exc:
        print(f"Failed to initialize PyAudio: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    gain = GAIN_MIN
    try:
        stream = pa.open(
            format=pyaudio.paFloat32,
            channels=1,
            rate=SAMPLE_RATE,
            input=True,
            output=True,
            frames_per_buffer=BLOCK_SIZE,
            stream_callback=lambda indata, outdata, frames, time_info, status:
                process_audio_data(indata, gain),
        )
    except Exception as exc:
        print(f"Failed to open audio stream: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    stream.start_stream()

    # --- Signal handlers -----------------------------------------------------
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Audio processing running. Press Ctrl+C to exit.")

    # --- Main loop: toggle gain on button press ------------------------------
    try:
        while running:
            if button.is_pressed:
                gain = GAIN_MAX if gain == GAIN_MIN else GAIN_MIN
                print(f"Gain toggled to {gain}")
                # Wait for release to avoid rapid toggling
                while button.is_pressed and running:
                    time.sleep(0.05)
            time.sleep(0.01)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        cleanup()
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

