import asyncio
import logging
import signal
import threading
import time
from typing import Callable, Optional

import numpy as np

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class WebSocketHandler:
    """Placeholder WebSocket handler exposing connection state and broadcast."""

    def __init__(self):
        self._connections = 0
        self._lock = threading.Lock()

    def has_connections(self) -> bool:
        with self._lock:
            return self._connections > 0

    def broadcast(self, data: bytes) -> None:
        with self._lock:
            if self._connections > 0:
                logger.debug("Broadcasting %d bytes to %d clients", len(data), self._connections)

    def add_connection(self) -> None:
        with self._lock:
            self._connections += 1

    def remove_connection(self) -> None:
        with self._lock:
            if self._connections > 0:
                self._connections -= 1


def convert_jpeg_to_frame(jpeg_data: bytes) -> Optional[np.ndarray]:
    """Decode JPEG bytes into a NumPy frame using the driver library's imdecode.

    The driver library expects a contiguous buffer; we extract the raw JPEG
    bytes between SOI (0xFF 0xD8) and EOI (0xFF 0xD9) markers.
    """
    if jpeg_data is None or len(jpeg_data) < 2:
        logger.error("Invalid JPEG data: too short")
        return None

    try:
        start = jpeg_data.find(b'\xff\xd8')
        end = jpeg_data.find(b'\xff\xd9')
        if start == -1 or end == -1:
            logger.error("JPEG markers not found in data")
            return None
        if end <= start:
            logger.error("Invalid JPEG marker positions")
            return None

        raw = jpeg_data[start:end + 2]
        if not raw:
            logger.error("Empty JPEG buffer after extraction")
            return None

        frame = imdecode(raw, 1)
        if frame is None or frame.size == 0:
            logger.error("imdecode returned empty frame")
            return None
        return frame
    except Exception as e:
        logger.error("Error converting JPEG to frame: %s", e)
        return None


def detect_motion(prev_frame: np.ndarray, curr_frame: np.ndarray) -> bool:
    """Detect motion between two frames using absolute difference."""
    if prev_frame is None or curr_frame is None:
        return False
    if prev_frame.shape != curr_frame.shape:
        logger.warning("Frame shape mismatch: prev=%s curr=%s", prev_frame.shape, curr_frame.shape)
        return False
    diff = np.abs(prev_frame.astype(np.int16) - curr_frame.astype(np.int16))
    motion_pixels = int(np.count_nonzero(diff > 25))
    return motion_pixels > 0


def capture_loop(
    camera,
    loop: asyncio.AbstractEventLoop,
    frame_queue: asyncio.Queue,
    motion_callback: Optional[Callable[[np.ndarray], None]],
    stop_event: threading.Event,
):
