import io
import logging
import signal
import threading
from typing import Callable, Optional

import numpy as np
import cv2
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Thread-safe buffer for raw camera streaming data."""

    def __init__(self, camera: Picamera2, websocket_manager: object):
        if not isinstance(camera, Picamera2):
            raise TypeError("camera must be a Picamera2 instance")
        if websocket_manager is None:
            raise ValueError("websocket_manager cannot be None")

        self._camera = camera
        self._websocket_manager = websocket_manager
        self._buffer = io.BytesIO()
        self._lock = threading.Lock()
        self._started = False

    def start(self) -> None:
        """Start the camera and begin streaming."""
        try:
            self._camera.start_recording(MJPEGEncoder(), Output(self))
            self._started = True
            logger.info("Camera streaming started.")
        except Exception as e:
            logger.error(f"Failed to start camera streaming: {e}")
            raise

    def stop(self) -> None:
        """Stop the camera streaming."""
        try:
            if self._started:
                self._camera.stop_recording()
                self._started = False
                logger.info("Camera streaming stopped.")
        except Exception as e:
            logger.error(f"Failed to stop camera streaming: {e}")

    def write(self, data: bytes) -> int:
        """Write data to the buffer, detecting complete JPEG frames.

        Returns the number of bytes written (always len(data)).
        """
        if not isinstance(data, (bytes, bytearray)):
            raise TypeError("data must be bytes or bytearray")

        with self._lock:
            self._buffer.write(data)
            buffer_pos = self._buffer.tell()
            self._buffer.seek(0)
            complete_data = self._buffer.read()
            self._buffer.seek(buffer_pos)

            # Detect JPEG boundary (0xFF 0xD8)
            if b'\xff\xd8' in complete_data:
                frames = complete_data.split(b'\xff\xd8')
                # Keep the last fragment in the buffer (incomplete)
                self._buffer.seek(0)
                self._buffer.truncate()
                self._buffer.write(frames[-1])

                for frame_data in frames[:-1]:
                    if self._websocket_manager.has_connections():
                        try:
                            self._websocket_manager.send_frame(frame_data)
                        except Exception as e:
                            logger.error(f"Failed to send frame: {e}")

        return len(data)

    def flush(self) -> None:
        """Flush any remaining data in the buffer."""
        with self._lock:
            if self._buffer.tell() > 0:
                remaining = self._buffer.read()
                if remaining and self._websocket_manager.has_connections():
                    try:
                        self._websocket_manager.send_frame(remaining)
                    except Exception as e:
                        logger.error(f"Failed to send remaining frame: {e}")
                self._buffer.seek(0)
                self._buffer.truncate()


class MotionDetectionBuffer:
    """Thread-safe buffer for motion detection."""

    def __init__(self, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")

        self._detect_motion = detect_motion_function
        self._buffer = io.BytesIO()
        self._lock = threading.Lock()
        self._previous_frame: Optional[bytes] = None
        self._current_frame: Optional[bytes] = None

    def _convert_to_opencv(self, frame_data: bytes) -> Optional[np.ndarray]:
        """Convert JPEG bytes to an OpenCV BGR image."""
        try:
            data = np.frombuffer(frame_data, dtype=np.uint8)
            image = cv2.imdecode(data, cv2.IMREAD_COLOR)
            if image is None:
                logger.error("Failed to decode frame data.")
                return None
            return image
        except Exception as e:
            logger.error(f"Error converting frame data: {e}")
            return None

    def write(self, data: bytes) -> int:
        """Write data to the buffer, detecting complete JPEG frames for motion detection."""
        if not isinstance(data, (bytes, bytearray)):
            raise TypeError("data must be bytes or bytearray")

        with self._lock:
            self._buffer.write(data)
            buffer_pos = self._buffer.tell()
            self._buffer.seek(0)
            complete_data = self._buffer.read()
            self._buffer.seek(buffer_pos)

            # Detect JPEG boundary (0xFF 0xD8)
            if b'\xff\xd8' in complete_data:
                frames = complete_data.split(b'\xff\xd8')
                # Keep the last fragment in the buffer (incomplete)
                self._buffer.seek(0)
                self._buffer.truncate()
                self._buffer.write(frames[-1])

                for frame_data in frames[:-1]:
                    if frame_data:
                        opencv_image = self._convert_to_opencv(frame_data)
                        if opencv_image is not None:
                            self._previous_frame = self._current_frame
                            self._current_frame = frame_data
                            if self._previous_frame is not None:
                                try:
                                    self._detect_motion(
                                        self._convert_to_opencv(self._previous_frame),
                                        opencv_image,
                                    )
                                except Exception as e:
                                    logger.error(f"Error during motion detection: {e}")

        return len(data)

    def flush(self) -> None:
        """Flush any remaining data in the buffer."""
        with self._lock:
            if self._buffer.tell() > 0:
                remaining = self._buffer.read()
                if remaining:
                    self._current_frame = remaining
                self._buffer.seek(0)
                self._buffer.truncate()


class CameraController:
    """Manages the Raspberry Pi camera and streaming buffers."""

    def __init__(self, camera_stream_buffer: CameraStreamBuffer, motion_detection_buffer: MotionDetectionBuffer):
        if not isinstance(camera_stream_buffer, CameraStreamBuffer):
            raise TypeError("camera_stream_buffer must be a CameraStreamBuffer instance")
        if not isinstance(motion_detection_buffer, MotionDetectionBuffer):
            raise TypeError("motion_detection_buffer must be a MotionDetectionBuffer instance")

        self._camera_stream_buffer = camera_stream_buffer
        self._motion_detection_buffer = motion_detection_buffer
        self._camera: Optional[Picamera2] = None
        self._lock = threading.Lock()
        self._running = False

    def start(self) -> None:
        """Initialize and start the camera and streaming buffers."""
        try:
            self._camera = Picamera2()
            # Configure for 64‑value setting and 10 fps as per V2 camera module specs
            config = self._camera.create_video_configuration(
                main={"size": (640, 480), "format": "RGB888"},
                controls={"FrameRate": 10.0},
            )
            self._camera.configure(config)
            self._camera.start()
            self._running = True

            self._camera_stream_buffer.start()
            self._motion_detection_buffer.start()
            logger.info("CameraController started.")
        except Exception as e:
            logger.error(f"Failed to start CameraController: {e}")
            self.stop()
            raise

    def stop(self) -> None:
        """Stop the camera and streaming buffers, flushing any remaining data."""
        with self._lock:
            if not self._running and self._camera is None:
                return

            self._running = False

            if self._camera is not None:
                try:
                    self._camera.stop()
                except Exception as e:
                    logger.error(f"Error stopping camera: {e}")
                finally:
                    self._camera = None

            if self._camera_stream_buffer is not None:
                self._camera_stream_buffer.stop()
            if self._motion_detection_buffer is not None:
                self._motion_detection_buffer.stop()

            if self._camera_stream_buffer is not None:
                self._camera_stream_buffer.flush()
            if self._motion_detection_buffer is not None:
                self._motion_detection_buffer.flush()

            logger.info("CameraController stopped.")


def main():
    logging.basicConfig(level=logging.INFO)

    # Placeholder websocket manager with stub methods for demonstration
    class WebsocketManagerStub:
        def has_connections(self) -> bool:
            return True

        def send_frame(self, frame_data: bytes) -> None:
            pass

    websocket_manager = WebsocketManagerStub()

    def dummy_detect_motion(prev_frame: np.ndarray, curr_frame: np.ndarray) -> None:
        pass

    picam2 = Picamera2()
    stream_buffer = CameraStreamBuffer(picam2, websocket_manager)
    motion_buffer = MotionDetectionBuffer(dummy_detect_motion)
    controller = CameraController(stream_buffer, motion_buffer)

    def signal_handler(signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        controller.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        controller.start()
        # Keep main thread alive; in production this would be an event loop
        signal.pause()
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        controller.stop()


if __name__ == "__main__":
    main()

