import io
import logging
import numpy as np

logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffers an MJPEG stream and flushes complete frames to an output sink.

    Designed for use with the V2 camera module on Raspberry Pi 4B.
    """

    def __init__(self, driver, output=None):
        self.driver = driver
        self.output = output
        self.buf = io.BytesIO()
        self._frame_complete = False

    def _is_frame_complete(self):
        """Return True when the current configuration indicates a complete frame."""
        try:
            config = self.driver._video_configuration
            return (
                config
                and config.get("encode", {}).get("metadata")
                and config["encode"]["metadata"].get("encodeMetadata")
                and config["encode"]["metadata"]["encodeMetadata"].get("completeFrame")
            )
        except Exception as exc:
            logger.warning("Could not read encode metadata: %s", exc)
            return False

    def write(self, data):
        """Append *data* to the buffer and flush complete frames.

        I/O errors during flush are logged but never raised.
        """
        try:
            self.buf.write(data)
            self.buf.seek(0, io.SEEK_END)
            frame_end = self.buf.tell()

            complete = self._is_frame_complete()
            if complete and frame_end > 0:
                self.buf.seek(0)
                frame_data = self.buf.read(frame_end)
                try:
                    # H.264 frame type 1 == I-frame; skip those for this buffer.
                    if self.driver._get_frame_type(frame_data) != 1:
                        if self.output:
                            self.output.write(frame_data)
                        self.buf = io.BytesIO()
                except Exception as exc:
                    logger.error("Error processing frame: %s", exc)
                    self.buf = io.BytesIO()
        except Exception as exc:
            logger.error("Error writing to buffer: %s", exc)

    def flush(self):
        """Flush any remaining buffered data to the output sink."""
        if self.buf.tell() > 0:
            try:
                remaining = self.buf.getvalue()
                if self.output and remaining:
                    self.output.write(remaining)
            except Exception as exc:
                logger.error("Error flushing buffer: %s", exc)
            finally:
                self.buf = io.BytesIO()


class MotionDetectionBuffer:
    """Buffers an MJPEG stream and invokes a callback on each decoded frame.

    Designed for use with the V2 camera module on Raspberry Pi 4B.
    """

    def __init__(self, driver, callback):
        self.driver = driver
        self.callback = callback
        self.buf = io.BytesIO()
        self._prev_frame = None

    def _convert_to_array(self, data):
        """Convert raw bytes to a NumPy array of unsigned bytes."""
        return np.frombuffer(data, dtype=np.uint8)

    def write(self, data):
        """Append *data* to the buffer and decode complete JPEG frames.

        Decode and callback errors are logged but never raised.
        """
        try:
            self.buf.write(data)
            self.buf.seek(0, io.SEEK_END)
            end = self.buf.tell()

            # MJPEG marker for start of image: 0xFF 0xD8
            marker = b'\xff\xd8'
            while True:
                pos = self.buf.getvalue().find(marker, 0, end)
                if pos == -1:
                    break
                # Found a JPEG boundary; read up to the next boundary or end.
                self.buf.seek(pos)
                chunk = self.buf.read(end - pos)
                if not chunk:
                    break

                try:
                    arr = self._convert_to_array(chunk)
                    frame = self.driver.imdecode(arr)
                    if frame is None:
                        logger.warning("imdecode returned None; skipping frame.")
                        continue

                    if self._prev_frame is not None:
                        try:
                            self.callback(self._prev_frame, frame)
                        except Exception as exc:
                            logger.error("Callback error: %s", exc)

                    self._prev_frame = frame
                except Exception as exc:
                    logger.error("Error decoding frame: %s", exc)

                # Reset buffer to remaining bytes after the processed chunk.
                remaining = self.buf.getvalue()[end - pos + len(chunk):]
                self.buf = io.BytesIO()
                self.buf.write(remaining)
                end = self.buf.tell()
        except Exception as exc:
            logger.error("Error writing to motion buffer: %s", exc)

