import sys
import time
import signal
import cv2
import select
import config
import drivers
from drivers import Sound

# Constants
BUTTON_PIN = 17
LOCK_PIN = 18
POSITIVE_LABEL = config.POSITIVE_LABEL
POSITIVE_THRESHOLD = config.POSITIVE_THRESHOLD
TRAINING_FILE = config.TRAINING_FILE
SOUND_WELCOME = config.SOUND_WELCOME
SOUND_WAIT = config.SOUND_WAIT
SOUND_LATER = config.SOUND_LATER
CAMERA_INDEX = config.CAMERA_INDEX
AUDIO_SAMPLE_RATE = 48000
LOOP_DELAY = 0.1

# Global state
_running = True
_sound_welcome = None
_sound_wait = None
_sound_later = None
_door = None
_camera = None
_face_model = None
_audio_mixer = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _door, _camera, _audio_mixer
    if _door is not None:
        try:
            _door.cleanup()
        except Exception:
            pass
    if _camera is not None:
        try:
            _camera.close()
        except Exception:
            pass
    if _audio_mixer is not None:
        try:
            _audio_mixer.stop()
        except Exception:
            pass


def _load_sounds():
    global _sound_welcome, _sound_wait, _sound_later
    for name, path in (('welcome', SOUND_WELCOME), ('wait', SOUND_WAIT), ('later', SOUND_LATER)):
        try:
            sound = Sound(path)
            sound.load()
            if name == 'welcome':
                _sound_welcome = sound
            elif name == 'wait':
                _sound_wait = sound
            else:
                _sound_later = sound
        except Exception as e:
            print(f"Error loading sound {name}: {e}", file=sys.stderr)
            raise


def _init_hardware():
    global _door, _camera, _audio_mixer
    try:
        _door = drivers.Door(BUTTON_PIN, LOCK_PIN)
    except Exception as e:
        print(f"Error initializing door driver: {e}", file=sys.stderr)
        raise
    try:
        _camera = cv2.VideoCapture(CAMERA_INDEX)
        if not _camera.isOpened():
            raise RuntimeError("Could not open camera")
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        raise
    try:
        _audio_mixer = drivers.AudioMixer(AUDIO_SAMPLE_RATE)
        _audio_mixer.start()
    except Exception as e:
        print(f"Error initializing audio mixer: {e}", file=sys.stderr)
        raise


def _init_face_recognition():
    global _face_model
    try:
        _face_model = cv2.face.EigenFaceRecognizer_create()
        _face_model.read(TRAINING_FILE)
    except Exception as e:
        print(f"Error loading face recognition model: {e}", file=sys.stderr)
        raise


def _process_face_recognition():
    try:
        ret, image = _camera.read()
        if not ret or image is None:
            return False
        gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        face_coords = _face_model.detectSingleFace(gray_image)
        if face_coords is None:
            return False
        x, y, w, h = face_coords
        cropped_face = gray_image[y:y + h, x:x + w]
        resized_face = cv2.resize(cropped_face, (100, 100))
        label, confidence = _face_model.predict(resized_face)
        print(f'Predicted label: {label}, Confidence: {confidence}')
        if label == POSITIVE_LABEL and confidence < POSITIVE_THRESHOLD:
            print('Recognized face! Unlocking...')
            _door.unlock()
            _sound_welcome.play()
            return True
        else:
            print('Face not recognized.')
            _sound_wait.play()
            return True
    except Exception as e:
        print(f"Error during face recognition: {e}", file=sys.stderr)
        return False


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        _load_sounds()
        _init_hardware()
        _init_face_recognition()
        print('Running Lock...')
        while _running:
            if _door.is_button_up() or _process_face_recognition():
                _door.lock()
            readable, _, _ = select.select([sys.stdin], [], [], LOOP_DELAY)
            if readable:
                break
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        _cleanup()
        print('Exiting Lock')


if __name__ == '__main__':
    main()

