import signal
import sys
import threading
import time
import logging

import RPi.GPIO as GPIO
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

LED_PINS = [17, 18, 23, 27, 22]
LCD_ADDR = 0x27
I2C_BUS = 1
UPDATE_INTERVAL = 1.0
LED_ON_TIME = 1.0

running = True
lcd_lock = threading.Lock()


def signal_handler(sig, frame):
    global running
    logging.info('Shutdown signal received.')
    running = False


class LCDController:
    def __init__(self, bus_num=I2C_BUS, addr=LCD_ADDR):
        self.addr = addr
        self.bus = None
        try:
            self.bus = SMBus(bus_num)
            self._init_lcd()
            logging.info(f'LCD initialized at 0x{addr:02X} on bus {bus_num}.')
        except Exception as e:
            logging.error(f'Failed to initialize LCD: {e}')
            self.bus = None
            raise

    def _write_byte(self, byte):
        if not self.bus:
            raise RuntimeError('LCD bus not initialized')
        self.bus.write_byte(self.addr, byte)

    def _write_nibble(self, nibble, rs):
        en_pulse = i2c_msg.write(self.addr, [nibble | 0x04 | rs, 0x04, 0x00])
        self.bus.i2c_rdwr(en_pulse)

    def _send_byte(self, byte, rs=0):
        self._write_nibble(byte & 0xF0, rs)
        self._write_nibble((byte << 4) & 0xF0, rs)
        time.sleep(0.001)

    def _send_command(self, cmd):
        self._send_byte(cmd, rs=0)

    def _send_data(self, data):
        self._send_byte(data, rs=1)

    def _init_lcd(self):
        time.sleep(0.05)
        self._send_command(0x33)
        self._send_command(0x32)
        self._send_command(0x28)
        self._send_command(0x0C)
        self._send_command(0x06)
        self._send_command(0x01)
        time.sleep(0.002)

    def display_string(self, text):
        with lcd_lock:
            try:
                self._send_command(0x80)
                for char in text[:16]:
                    self._send_data(ord(char))
            except Exception as e:
                logging.error(f'LCD write error: {e}')

    def clear(self):
        with lcd_lock:
            try:
                self._send_command(0x01)
                time.sleep(0.002)
            except Exception as e:
                logging.error(f'LCD clear error: {e}')

    def close(self):
        with lcd_lock:
            try:
                self.clear()
                self._write_byte(0x08)
            except Exception:
                pass
            if self.bus:
                self.bus.close()
                self.bus = None


def get_cpu_usage():
    try:
        with open('/proc/stat', 'r') as f:
            line = f.readline()
        parts = line.split()
        if len(parts) < 5:
            return 0.0
        vals = list(map(int, parts[1:6]))
        total = sum(vals)
        idle = vals[3]
        return max(0.0, 100.0 - (idle * 100.0 / total) if total > 0 else 0.0)
    except Exception as e:
        logging.error(f'Error reading CPU usage: {e}')
        return 0.0


def get_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except Exception as e:
        logging.error(f'Error reading CPU temperature: {e}')
        return 0.0


def activate_led(cls):
    if not (0 <= cls < len(LED_PINS)):
        logging.error(f'Invalid class index: {cls}')
        return
    pin = LED_PINS[cls]
    try:
        GPIO.output(pin, GPIO.HIGH)
        time.sleep(LED_ON_TIME)
        GPIO.output(pin, GPIO.LOW)
    except Exception as e:
        logging.error(f'Error controlling LED on GPIO{pin}: {e}')


def update_lcd(lcd):
    while running:
        try:
            cpu_usage = get_cpu_usage()
            cpu_temp = get_cpu_temp()
            line1 = f'CPU  : {cpu_usage:5.1f}%'
            line2 = f'Temp : {cpu_temp:5.1f}C'
            lcd.display_string(line1)
            lcd.display_string(line2)
        except Exception as e:
            logging.error(f'Error updating LCD: {e}')
        time.sleep(UPDATE_INTERVAL)


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    GPIO.setmode(GPIO.BCM)
    for pin in LED_PINS:
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

    lcd = None
    lcd_thread = None
    try:
        lcd = LCDController()
        lcd_thread = threading.Thread(target=update_lcd, args=(lcd,), daemon=True)
        lcd_thread.start()

        while running:
            cls = int(input('Enter class index (0-4): '))
            if not (0 <= cls < len(LED_PINS)):
                logging.error(f'Invalid class index: {cls}')
                continue
            activate_led(cls)
    except Exception as e:
        logging.error(f'Unexpected error: {e}')
    finally:
        running = False
        if lcd_thread and lcd_thread.is_alive():
            lcd_thread.join(timeout=2.0)
        lcd.close()
        GPIO.cleanup()
        logging.info('Program finished.')


if __name__ == '__main__':
    main()

