import signal
import sys
import smbus2

# Thermal zone file path
THERMAL_ZONE_FILE = '/sys/class/thermal/thermal_zone0/temp'

# Global handle for cleanup
i2c_bus = None

def cleanup(signum=None, frame=None):
    """Release I2C bus resources on exit or signal."""
    global i2c_bus
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass
        i2c_bus = None
    if signum is not None:
        sys.exit(0)

def read_temperature():
    """Read temperature from the thermal zone file and print in Celsius."""
    try:
        with open(THERMAL_ZONE_FILE, 'r') as f:
            raw = f.read().strip()
        millideg = int(raw)
        celsius = millideg / 1000.0
        print(f"Temperature: {celsius:.2f} °C")
    except FileNotFoundError:
        print("Error: Thermal zone file not found. Is this running on a Raspberry Pi?")
    except PermissionError:
        print("Error: Permission denied reading thermal zone. Run with appropriate privileges.")
    except ValueError:
        print("Error: Could not parse temperature value from file.")
    except OSError as e:
        print(f"Error: OS error reading temperature: {e}")

def main():
    global i2c_bus

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize I2C bus 1 for potential future use (bus checks only)
    try:
        i2c_bus = smbus2.SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C via raspi-config.")
        sys.exit(1)
    except PermissionError:
        print("Error: Permission denied accessing I2C bus. Run with i2c privileges.")
        sys.exit(1)
    except OSError as e:
        print(f"Error: Failed to initialize I2C bus 1: {e}")
        sys.exit(1)

    try:
        while True:
            read_temperature()
            time.sleep(2)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

