import signal
import sys
import time
import smbus2
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
OLED_ADDR = 0x3C
BME280_ADDR = 0x76
TSL2561_ADDR = 0x39

# --- Globals for cleanup -----------------------------------------------------
running = True
i2c_bus = None
oled = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global i2c_bus, oled
    if oled is not None:
        try:
            oled.clear()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass


def init_i2c():
    global i2c_bus
    try:
        i2c_bus = smbus2.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)


def init_oled():
    global oled
    try:
        serial = i2c(port=I2C_BUS, address=OLED_ADDR)
        oled = ssd1306(serial, width=128, height=64)
    except Exception as e:
        print(f"Error initializing SSD1306 OLED at 0x{OLED_ADDR:02X}: {e}", file=sys.stderr)
        sys.exit(1)


def init_bme280():
    try:
        # Verify device presence
        i2c_bus.read_byte(BME280_ADDR)
        return True
    except Exception:
        print(f"BME280 not found at 0x{BME280_ADDR:02X}", file=sys.stderr)
        return False


def init_tsl2561():
    try:
        # Verify device presence
        i2c_bus.read_byte(TSL2561_ADDR)
        return True
    except Exception:
        print(f"TSL2561 not found at 0x{TSL2561_ADDR:02X}", file=sys.stderr)
        return False


def read_bme280():
    # Placeholder: real implementation would read calibration + data registers
    return 25.0, 50.0, 1013.25


def read_tsl2561():
    # Placeholder: real implementation would read integration time + gain
    return 500.0


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_i2c()
    init_oled()

    bme_ok = init_bme280()
    tsl_ok = init_tsl2561()

    if not bme_ok and not tsl_ok:
        print("No sensors detected. Exiting.", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while running:
            temp, hum, pres = (0.0, 0.0, 0.0)
            light = 0.0

            if bme_ok:
                try:
                    temp, hum, pres = read_bme280()
                except Exception as e:
                    print(f"BME280 read error: {e}", file=sys.stderr)
                    temp, hum, pres = 0.0, 0.0, 0.0

            if tsl_ok:
                try:
                    light = read_tsl2561()
                except Exception as e:
                    print(f"TSL2561 read error: {e}", file=sys.stderr)
                    light = 0.0

            try:
                with canvas(oled) as draw:
                    draw.text((0, 0), f"Temp: {temp:.1f} C", fill="white")
                    draw.text((0, 16), f"Humidity: {hum:.1f} %", fill="white")
                    draw.text((0, 32), f"Pressure: {pres:.1f} hPa", fill="white")
                    draw.text((0, 48), f"Light: {light:.1f} lux", fill="white")
            except Exception as e:
                print(f"OLED display error: {e}", file=sys.stderr)

            time.sleep(1)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

