import time
import signal
import sys
import smbus
import adafruit_dht
from adafruit_character_lcd.character_lcd_i2c import Character_LCD_I2C

# --- Configuration ---
I2C_BUS = 1
LCD_ADDR = 0x27
LCD_COLS = 16
LCD_ROWS = 2
DHT_PIN = 4
UPDATE_INTERVAL = 2.0

# --- Globals for cleanup ---
lcd = None
dht_sensor = None
running = True

def cleanup(signum=None, frame=None):
    """Clear the LCD and release resources on exit."""
    global lcd, dht_sensor, running
    running = False
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def init_lcd():
    """Initialize the I2C bus and LCD; return the LCD object or None on failure."""
    global lcd
    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}")
        return None
    try:
        lcd = Character_LCD_I2C(bus, LCD_ADDR, LCD_COLS, LCD_ROWS)
        lcd.clear()
        return lcd
    except OSError as e:
        print(f"Error: LCD not found at address 0x{LCD_ADDR:02X} on bus {I2C_BUS}: {e}")
        return None
    except Exception as e:
        print(f"Error: LCD initialization failed: {e}")
        return None

def init_dht():
    """Initialize the DHT22 sensor; return the sensor object or None on failure."""
    global dht_sensor
    try:
        dht_sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        return dht_sensor
    except Exception as e:
        print(f"Error: DHT22 initialization failed on GPIO{DHT_PIN}: {e}")
        return None

def read_sensor_data():
    """Read temperature and humidity from the DHT22 sensor.
    Returns (temperature, humidity) or (None, None) on failure."""
    global dht_sensor
    if dht_sensor is None:
        return None, None
    try:
        temperature = dht_sensor.temperature
        humidity = dht_sensor.humidity
        if temperature is None or humidity is None:
            print("Warning: DHT22 returned None for temperature or humidity.")
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT22 commonly throws checksum or timing errors; treat as transient
        print(f"Warning: DHT22 read error (transient): {e}")
        return None, None
    except OSError as e:
        print(f"Error: DHT22 I/O error: {e}")
        return None, None
    except Exception as e:
        print(f"Error: unexpected DHT22 failure: {e}")
        return None, None

def display_data(lcd_obj, temperature, humidity):
    """Display temperature and humidity on the 16x2 LCD."""
    if lcd_obj is None:
        return
    try:
        line1 = f"Temp: {temperature:.1f} C"
        line2 = f"Humidity: {humidity:.1f}%"
        lcd_obj.clear()
        lcd_obj.message = line1 + "\n" + line2
    except OSError as e:
        print(f"Error: LCD I/O error: {e}")
    except Exception as e:
        print(f"Error: LCD display error: {e}")

def main():
    """Main loop: read sensor and update LCD every 2 seconds."""
    global lcd, dht_sensor

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    lcd = init_lcd()
    if lcd is None:
        print("Fatal: LCD initialization failed. Exiting.")
        sys.exit(1)

    dht_sensor = init_dht()
    if dht_sensor is None:
        print("Warning: DHT22 initialization failed. LCD will display error message.")

    try:
        while running:
            temperature, humidity = read_sensor_data()
            if temperature is not None and humidity is not None:
                display_data(lcd, temperature, humidity)
            else:
                # Display error state on LCD
                try:
                    lcd.clear()
                    lcd.message = "Sensor Error\nRetrying..."
                except Exception:
                    pass
            time.sleep(UPDATE_INTERVAL)
    except Exception as e:
        print(f"Fatal error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

