import smbus
import time
import signal
import sys
import math
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

TSL2561_ADDR = 0x29
TSL2561_CMD = 0x80
TSL2561_REG_CONTROL = 0x00
TSL2561_REG_TIMING = 0x01
TSL2561_REG_DATA0LOW = 0x0C
TSL2561_REG_DATA1LOW = 0x0E
TSL2561_REG_ID = 0x12
TSL2561_ID = 0x50
TSL2561_INTEGRATIONTIME_101MS = 0x01
TSL2561_GAIN_1X = 0x00
TSL2561_POWERON = 0x03

running = True
i2c_bus = None
oled_display = None


def signal_handler(sig, frame):
    global running
    running = False


def tsl2561_read_word(bus, reg):
    bus.write_byte_data(TSL2561_ADDR, TSL2561_CMD | reg, 0x00)
    time.sleep(0.005)
    data = bus.read_i2c_block_data(TSL2561_ADDR, TSL2561_CMD | (reg + 1), 2)
    return (data[1] << 8) | data[0]


def tsl2561_init(bus):
    try:
        id_ = tsl2561_read_word(bus, TSL2561_REG_ID)
        if id_ != TSL2561_ID:
            print(f"Warning: TSL2561 ID mismatch: 0x{id_:02X} (expected 0x{TSL2561_ID:02X})")
        bus.write_byte_data(TSL2561_ADDR, TSL2561_CMD | TSL2561_REG_CONTROL, TSL2561_POWERON)
        bus.write_byte_data(TSL2561_ADDR, TSL2561_CMD | TSL2561_REG_TIMING, TSL2561_INTEGRATIONTIME_101MS | TSL2561_GAIN_1X)
        time.sleep(0.18)
        return True
    except OSError as e:
        print(f"Error initializing TSL2561: {e}")
        return False


def tsl2561_read_lux(bus):
    try:
        ch0 = tsl2561_read_word(bus, TSL2561_REG_DATA0LOW)
        ch1 = tsl2561_read_word(bus, TSL2561_REG_DATA1LOW)
    except OSError as e:
        print(f"Error reading TSL2561 data: {e}")
        return None

    if ch0 == 0:
        return 0.0

    ratio = ch1 / ch0
    if ratio <= 0.5:
        lux = 0.0304 * ch0 - 0.062 * ch0 * (ratio ** 1.4)
    elif ratio <= 0.61:
        lux = 0.0224 * ch0 - 0.031 * ch1
    elif ratio <= 0.80:
        lux = 0.0128 * ch0 - 0.0153 * ch1
    elif ratio <= 1.3:
        lux = 0.00146 * ch0 - 0.00112 * ch1
    else:
        lux = 0.0

    return max(0.0, lux)


def cleanup():
    global i2c_bus, oled_display
    if oled_display is not None:
        try:
            oled_display.clear()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.write_byte_data(TSL2561_ADDR, TSL2561_CMD | TSL2561_REG_CONTROL, 0x00)
        except OSError:
            pass
        try:
            i2c_bus.close()
        except Exception:
            pass


def main():
    global i2c_bus, oled_display

    signal.signal(signal.SIGINT, signal_handler)

    try:
        i2c_bus = smbus.SMBus(1)
    except OSError as e:
        print(f"Error initializing I2C bus 1: {e}")
        sys.exit(1)

    if not tsl2561_init(i2c_bus):
        cleanup()
        sys.exit(1)

    try:
        serial = i2c(port=1, address=0x3C)
        oled_display = ssd1306(serial)
    except Exception as e:
        print(f"Error initializing SSD1306 OLED: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            lux = tsl2561_read_lux(i2c_bus)
            if lux is not None:
                brightness = int(min(max(lux / 1000.0, 0), 255))
                with canvas(oled_display) as draw:
                    draw.text((0, 0), f"Lux: {lux:.2f}", fill="white")
                    draw.text((0, 16), f"Brightness: {brightness}", fill="white")
            time.sleep(1)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

