import os
import sys
import time
import signal
import logging
from typing import List, Tuple, Optional

import numpy as np
from PIL import Image, ImageSequence

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    from lib.oled.SSD1306 import SSD1306
except ImportError:
    SSD1306 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

I2C_BUS = 1
I2C_ADDR = 0x3C
WIDTH = 128
HEIGHT = 64

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info("Shutdown signal received.")

def init_display() -> Optional[SSD1306]:
    if SSD1306 is None:
        logger.error("SSD1306 library not found.")
        return None
    try:
        bus = smbus2.SMBus(I2C_BUS) if smbus2 else None
        disp = SSD1306(WIDTH, HEIGHT, busnum=I2C_BUS, addr=I2C_ADDR, bus=bus)
        disp.begin()
        disp.clear()
        disp.display()
        return disp
    except Exception as e:
        logger.error(f"Failed to initialize SSD1306 display: {e}")
        return None

def get_gif_files(folder: str) -> List[str]:
    if not os.path.isdir(folder):
        logger.error(f"Folder not found: {folder}")
        return []
    gif_files = [f for f in os.listdir(folder) if f.lower().endswith('.gif')]
    gif_files.sort()
    return [os.path.join(folder, f) for f in gif_files]

def load_gif(path: str) -> Optional[Image.Image]:
    try:
        return Image.open(path)
    except FileNotFoundError:
        logger.error(f"File not found: {path}")
        return None
    except Exception as e:
        logger.error(f"Error loading GIF {path}: {e}")
        return None

def get_frame_duration(gif: Image.Image) -> int:
    try:
        return int(gif.info.get('duration', 100))
    except (ValueError, TypeError):
        return 100

def resize_and_pad(img: Image.Image) -> Image.Image:
    img.thumbnail((WIDTH, HEIGHT), Image.LANCZOS)
    bg = Image.new('RGB', (WIDTH, HEIGHT), (0, 0, 0))
    bg.paste(
        img,
        ((WIDTH - img.width) // 2, (HEIGHT - img.height) // 2)
    )
    return bg.convert('1')

def display_frame(disp: SSD1306, frame: Image.Image) -> None:
    pixels = np.array(frame).flatten()
    disp.showImage(pixels)

def play_gif(disp: SSD1306, path: str) -> None:
    gif = load_gif(path)
    if gif is None:
        return
    try:
        n_frames = len(gif.n_frames) if hasattr(gif, 'n_frames') else len(list(ImageSequence.Iterator(gif)))
        loop = int(gif.info.get('loop', 0))
        if loop == 0:
            loop = -1
        frame_duration = get_frame_duration(gif)
        for _ in range(loop):
            for i in range(n_frames):
                if not _running:
                    return
                gif.seek(i)
                frame = resize_and_pad(gif.convert('RGB'))
                display_frame(disp, frame)
                time.sleep(frame_duration / 1000.0)
    except Exception as e:
        logger.error(f"Error playing GIF {path}: {e}")

def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    disp = init_display()
    if disp is None:
        sys.exit(1)
    try:
        gifs = get_gif_files('.')
        if not gifs:
            logger.warning("No GIF files found in current directory.")
            return
        for path in gifs:
            if not _running:
                break
            logger.info(f"Playing: {path}")
            play_gif(disp, path)
    finally:
        try:
            disp.clear()
            disp.display()
        except Exception:
            pass
        logger.info("Display cleared. Exiting.")

if __name__ == '__main__':
    main()

