logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor over I2C."""

    DHT20_I2C_ADDRESS = 0x5C
    DHT20_STATUS_REG = 0x01
    DHT20_DATA_REG = 0x00
    DHT20_POWER_ON_DELAY = 0.5
    DHT20_MEASURE_DELAY = 0.1
    DHT20_MAX_RETRIES = 5
    DHT20_RETRY_DELAY = 2.0
    DHT20_CRC_POLYNOMIAL = 0x31
    DHT20_CRC_INIT = 0xFF

    def __init__(self, i2c_bus_number=1, i2c_address=None):
        self._i2c_address = i2c_address or self.DHT20_I2C_ADDRESS
        self._i2c_bus = None
        try:
            self._i2c_bus = smbus2.SMBus(i2c_bus_number)
            time.sleep(self.DHT20_POWER_ON_DELAY)
            if not self._check_device_status():
                self._i2c_bus.close()
                self._i2c_bus = None
                raise IOError("DHT20 status check failed")
            logger.info("DHT20 initialized successfully")
        except Exception as e:
            logger.error(f"Error initializing DHT20: {e}")
            self.close()
            raise

    def _check_device_status(self):
        try:
            status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
            return (status & 0x18) == 0x18
        except Exception as e:
            logger.error(f"Error checking DHT20 status: {e}")
            return False

    def _read_register(self, register, length):
        try:
            return self._i2c_bus.read_i2c_block_data(self._i2c_address, register, length)
        except Exception as e:
            logger.error(f"Error reading register 0x{register:02X}: {e}")
            raise

    def _write_register(self, register, data):
        try:
            self._i2c_bus.write_i2c_block_data(self._i2c_address, register, data)
        except Exception as e:
            logger.error(f"Error writing register 0x{register:02X}: {e}")
            raise

    def _calculate_crc8(self, data):
        crc = self.DHT20_CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.DHT20_CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

