        if self._i2c_bus is None:
            logger.error("I2C bus is not initialized")
            return None, None, True

        for attempt in range(self.DHT20_MAX_RETRIES):
            try:
                self._write_register(self.DHT20_DATA_REG, [])
                time.sleep(self.DHT20_MEASURE_DELAY)

                status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
                if (status & 0x80) != 0:
                    logger.warning(f"Measurement in progress (status=0x{status:02X}), retrying...")
                    time.sleep(self.DHT20_RETRY_DELAY)
                    continue

                data = self._read_register(self.DHT20_DATA_REG, 7)
                if len(data) != 7:
                    logger.warning(f"Incomplete data read ({len(data)} bytes), retrying...")
                    time.sleep(self.DHT20_RETRY_DELAY)
                    continue

