                return temperature, humidity, crc_error

            except Exception as e:
                logger.error(f"Error reading DHT20 data (attempt {attempt + 1}/{self.DHT20_MAX_RETRIES}): {e}")

            time.sleep(self.DHT20_RETRY_DELAY)

        logger.error("Failed to read DHT20 data after multiple retries.")
        return None, None, True

    def close(self):
        if self._i2c_bus is not None:
            try:
                self._i2c_bus.close()
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")
            finally:
                self._i2c_bus = None

    def __del__(self):
        self.close()


if __name__ == "__main__":
    try:
        sensor = DHT20()
        temperature, humidity, crc_error = sensor.read_data()
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.2f} C")
            print(f"Humidity: {humidity:.2f} %")
            if crc_error:
                print("Warning: CRC error detected!")
        else:
            print("Failed to read sensor data.")
    except Exception as e:
        logger.error(f"Fatal error: {e}")

