import time
import datetime
import signal
import sys
import RPi.GPIO as GPIO

DHT_PIN = 4
LOG_FILE = "humidity_log.txt"
READ_INTERVAL = 10

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_dht22():
    """Reads temperature and humidity from a DHT22 sensor using bit-banged protocol."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.OUT)
        GPIO.output(DHT_PIN, GPIO.HIGH)
        time.sleep(0.5)

        GPIO.output(DHT_PIN, GPIO.LOW)
        time.sleep(0.018)
        GPIO.output(DHT_PIN, GPIO.HIGH)
        time.sleep(0.00004)

        GPIO.setup(DHT_PIN, GPIO.IN)

        timeout = time.time() + 0.1
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.time() > timeout:
                return None, None
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            if time.time() > timeout:
                return None, None
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.time() > timeout:
                return None, None

        data = []
        for _ in range(40):
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                if time.time() > timeout:
                    return None, None
            start = time.time()
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() > timeout:
                    return None, None
            duration = time.time() - start
            data.append(1 if duration > 0.00005 else 0)

        GPIO.cleanup(DHT_PIN)

        humidity_int = (data[0] << 7) | (data[1] << 6) | (data[2] << 5) | (data[3] << 4) | (data[4] << 3) | (data[5] << 2) | (data[6] << 1) | data[7]
        humidity_dec = (data[8] << 7) | (data[9] << 6) | (data[10] << 5) | (data[11] << 4) | (data[12] << 3) | (data[13] << 2) | (data[14] << 1) | data[15]
        temp_int = (data[16] << 7) | (data[17] << 6) | (data[18] << 5) | (data[19] << 4) | (data[20] << 3) | (data[21] << 2) | (data[22] << 1) | data[23]
        temp_dec = (data[24] << 7) | (data[25] << 6) | (data[26] << 5) | (data[27] << 4)
        temp_sign = data[28]
        checksum = (data[29] << 7) | (data[30] << 6) | (data[31] << 5) | (data[32] << 4) | (data[33] << 3) | (data[34] << 2) | (data[35] << 1) | data[36]

        calculated_checksum = (humidity_int + humidity_dec + temp_int + temp_dec + temp_sign) & 0xFF
        if calculated_checksum != checksum:
            return None, None

        humidity = humidity_int + humidity_dec / 10.0
        temperature = temp_int + temp_dec / 10.0
        if temp_sign:
            temperature = -temperature

        return temperature, humidity

    except Exception:
        return None, None

def log_data(temperature, humidity):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(LOG_FILE, "a") as f:
            f.write(f"{timestamp}, {temperature:.1f}, {humidity:.1f}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        while _running:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                log_data(temperature, humidity)
            else:
                print("Failed to read DHT22 sensor.")
            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

