import smbus
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT20_I2C_ADDRESS = 0x5C
DHT20_STATUS_REG = 0x01
DHT20_MEASURE_REG = 0xFE
DHT20_DATA_REG = 0x00
DHT20_BUS = 1
DHT20_EXPECTED_STATUS = 0x21
DHT20_CRC_POLYNOMIAL = 0x31
DHT20_CRC_INIT = 0xFF
DHT20_MEASURE_DELAY = 0.08
DHT20_MAX_WAIT = 0.1
DHT20_POLL_INTERVAL = 0.01


class DHT20:
    def __init__(self, bus=DHT20_BUS, address=DHT20_I2C_ADDRESS):
        self.address = address
        self.bus = None
        try:
            self.bus = smbus.SMBus(bus)
            time.sleep(0.05)
            if not self._verify():
                logging.warning('DHT20 not found or not responding at 0x%02X', address)
                self.bus = None
        except OSError as e:
            logging.error('Failed to open I2C bus %d: %s', bus, e)
            self.bus = None
        except Exception as e:
            logging.error('Unexpected error during init: %s', e)
            self.bus = None

    def _verify(self):
        if self.bus is None:
            return False
        try:
            status = self.bus.read_byte_data(self.address, DHT20_STATUS_REG)
            return status == DHT20_EXPECTED_STATUS
        except OSError:
            return False

    def _crc8(self, data):
        crc = DHT20_CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20_CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def measure(self):
        if self.bus is None:
            logging.error('I2C bus not initialized')
            return None, None, True
        try:
            self.bus.write_byte_data(self.address, DHT20_MEASURE_REG, 0x00)
            time.sleep(DHT20_MEASURE_DELAY)
            deadline = time.time() + DHT20_MAX_WAIT
            while True:
                status = self.bus.read_byte_data(self.address, DHT20_STATUS_REG)
                if status & 0x18:
                    break
                if time.time() > deadline:
                    logging.warning('DHT20 measurement timed out')
                    return None, None, True
                time.sleep(DHT20_POLL_INTERVAL)
            data = self.bus.read_i2c_block_data(self.address, DHT20_DATA_REG, 7)
            crc_error = self._crc8(data[:6]) != data[6]
            if crc_error:
                logging.warning('CRC mismatch')
                return None, None, True
            humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
            temperature = (temperature_raw / (1 << 20)) * 200.0 - 50.0
            humidity = (humidity_raw / (1 << 20)) * 100.0
            return temperature, humidity, False
        except OSError as e:
            logging.error('I2C communication error: %s', e)
            return None, None, True
        except Exception as e:
            logging.error('Unexpected error during measurement: %s', e)
            return None, None, True

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


def main():
    sensor = DHT20()
    if sensor.bus is None:
        logging.error('Sensor initialization failed')
        sys.exit(1)
    def signal_handler(signum, frame):
        logging.info('Signal %d received, exiting', signum)
        sensor.close()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        temperature, humidity, crc_error = sensor.measure()
        if crc_error:
            print('Measurement failed: CRC error')
        else:
            print(f'Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %')
    finally:
        sensor.close()


if __name__ == '__main__':
    main()

