import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants
I2C_MUX_ADDRESS = 0x70
BME280_CHANNEL = 0
TSL2591_CHANNEL = 1
READ_INTERVAL_SECONDS = 2


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to confirm it is actually alive
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()
        if not devices:
            print("Error: No I2C devices detected on the bus.")
            i2c_bus.deinit()
            return None
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_MUX_ADDRESS)
    except ValueError:
        print(f"Error: TCA9548A multiplexer not found at address 0x{I2C_MUX_ADDRESS:02X}.")
        return None
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_bme280(multiplexer):
    """Initialize the BME280 sensor on the specified multiplexer channel."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(multiplexer[BME280_CHANNEL], address=0x76)
    except ValueError:
        print(f"Error: BME280 not found on channel {BME280_CHANNEL}.")
        return None
    except Exception as e:
        print(f"Error initializing BME280: {e}")
        return None


def initialize_tsl2591(multiplexer):
    """Initialize the TSL2591 light sensor on the specified multiplexer channel."""
    try:
        return adafruit_tsl2591.TSL2591(multiplexer[TSL2591_CHANNEL])
    except ValueError:
        print(f"Error: TSL2591 not found on channel {TSL2591_CHANNEL}.")
        return None
    except Exception as e:
        print(f"Error initializing TSL2591: {e}")
        return None


def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Read temperature, humidity, and light intensity from the sensors."""
    temperature = None
    humidity = None
    light_intensity = None

    # Read BME280
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
    except OSError as e:
        print(f"I2C bus error reading BME280: {e}")
    except Exception as e:
        print(f"Unexpected error reading BME280: {e}")

    # Read TSL2591
    try:
        light_intensity = tsl2591_sensor.lux
    except OSError as e:
        print(f"I2C bus error reading TSL2591: {e}")
    except Exception as e:
        print(f"Unexpected error reading TSL2591: {e}")

    return temperature, humidity, light_intensity


def display_sensor_data(temperature, humidity, light_intensity):
    """Print the sensor readings to the console."""
    print(f"Temperature: {temperature:.1f} C" if temperature is not None else "Temperature: N/A")
    print(f"Humidity: {humidity:.1f} %" if humidity is not None else "Humidity: N/A")
    print(f"Light Intensity: {light_intensity:.1f} lux" if light_intensity is not None else "Light Intensity: N/A")
    print("-" * 30)


def main():
    """Main function to read and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        i2c_bus.deinit()
        return

    bme280_sensor = initialize_bme280(multiplexer)
    if bme280_sensor is None:
        i2c_bus.deinit()
        return

    tsl2591_sensor = initialize_tsl2591(multiplexer)
    if tsl2591_sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        i2c_bus.deinit()
        print("I2C bus released.")


if __name__ == "__main__":
    main()

