import argparse
import json
import logging
import socket
import sys
import threading

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

DEFAULT_RELAY_PIN = 17
DEFAULT_DHT_PIN = 4
DEFAULT_PORT = 12345
DEFAULT_ALLOWED_IP = "192.168.1.100"
DEFAULT_LOG_FILE = "hydroponics.log"

pump_state = False
pump_lock = threading.Lock()


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def setup_gpio(relay_pin, dht_pin):
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in simulation mode.")
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(relay_pin, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(dht_pin, GPIO.IN)
        logging.info("GPIO setup complete (relay=%d, dht=%d).", relay_pin, dht_pin)
    except Exception as e:
        logging.error("GPIO setup failed: %s", e)
        raise


def cleanup_gpio():
    if GPIO is not None:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleanup complete.")
        except Exception as e:
            logging.error("GPIO cleanup error: %s", e)


def handle_client(conn, addr, relay_pin, dht_pin):
    global pump_state
    logging.info("Connection from %s:%s", addr[0], addr[1])
    try:
        data = conn.recv(1024)
        if not data:
            logging.warning("Empty data received from %s", addr[0])
            return

        try:
            command = json.loads(data.decode("utf-8"))
        except json.JSONDecodeError:
            logging.error("Invalid JSON from %s: %s", addr[0], data.decode("utf-8", errors="ignore"))
            conn.sendall(b"Invalid JSON")
            return

        if not isinstance(command, dict) or "command" not in command:
            logging.error("Malformed command from %s", addr[0])
            conn.sendall(b"Invalid command format")
            return

        cmd = command["command"]

        if cmd == "pump_on":
            with pump_lock:
                GPIO.output(relay_pin, GPIO.HIGH)
                pump_state = True
            logging.info("Pump turned ON by %s", addr[0])
            conn.sendall(b"Pump turned ON")

        elif cmd == "pump_off":
            with pump_lock:
                GPIO.output(relay_pin, GPIO.LOW)
                pump_state = False
            logging.info("Pump turned OFF by %s", addr[0])
            conn.sendall(b"Pump turned OFF")

        elif cmd == "get_status":
            with pump_lock:
                status = {"pump_state": "on" if pump_state else "off", "temperature": 25.0}
            logging.info("Status requested by %s", addr[0])
            conn.sendall(json.dumps(status).encode("utf-8"))

        else:
            logging.warning("Unknown command from %s: %s", addr[0], cmd)
            conn.sendall(b"Unknown command")

    except socket.error as e:
        logging.error("Socket error with %s: %s", addr[0], e)
    except Exception as e:
        logging.error("Error handling client %s: %s", addr[0], e)
    finally:
        try:
            conn.close()
        except Exception:
            pass
        logging.info("Connection closed for %s", addr[0])


def main():
    parser = argparse.ArgumentParser(description="Hydroponics Controller")
    parser.add_argument("--relay_pin", type=int, default=DEFAULT_RELAY_PIN, help="BCM pin for relay")
    parser.add_argument("--dht_pin", type=int, default=DEFAULT_DHT_PIN, help="BCM pin for DHT11")
    parser.add_argument("--port", type=int, default=DEFAULT_PORT, help="Listening port")
    parser.add_argument("--allowed_ip", type=str, default=DEFAULT_ALLOWED_IP, help="Allowed client IP")
    parser.add_argument("--log_file", type=str, default=DEFAULT_LOG_FILE, help="Log file path")
    args = parser.parse_args()

    setup_logging(args.log_file)
    logging.info("Starting hydroponics controller...")

    try:
        setup_gpio(args.relay_pin, args.dht_pin)
    except Exception:
        logging.error("Failed to initialize GPIO. Exiting.")
        sys.exit(1)

    server_socket = None
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(("", args.port))
        server_socket.listen(5)
        logging.info("Listening on port %d", args.port)

        while True:
            try:
                conn, addr = server_socket.accept()
            except socket.timeout:
                continue
            if addr[0] != args.allowed_ip:
                logging.warning("Unauthorized connection from %s", addr[0])
                try:
                    conn.close()
                except Exception:
                    pass
                continue
            client_thread = threading.Thread(
                target=handle_client,
                args=(conn, addr, args.relay_pin, args.dht_pin),
                daemon=True,
            )
            client_thread.start()

    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received. Shutting down...")
    except socket.error as e:
        logging.error("Socket error: %s", e)
    finally:
        if server_socket is not None:
            try:
                server_socket.close()
            except Exception:
                pass
        cleanup_gpio()
        logging.info("Hydroponics controller stopped.")


if __name__ == "__main__":
    main()

