import time
import sys
from gpiozero import CPUTemperature

# Raspberry Pi 4 Model B: on‑board CPU temperature sensor
# Thermal zone file: /sys/class/thermal/thermal_zone0/temp

# Number of times to read the CPU temperature
NUM_READINGS = 5

# Delay between readings in seconds
DELAY_SECONDS = 5


def read_cpu_temp():
    """Read the CPU temperature, creating the CPUTemperature object each time.

    Returns the temperature as a float, or None if the thermal file is missing
    or any other error occurs.
    """
    try:
        cpu = CPUTemperature()
        return float(cpu.temperature)
    except FileNotFoundError:
        print("Error: Thermal zone file not found. Is this running on a Raspberry Pi?")
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None


def display_cpu_temp(cpu_temp):
    """Print the CPU temperature to the console, formatted to two decimal places."""
    if cpu_temp is not None:
        print(f"CPU Temperature: {cpu_temp:.2f} °C")


def main():
    """Main loop: read and display CPU temperature NUM_READINGS times."""
    try:
        for i in range(NUM_READINGS):
            cpu_temp = read_cpu_temp()
            display_cpu_temp(cpu_temp)
            if i < NUM_READINGS - 1:
                time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram terminated")
        sys.exit(0)


if __name__ == "__main__":
    main()

