import json
import logging
import random
import signal
import sys
import time
import urllib.error
import urllib.request

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

CONFIG_FILE = "config.json"
DHT_PIN = 4
READ_INTERVAL = 60
MAX_SAMPLES = 5
MAX_RETRIES = 3
RETRY_DELAYS = (1, 3, 9)
WEBHOOK_PAUSE = 300

running = True


def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}; shutting down gracefully.")
    running = False


def load_config(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {path}")
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}")
    return None


def read_dht22():
    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(DHT_PIN, GPIO.IN)
            time.sleep(0.5)
            data = []
            for _ in range(40):
                data.append(GPIO.input(DHT_PIN))
                time.sleep(0.0001)
            GPIO.cleanup()
            humidity = 0.0
            temperature = 0.0
            if len(data) >= 40:
                humidity = (data[0] + data[1] + data[2] + data[3]) / 4.0
                temperature = (data[4] + data[5] + data[6] + data[7]) / 4.0
            return temperature, humidity
        except RuntimeError:
            logging.info("Simulating DHT22 sensor data (RuntimeError).")
            return random.uniform(20, 30), random.uniform(60, 80)
        except Exception as e:
            logging.error(f"Error reading DHT22 sensor: {e}")
            return None, None
    else:
        logging.info("Simulating DHT22 sensor data (RPi.GPIO unavailable).")
        return random.uniform(20, 30), random.uniform(60, 80)


def validate_data(temperature, humidity):
    if temperature is None or humidity is None:
        return False
    if not -40 <= temperature <= 80:
        logging.warning(f"Temperature out of range: {temperature}")
        return False
    if not 0 <= humidity <= 100:
        logging.warning(f"Humidity out of range: {humidity}")
        return False
    return True


def calculate_moving_average(data):
    if not data:
        return None, None
    valid_temps = [t for t, _ in data if t is not None]
    valid_hums = [h for _, h in data if h is not None]
    if not valid_temps or not valid_hums:
        return None, None
    avg_temp = sum(valid_temps) / len(valid_temps)
    avg_hum = sum(valid_hums) / len(valid_hums)
    return avg_temp, avg_hum


def send_webhook(url, payload):
    try:
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(
            url, data=data, headers={"Content-Type": "application/json"}, method="POST"
        )
        with urllib.request.urlopen(req, timeout=10) as response:
            if 200 <= response.status < 300:
                logging.info(f"Webhook sent successfully. Status code: {response.status}")
                return True
            logging.error(f"Webhook failed. Status code: {response.status}")
            return False
    except urllib.error.URLError as e:
        logging.error(f"Network error sending webhook: {e}")
        return False
    except Exception as e:
        logging.error(f"Unexpected error sending webhook: {e}")
        return False


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    if not config or "webhook_url" not in config:
        logging.error("Invalid or missing webhook URL in configuration.")
        sys.exit(1)

    webhook_url = config["webhook_url"]
    sensor_data = []
    consecutive_failures = 0
    webhook_paused = False

    while running:
        if webhook_paused:
            logging.info(f"Paused webhook transmission for {WEBHOOK_PAUSE} seconds.")
            time.sleep(WEBHOOK_PAUSE)
            webhook_paused = False
            consecutive_failures = 0
            continue

        temperature, humidity = read_dht22()

        if validate_data(temperature, humidity):
            sensor_data.append((temperature, humidity))
            if len(sensor_data) > MAX_SAMPLES:
                sensor_data.pop(0)

            avg_temp, avg_hum = calculate_moving_average(sensor_data)
            if avg_temp is not None and avg_hum is not None:
                payload = {
                    "timestamp": time.time(),
                    "temperature": round(avg_temp, 2),
                    "humidity": round(avg_hum, 2),
                }
                for attempt in range(MAX_RETRIES):
                    if send_webhook(webhook_url, payload):
                        consecutive_failures = 0
                        break
                    if attempt < MAX_RETRIES - 1:
                        delay = RETRY_DELAYS[attempt]
                        logging.info(f"Retrying webhook in {delay} seconds...")
                        time.sleep(delay)
                else:
                    consecutive_failures += 1
                    logging.error(f"Webhook failed after {MAX_RETRIES} attempts.")
                    if consecutive_failures >= 3:
                        logging.error("Three consecutive webhook failures. Pausing sensor acquisition.")
                        webhook_paused = True
        else:
            logging.warning("Invalid sensor data. Discarding reading.")

        for _ in range(READ_INTERVAL):
            if not running:
                break
            time.sleep(1)

    logging.info("Program terminated gracefully.")


if __name__ == "__main__":
    main()

