import config
import time
import signal
import sys
import paho.mqtt.client as mqtt
from paho.mqtt.enums import CallbackAPIVersion
import adafruit_dht
import board

DEGREE_CELSIUS = '\u00B0C'
HOMIE_VERSION = "4.0"
MAX_READ_RETRIES = 3
READ_RETRY_DELAY = 2.0
DHT_WARMUP_DELAY = 2.0

running = True
client = None
dht_sensor = None


def signal_handler(signum, frame):
    global running
    running = False


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print(f"Connected to MQTT broker")
    else:
        print(f"MQTT connection failed with reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker (reason code: {reason_code})")


def on_publish(client, userdata, mid, reason_code, properties):
    pass


def mqtt_connect():
    global client
    try:
        client = mqtt.Client(
            callback_api_version=CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            protocol=mqtt.MQTTv311
        )
        if config.mqttusername and config.mqttpassword:
            client.username_pw_set(config.mqttusername, config.mqttpassword)

        client.on_connect = on_connect
        client.on_disconnect = on_disconnect
        client.on_publish = on_publish

        client.will_set(
            f"homie/{config.homieclientid}/$state",
            payload="lost",
            retain=True,
            qos=1
        )

        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        client.loop_start()

        time.sleep(1)
        if not client.is_connected():
            raise RuntimeError("MQTT broker did not accept the connection")

        publish_homie_discovery()
        return True
    except Exception as e:
        print(f"MQTT connection error: {e}")
        return False


def publish_homie_discovery():
    publish_message("$homie", HOMIE_VERSION)
    publish_message("$name", config.homieclientname)
    publish_message("$state", "init")
    publish_message(f"{config.homienodes}/$name", "DHT22 Sensor")
    publish_message(f"{config.homienodes}/$properties", "temperature,humidity")
    publish_message(f"{config.homienodes}/temperature/$name", "Temperature")
    publish_message(f"{config.homienodes}/temperature/$unit", DEGREE_CELSIUS)
    publish_message(f"{config.homienodes}/temperature/$datatype", "float")
    publish_message(f"{config.homienodes}/temperature/$settable", "false")
    publish_message(f"{config.homienodes}/humidity/$name", "Humidity")
    publish_message(f"{config.homienodes}/humidity/$unit", "%")
    publish_message(f"{config.homienodes}/humidity/$datatype", "float")
    publish_message(f"{config.homienodes}/humidity/$settable", "false")
    publish_message("$state", "ready")


def publish_message(topic, payload):
    try:
        full_topic = f"homie/{config.homieclientid}/{topic}"
        info = client.publish(full_topic, str(payload), retain=True, qos=1)
        info.wait_for_publish(timeout=5)
    except Exception as e:
        print(f"Error publishing to topic {topic}: {e}")


def read_dht22():
    global dht_sensor
    try:
        if dht_sensor is None:
            pin = getattr(board, f"D{config.dhtegpiopin}")
            dht_sensor = adafruit_dht.DHT22(pin, use_pulseio=False)

        time.sleep(DHT_WARMUP_DELAY)

        for attempt in range(1, MAX_READ_RETRIES + 1):
            try:
                temperature = dht_sensor.temperature
                humidity = dht_sensor.humidity
                if temperature is not None and humidity is not None:
                    return temperature, humidity
                else:
                    raise RuntimeError("Sensor returned None")
            except RuntimeError as e:
                print(f"DHT22 read attempt {attempt}/{MAX_READ_RETRIES} failed: {e}")
                if attempt < MAX_READ_RETRIES:
                    time.sleep(READ_RETRY_DELAY)
            except Exception as e:
                print(f"Unexpected DHT22 error on attempt {attempt}: {e}")
                if attempt < MAX_READ_RETRIES:
                    time.sleep(READ_RETRY_DELAY)

        print("DHT22 reading failed after all retries.")
        return None, None
    except Exception as e:
        print(f"Error initializing DHT22: {e}")
        return None, None


def publish_sensor_data(temperature, humidity):
    if temperature is not None and humidity is not None:
        publish_message(f"{config.homienodes}/temperature", f"{temperature:.1f}")
        publish_message(f"{config.homienodes}/humidity", f"{humidity:.1f}")
    else:
        print("Skipping publish due to invalid sensor data.")


def cleanup():
    global client, dht_sensor
    if client is not None:
        try:
            publish_message("$state", "disconnected")
            client.loop_stop()
            client.disconnect()
        except Exception:
            pass
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception:
            pass


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not mqtt_connect():
        print("Failed to connect to MQTT broker. Exiting.")
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_dht22()
            publish_sensor_data(temperature, humidity)

            if running:
                time.sleep(config.publishtime)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

