    publish_message(f"{config.homienodes}/temperature/$settable", "false")
    publish_message(f"{config.homienodes}/humidity/$name", "Humidity")
    publish_message(f"{config.homienodes}/humidity/$unit", "%")
    publish_message(f"{config.homienodes}/humidity/$datatype", "float")
    publish_message(f"{config.homienodes}/humidity/$settable", "false")
    publish_message("$state", "ready")


def publish_message(topic, payload):
    try:
        full_topic = f"homie/{config.homieclientid}/{topic}"
        info = client.publish(full_topic, str(payload), retain=True, qos=1)
        info.wait_for_publish(timeout=5)
    except Exception as e:
        print(f"Error publishing to topic {topic}: {e}")


def read_dht22():
    global dht_sensor
    try:
        if dht_sensor is None:
            pin = getattr(board, f"D{config.dhtegpiopin}")
            dht_sensor = adafruit_dht.DHT22(pin, use_pulseio=False)

        time.sleep(DHT_WARMUP_DELAY)

        for attempt in range(1, MAX_READ_RETRIES + 1):
            try:
                temperature = dht_sensor.temperature
                humidity = dht_sensor.humidity
                if temperature is not None and humidity is not None:
                    return temperature, humidity
                else:
                    raise RuntimeError("Sensor returned None")
            except RuntimeError as e:
                print(f"DHT22 read attempt {attempt}/{MAX_READ_RETRIES} failed: {e}")
                if attempt < MAX_READ_RETRIES:
                    time.sleep(READ_RETRY_DELAY)
            except Exception as e:
                print(f"Unexpected DHT22 error on attempt {attempt}: {e}")
                if attempt < MAX_READ_RETRIES:
                    time.sleep(READ_RETRY_DELAY)

        print("DHT22 reading failed after all retries.")
        return None, None
    except Exception as e:
        print(f"Error initializing DHT22: {e}")
        return None, None


def publish_sensor_data(temperature, humidity):
    if temperature is not None and humidity is not None:
        publish_message(f"{config.homienodes}/temperature", f"{temperature:.1f}")
        publish_message(f"{config.homienodes}/humidity", f"{humidity:.1f}")
    else:
        print("Skipping publish due to invalid sensor data.")


def cleanup():
    global client, dht_sensor
    if client is not None:
        try:
            publish_message("$state", "disconnected")
            client.loop_stop()
            client.disconnect()
        except Exception:
            pass
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception:
            pass


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not mqtt_connect():
        print("Failed to connect to MQTT broker. Exiting.")
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_dht22()
            publish_sensor_data(temperature, humidity)

            if running:
                time.sleep(config.publishtime)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

