import time
import threading
import queue
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.animation as animation

try:
    import serial
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial")
    raise SystemExit(1)

try:
    import thermal_api
except ImportError:
    print("Error: thermal_api module not found.")
    raise SystemExit(1)

# Constants
UART_PORT = "/dev/ttyS0"
BAUD_RATE = 9600
TIMEOUT = 1
IMAGE_WIDTH = 32
IMAGE_HEIGHT = 24
EXPECTED_VALUES = IMAGE_WIDTH * IMAGE_HEIGHT
UPDATE_INTERVAL_MS = 100


class ThermalMonitor:
    """Monitors thermal data from a UART sensor and displays it as a heatmap."""

    def __init__(self):
        self.serial_port = None
        self.thermal_sensor = None
        self.data_queue = queue.Queue()
        self.stop_event = threading.Event()
        self.lock = threading.Lock()
        self.image = None
        self.fig = None

    def initialize_serial(self):
        """Opens the UART port via the library API and the underlying serial port."""
        try:
            self.serial_port = serial.Serial(
                port=UART_PORT,
                baudrate=BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=TIMEOUT,
            )
            print(f"Serial port {UART_PORT} opened at {BAUD_RATE} baud.")
        except serial.SerialException as e:
            print(f"Error opening serial port {UART_PORT}: {e}")
            raise

        try:
            self.thermal_sensor = thermal_api.ThermalSensor(
                serial_port=self.serial_port
            )
            print("Thermal sensor initialized.")
        except Exception as e:
            print(f"Error initializing thermal sensor: {e}")
            self.close_serial()
            raise

    def read_thermal_data(self):
        """Background thread: reads comma-separated integer frames from the API."""
        while not self.stop_event.is_set():
            try:
                data = self.thermal_sensor.read_data()
                if data is not None:
                    try:
                        values = [int(v) for v in data.split(",")]
                        if len(values) == EXPECTED_VALUES:
                            self.data_queue.put(values)
                        else:
                            print(
                                f"Warning: Expected {EXPECTED_VALUES} values, "
                                f"received {len(values)}."
                            )
                    except ValueError as e:
                        print(f"Error parsing data (invalid integer): {e}")
            except Exception as e:
                print(f"Error reading thermal data: {e}")
                time.sleep(0.1)

    def update_heatmap(self, frame):
        """Animation callback: pops a frame from the queue and updates the plot."""
        try:
            values = self.data_queue.get_nowait()
        except queue.Empty:
            return self.image

        with self.lock:
            image_array = np.array(values, dtype=np.float32).reshape(
                (IMAGE_HEIGHT, IMAGE_WIDTH)
            )
            if self.image is None:
                self.image = self.ax.imshow(
                    image_array, cmap="inferno", interpolation="nearest"
                )
                plt.colorbar(self.image, ax=self.ax)
            else:
                self.image.set_data(image_array)
            self.fig.canvas.draw_idle()
            return self.image

    def start(self):
        """Initializes the serial connection, starts the reader thread, and runs the plot."""
        self.initialize_serial()

        self.thread = threading.Thread(target=self.read_thermal_data, daemon=True)
        self.thread.start()

        self.fig, self.ax = plt.subplots()
        self.ani = animation.FuncAnimation(
            self.fig,
            self.update_heatmap,
            interval=UPDATE_INTERVAL_MS,
            blit=False,
        )

        try:
            plt.show()
        except KeyboardInterrupt:
            print("\nKeyboardInterrupt received. Shutting down...")
        finally:
            self.stop()

    def stop(self):
        """Signals the reader thread to stop, closes the serial port, and joins the thread."""
        self.stop_event.set()
        if self.thread.is_alive():
            self.thread.join(timeout=2.0)
        self.close_serial()

    def close_serial(self):
        """Closes the serial port if open."""
        if self.serial_port is not None and self.serial_port.is_open:
            try:
                self.serial_port.close()
                print("Serial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}")
        self.serial_port = None


if __name__ == "__main__":
    monitor = ThermalMonitor()
    monitor.start()

