    sys.exit(1)

try:
    import adafruit_dht
    import board
    DHT_AVAILABLE = True
except ImportError:
    DHT_AVAILABLE = False

LED_PIN = 17
PWM_FREQ = 100
MAX_BRIGHTNESS = 90
RAMP_SECONDS = 600
HOLD_SECONDS = 10
SENSOR_INTERVAL = 5
MAX_RETRIES = 3
RETRY_DELAY = 2

running = True
pwm = None
dht_device = None


def log_event(brightness, temperature=None, humidity=None):
    entry = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "brightness": brightness,
    }
    if temperature is not None and humidity is not None:
        entry["temperature"] = temperature
        entry["humidity"] = humidity
    print(json.dumps(entry))


def read_sensor():
    if not DHT_AVAILABLE:
        return None, None
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temp = dht_device.temperature
            hum = dht_device.humidity
            if temp is not None and hum is not None:
                return temp, hum
        except RuntimeError as e:
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                print(json.dumps({"timestamp": datetime.now(timezone.utc).isoformat(), "message": f"DHT22 read failed: {e}"}))
    return None, None


def set_brightness(level):
    clamped = max(0, min(MAX_BRIGHTNESS, level))
    pwm.ChangeDutyCycle(clamped)


def cleanup(signum=None, frame=None):
    global running, pwm, dht_device
    running = False
    if pwm is not None:
        try:
            pwm.ChangeDutyCycle(0)
            pwm.stop()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def main():
    global pwm, dht_device
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(LED_PIN, GPIO.OUT)

    try:
        pwm = GPIO.PWM(LED_PIN, PWM_FREQ)
