            dht_device = adafruit_dht.DHT22(board.D4, use_pulseio=False)
        except Exception as e:
            print(json.dumps({"timestamp": datetime.now(timezone.utc).isoformat(), "message": f"DHT22 init failed: {e}"}))
            dht_device = None

    last_sensor_time = 0.0
    try:
        while running:
            set_brightness(0)
            log_event(0)
            time.sleep(HOLD_SECONDS)

            set_brightness(0)
            start = time.monotonic()
            while running and (time.monotonic() - start) < RAMP_SECONDS:
                frac = (time.monotonic() - start) / RAMP_SECONDS
                set_brightness(frac * MAX_BRIGHTNESS)
                log_event(frac * MAX_BRIGHTNESS)
                if time.monotonic() - last_sensor_time >= SENSOR_INTERVAL:
                    temp, hum = read_sensor()
                    log_event(frac * MAX_BRIGHTNESS, temp, hum)
                    last_sensor_time = time.monotonic()
                time.sleep(0.1)

