import config
import time
import signal
import sys
import paho.mqtt.client as mqtt
from paho.mqtt.client import CallbackAPIVersion
import adafruit_dht
from board import Pin

DEGREE_CELSIUS = "\u00B0C"
running = True
client = None
dht_device = None

def signal_handler(signum, frame):
    global running
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker")
    else:
        print(f"Failed to connect to MQTT broker, reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker, reason code: {reason_code}")

def connect_mqtt():
    global client
    client = mqtt.Client(
        callback_api_version=CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid,
        clean_session=True
    )
    if hasattr(config, 'mqttusername') and config.mqttusername:
        client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect
    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        client.loop_start()
        time.sleep(1)
        if not client.is_connected():
            raise ConnectionError("MQTT connection timed out")
    except Exception as e:
        print(f"MQTT connection error: {e}")
        raise

def publish(topic, payload):
    if client and client.is_connected():
        try:
            full_topic = f"homie/{config.homieclientid}/{topic}"
            client.publish(full_topic, payload, qos=1)
        except Exception as e:
            print(f"MQTT publish error: {e}")

def read_dht22():
    global dht_device
    try:
        if dht_device is None:
            dht_device = adafruit_dht.DHT22(Pin(config.dhtgpiopin), use_pulseio=False)
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is not None and humidity is not None:
            return temperature, humidity
        return None, None
    except RuntimeError as e:
        print(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}")
        return None, None

def cleanup():
    global client, dht_device
    if client:
        try:
            client.loop_stop()
            client.disconnect()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        connect_mqtt()
        publish("$state", "init")
        publish("$homie", "4.0")
        publish("$name", config.homieclientname)
        publish("$nodes", config.homienodes)
        last_read_time = 0
        while running:
            current_time = time.time()
            if current_time - last_read_time >= 2:
                temperature, humidity = read_dht22()
                if temperature is not None and humidity is not None:
                    print(f"Temperature = {temperature:.1f} {DEGREE_CELSIUS}")
                    print(f"Humidity = {humidity:.1f} %\r")
                    publish(f"{config.homienodes}/temperature", f"{temperature:.1f}")
                    publish(f"{config.homienodes}/humidity", f"{humidity:.1f}")
                last_read_time = current_time
            time.sleep(0.1)
    except Exception as e:
        print(f"Main loop error: {e}")
    finally:
        cleanup()
        print("Exiting...")

if __name__ == "__main__":
    main()

