import logging
import logging.handlers
import os
import signal
import sys
import datetime

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

# Constants
DHT_PIN = 4
LOG_FILE = '/var/log/wearable'
FALLBACK_LOG_FILE = os.path.join(os.path.expanduser('~'), '.local', 'log', 'wearable')
LOG_RETENTION_DAYS = 7
READ_INTERVAL = 5
MAX_RETRIES = 3
RETRY_DELAY = 1

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def setup_logging():
    """Configure logging with daily rotation and fallback path."""
    log_file = LOG_FILE
    try:
        test_file = open(log_file, 'a')
        test_file.close()
    except (PermissionError, OSError):
        log_file = FALLBACK_LOG_FILE
