import signal
import sys
import time
import logging

try:
    from gpiozero import InputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("sensor_monitor")

PINS = [17, 27, 22]
POLL_INTERVAL = 1.0
_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            try:
                dev = InputDevice(pin=pin, pull_up=True)
                devices.append(dev)
                log.info("Configured GPIO%d as input (pull_up=True)", pin)
            except (GPIOZeroError, GPIODeviceError) as exc:
                log.error("Failed to initialize GPIO%d: %s", pin, exc)
                _cleanup(devices)
                sys.exit(1)

        log.info("Monitoring sensors on pins %s every %.1f s. Press Ctrl+C to exit.", PINS, POLL_INTERVAL)

        while _running:
            for idx, dev in enumerate(devices):
                try:
                    if dev.is_active:
                        log.info("Response for sensor %d", idx + 1)
                except (GPIOZeroError, GPIODeviceError) as exc:
                    log.error("Error reading GPIO%d: %s", PINS[idx], exc)
            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        log.exception("Unexpected error: %s", exc)
    finally:
        _cleanup(devices)
        log.info("GPIO cleanup completed.")


def _cleanup(devices):
    for dev in devices:
        try:
            dev.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

