#!/usr/bin/env python3
"""
led_control.py — Button-controlled LED toggle for Raspberry Pi.

Wiring:
  • LED  : GPIO 17 (physical pin 11) -> 330 ohm -> LED anode -> LED cathode -> GND
  • Button: 3.3 V (physical pin 1) -> Button (to GPIO 5) -> 10 k ohm -> GND
    (10 k ohm external pull-down; GPIO 2 has a fixed on-board pull-up so it is
    avoided to prevent conflicts.)

Behavior:
  • Button pressed  -> print "Button pressed! LED is ON"   -> LED on
  • Button released -> print "Button released! LED is OFF" -> LED off
  • Polls every 0.1 s.
  • Clean shutdown on Ctrl-C or unexpected error.
"""

import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    # Allow the script to run in mocked/emulated environments where RPi.GPIO
    # is not installed (e.g., CI / unittest.mock).
    GPIO = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
BUTTON_PIN = 5   # BCM 5  (physical pin 29)
LED_PIN = 17     # BCM 17 (physical pin 11)
POLL_INTERVAL = 0.1  # seconds

# ---------------------------------------------------------------------------
# GPIO setup
# ---------------------------------------------------------------------------
if GPIO is not None:
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as exc:
        print(f"GPIO initialization failed: {exc}", file=sys.stderr)
        sys.exit(1)
else:
    # Mock-friendly stubs so the control loop can run without real hardware.
    class _GPIO:
        BCM = None
        IN = None
        OUT = None
        PUD_DOWN = None
        HIGH = True
        LOW = False

        @staticmethod
        def setmode(mode):
            pass

        @staticmethod
        def setwarnings(flag):
            pass

        @staticmethod
        def setup(pin, direction, **kwargs):
            pass

        @staticmethod
        def input(pin):
            return False

        @staticmethod
        def output(pin, state):
            pass

        @staticmethod
        def cleanup():
            pass

    GPIO = _GPIO()

# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------
try:
    while True:
        try:
            button_state = GPIO.input(BUTTON_PIN)
        except Exception as exc:
            # Transient I/O error — log and continue polling.
            print(f"Error reading button state: {exc}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
            continue

        if button_state:
            print("Button pressed! LED is ON")
            try:
                GPIO.output(LED_PIN, GPIO.HIGH)
            except Exception as exc:
                print(f"Error turning LED on: {exc}", file=sys.stderr)
        else:
            print("Button released! LED is OFF")
            try:
                GPIO.output(LED_PIN, GPIO.LOW)
            except Exception as exc:
                print(f"Error turning LED off: {exc}", file=sys.stderr)

        time.sleep(POLL_INTERVAL)

except KeyboardInterrupt:
    print("\nProgram stopped by user.")
except Exception as exc:
    print(f"Unexpected error: {exc}", file=sys.stderr)
finally:
    # Ensure the LED is off and release GPIO resources on every exit path.
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

