import time
import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

DYNAMO_PIN = 17
HIGH_DURATION = 0.2
LOW_DURATION = 0.2

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def setup_gpio(pin):
    try:
        import RPi.GPIO as GPIO
    except RuntimeError:
        logging.error("RPi.GPIO module not available; run on a Raspberry Pi.")
        return False
    except ImportError:
        logging.error("RPi.GPIO library not installed. Install with: pip install RPi.GPIO")
        return False

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO %d setup for output (initial LOW).", pin)
        return GPIO
    except Exception as e:
        logging.error("Failed to initialize GPIO %d: %s", pin, e)
        return False


def set_pin_state(GPIO, pin, state):
    try:
        GPIO.output(pin, state)
    except Exception as e:
        logging.error("Failed to set GPIO %d to %s: %s", pin, state, e)
        return False
    return True


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO = setup_gpio(DYNAMO_PIN)
    if GPIO is False:
        sys.exit(1)

    try:
        logging.info("Starting dynamo simulation on GPIO %d.", DYNAMO_PIN)
        while _running:
            if not set_pin_state(GPIO, DYNAMO_PIN, GPIO.HIGH):
                break
            logging.info("Dynamo ON (HIGH)")
            time.sleep(HIGH_DURATION)
            if not _running:
                break
            if not set_pin_state(GPIO, DYNAMO_PIN, GPIO.LOW):
                break
            logging.info("Dynamo OFF (LOW)")
            time.sleep(LOW_DURATION)
    except Exception as e:
        logging.error("Unexpected error in main loop: %s", e)
    finally:
        try:
            set_pin_state(GPIO, DYNAMO_PIN, GPIO.LOW)
            GPIO.cleanup()
            logging.info("GPIO cleanup completed.")
        except Exception as e:
            logging.error("Error during GPIO cleanup: %s", e)
