                while not self._stop_event.is_set():
                    try:
                        data = self.dog.receive()
                        if data is not None:
                            log_file.write(str(data) + '\n')
                            log_file.flush()
                    except Exception as e:
                        print(f"Error receiving data: {e}", file=sys.stderr)
                    time.sleep(0.1)
        except IOError as e:
            print(f"File I/O error in receive loop: {e}", file=sys.stderr)
        except Exception as e:
            print(f"Unexpected error in receive loop: {e}", file=sys.stderr)

    def start_logging(self, log_file_path: str):
        """Starts the data logging process in a separate thread."""
        if self.is_running:
