                        self.help_command()
                elif action == 'exit':
                    self.stop_logging()
                    GPIO.cleanup()
                    sys.exit(0)
                else:
                    print("Unknown command. Try 'help'.")

            except EOFError:
                print("\nEOF received. Exiting...")
