import time
import signal
import sys

TILT_SENSOR_PIN = 17
BUZZER_PIN = 27
POLL_INTERVAL = 0.1
BUZZ_DURATION = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(TILT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(BUZZER_PIN, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio():
    GPIO.output(BUZZER_PIN, GPIO.LOW)
    GPIO.cleanup()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                tilted = GPIO.input(TILT_SENSOR_PIN) == GPIO.LOW
            except Exception as e:
                print(f"Sensor read error: {e}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)
                continue

            if tilted:
                try:
                    GPIO.output(BUZZER_PIN, GPIO.HIGH)
                    start = time.monotonic()
                    while _running and GPIO.input(TILT_SENSOR_PIN) == GPIO.LOW:
                        if time.monotonic() - start >= BUZZ_DURATION:
                            break
                        time.sleep(POLL_INTERVAL)
                    GPIO.output(BUZZER_PIN, GPIO.LOW)
                except Exception as e:
                    print(f"Buzzer control error: {e}", file=sys.stderr)
                    GPIO.output(BUZZER_PIN, GPIO.LOW)
            else:
                time.sleep(POLL_INTERVAL)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

