import time
import board
import busio
import adafruit_fingerprint

# Constants
I2C_RETRY_DELAY = 1.0  # seconds between authentication attempts
DEINIT_RETRY_DELAY = 5.0  # seconds to wait before retrying deinit


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C bus: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing I2C bus: {e}")
        return None


def initialize_fingerprint_sensor(i2c_bus):
    """Initialize the Adafruit fingerprint sensor on the I2C bus."""
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return sensor
    except ValueError as e:
        print(f"Error initializing fingerprint sensor (I2C bus may be locked): {e}")
        return None
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor (sensor absent or unresponsive): {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing fingerprint sensor: {e}")
        return None


def authenticate_user(sensor):
    """Attempt to authenticate a user against the fingerprint database."""
    print("Waiting for fingerprint...")
    try:
        result = sensor.get_image()
        if result == adafruit_fingerprint.NOFINGER:
            print("No finger detected.")
            return False
        elif result != adafruit_fingerprint.OK:
            print(f"Error capturing image: {result}")
            return False

        print("Creating template...")
        if sensor.image_2_tz(1) != adafruit_fingerprint.OK:
            print("Error converting image to template.")
            return False

        print("Searching database...")
        if sensor.finger_search() != adafruit_fingerprint.OK:
            print("No match found.")
            return False

        print("Access Granted")
        print(f"Matched ID: {sensor.finger_id}")
        print(f"Confidence: {sensor.confidence}")
        return True

    except ValueError as e:
        print(f"I2C communication error during authentication: {e}")
        return False
    except RuntimeError as e:
        print(f"Sensor runtime error during authentication: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error during authentication: {e}")
        return False


def main():
    """Main loop: initialize hardware, authenticate users, clean up on exit."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_fingerprint_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            authenticate_user(sensor)
            time.sleep(I2C_RETRY_DELAY)

    except KeyboardInterrupt:
        print("\nExiting program...")

    finally:
        # Attempt to deinitialize the I2C bus; retry if the bus is locked
        while True:
            try:
                i2c_bus.deinit()
                print("I2C bus deinitialized.")
                break
            except ValueError:
                print(f"I2C bus is locked; retrying deinit in {DEINIT_RETRY_DELAY} seconds...")
                time.sleep(DEINIT_RETRY_DELAY)
            except Exception as e:
                print(f"Error deinitializing I2C bus: {e}")
                break


if __name__ == "__main__":
    main()

