import signal
import sys
import time
import logging
import threading
from typing import Optional

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

from gpiozero import Device
from gpiozero.pins.native import NativeFactory

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# Constants for GPIO pin numbers (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Constants for data transmission
START_BYTE = [1, 0, 1, 1, 1, 1, 1, 1]
END_BYTE = [1, 1, 1, 1, 1, 1, 1, 1]
EMPTY_BYTE = [0, 0, 0, 0, 0, 0, 0, 0]
BASE_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Timing constants (seconds)
BIT_DELAY = 0.0001
RECEIVE_TIMEOUT = 5.0

# Global shutdown flag
_shutdown = threading.Event()


def _signal_handler(signum, frame):
    logger.info("Signal %s received, initiating shutdown.", signum)
    _shutdown.set()


def setup_gpio() -> None:
    """Sets up the GPIO pins for data transmission and reception."""
    if GPIO is None:
        raise RuntimeError("RPi.GPIO is not available on this platform.")
    GPIO.setwarnings(False)
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DATA_OUT_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(TIMER_OUT_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(DATA_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    GPIO.setup(TIMER_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    logger.info("GPIO setup complete.")


def cleanup_gpio() -> None:
    """Cleans up the GPIO pins."""
    if GPIO is not None:
        try:
            GPIO.cleanup()
            logger.info("GPIO cleanup complete.")
        except Exception as e:
            logger.error("Error during GPIO cleanup: %s", e)


def char_to_byte(char: str) -> list:
    """Converts a character to its 8-bit representation."""
    if not isinstance(char, str) or len(char) != 1:
        raise ValueError("Input must be a single character.")
    return [int(bit) for bit in format(ord(char), '08b')]


def byte_to_char(byte: list) -> str:
    """Converts an 8-bit list representation back to a character."""
    if not isinstance(byte, list) or len(byte) != 8 or not all(isinstance(bit, int) for bit in byte):
        raise ValueError("Input must be a list of 8 integers.")
    return chr(int("".join(map(str, byte)), 2))


def buffer_to_string(buffer: list) -> str:
    """Converts a buffer list to a string, excluding start and end markers."""
    try:
        return "".join(byte_to_char(byte) for byte in buffer if byte not in (START_BYTE, END_BYTE, EMPTY_BYTE))
    except ValueError as e:
        logger.error("Error converting buffer to string: %s", e)
        return ""


def string_to_buffer(string: str) -> list:
    """Converts a string to a buffer list, adding start and end markers."""
    buffer = [START_BYTE]
    for char in string:
        buffer.append(char_to_byte(char))
    buffer.append(END_BYTE)
    return buffer


def send_data(data: str) -> None:
    """Sends data over the GPIO pins using the defined protocol."""
    if not isinstance(data, str):
        raise ValueError("Input must be a string.")
    if data == "":
        logger.warning("Empty string passed to send_data. Nothing to send.")
        return

    setup_gpio()
    try:
        buffer = string_to_buffer(data)
        logger.info("Sending data: %s", data)

        for byte in buffer:
            for bit in byte:
                GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
                GPIO.output(DATA_OUT_PIN, bit)
                time.sleep(BIT_DELAY)
                GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
                time.sleep(BIT_DELAY)

        GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
        logger.info("Data transmission complete.")
    except Exception as e:
        logger.error("Error during data transmission: %s", e)
        raise
    finally:
        cleanup_gpio()


def _receive_bit_callback(channel: int) -> None:
    """Callback function for rising edge detection on timer_in."""
    if _shutdown.is_set():
        return
    try:
        received_bit = GPIO.input(DATA_IN_PIN)
        _buffer.append(received_bit)
        if len(_buffer) == 8:
            _bytes.append(_buffer)
            _buffer.clear()
    except Exception as e:
        logger.error("Error in receive bit callback: %s", e)


def receive_data(timeout: float = RECEIVE_TIMEOUT) -> str:
    """Receives data from the GPIO pins using the defined protocol."""
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError("Timeout must be a positive number.")

    if GPIO is None:
        raise RuntimeError("RPi.GPIO is not available on this platform.")

    setup_gpio()
    _buffer: list = []
    _bytes: list = []
    _start_time = time.time()
    _stop_time = _start_time + timeout

    try:
        GPIO.add_event_detect(TIMER_IN_PIN, GPIO.RISING, callback=_receive_bit_callback)

        while not _shutdown.is_set():
            if time.time() > _stop_time:
                logger.warning("Receive timeout reached.")
                break
            if START_BYTE in _bytes:
                break
            time.sleep(0.01)

        if START_BYTE not in _bytes:
            logger.warning("Start byte not received.")
            return ""

        start_index = _bytes.index(START_BYTE) + 1
        end_index = start_index
        while end_index < len(_bytes) and _bytes[end_index] != END_BYTE:
            end_index += 1

        if end_index == len(_bytes):
            logger.warning("End byte not received.")
            return ""

        received_bytes = _bytes[start_index:end_index]
        received_data = buffer_to_string(received_bytes)
        logger.info("Received data: %s", received_data)
        return received_data

    except Exception as e:
        logger.error("Error during data reception: %s", e)
        return ""
    finally:
        try:
            GPIO.remove_event_detect(TIMER_IN_PIN)
        except Exception:
            pass
        cleanup_gpio()


def api_call(data: str) -> str:
    """Sends data using send_data and receives the response using receive_data."""
    try:
        send_data(data)
        return receive_data()
    except Exception as e:
        logger.error("Error during API call: %s", e)
        return ""


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        response = api_call("Hello")
        print(f"Response: {response}")
    except Exception as e:
        logger.error("Fatal error in main: %s", e)
        sys.exit(1)

