try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000

fan = None

try:
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
        print(f"Hardware PWM initialized on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    except GPIOZeroError as e:
        print(f"Warning: hardware PWM unavailable ({e}); using software PWM fallback.", file=sys.stderr)
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)

    while True:
        try:
            user_input = input("Enter fan speed (0-100, or 'q' to quit): ").strip()
        except EOFError:
            print("\nEOF received, exiting.")
            break

        if user_input.lower() == 'q':
            break

        try:
            speed = float(user_input)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100, or 'q' to quit.")
            continue

        if not 0 <= speed <= 100:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        try:
            fan.value = speed / 100.0
            print(f"Fan speed set to {speed:.1f}%")
        except Exception as e:
            print(f"Error setting fan speed: {e}", file=sys.stderr)

except KeyboardInterrupt:
    print("\nExiting program.")

finally:
    if fan is not None:
        try:
            fan.value = 0
            fan.close()
            print("PWM stopped and GPIO resources released.")
        except Exception as e:
            print(f"Error during cleanup: {e}", file=sys.stderr)

