#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter demo.

Touchpads A/B/C toggle bits 2/1/0 respectively.  The current value (0-7)
is shown on the 14-segment display, the discrete LEDs, and an APA102
strip.  A buzzer tone and onboard LEDs are also driven.

Wiring (BCM numbering):
  Touch A  – GPIO5
  Touch B  – GPIO6
  Touch C  – GPIO12
  APA102   – GPIO10 (data), GPIO11 (clock)
  Buzzer   – GPIO13
  Green LED – GPIO7
  Blue LED  – GPIO8
  I2C bus   – 14-segment display (default 0x70)
"""

import signal
import sys
import time

import board
import busio
import digitalio
import pulseio

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
NUM_BITS = 3
BIT_VALUES = [4, 2, 1]          # A, B, C  -> 2^2, 2^1, 2^0
TOUCH_PINS = [5, 6, 12]          # BCM GPIO for touchpads A, B, C
APA102_DATA_PIN = 10
APA102_CLOCK_PIN = 11
BUZZER_PIN = 13
GREEN_LED_PIN = 7
BLUE_LED_PIN = 8
TONE_FREQ = 880
TONE_DURATION = 0.5

# Rainbow HAT I2C address for the 14-segment display
I2C_ADDR = 0x70

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_i2c = None
_display = None
_discrete = None
_strip = None
_buzzer = None
_green = None
_blue = None


def _cleanup():
    """Turn everything off and release resources."""
    global _display, _discrete, _strip, _buzzer, _green, _blue
    try:
        if _display is not None:
            _display.clear()
    except Exception as exc:
        print(f"Display clear error: {exc}", file=sys.stderr)
    try:
        if _discrete is not None:
            for led in _discrete:
                led.off()
    except Exception as exc:
        print(f"Discrete LED off error: {exc}", file=sys.stderr)
    try:
        if _strip is not None:
            _strip.fill(0)
            _strip.show()
    except Exception as exc:
        print(f"APA102 off error: {exc}", file=sys.stderr)
    try:
        if _buzzer is not None:
            _buzzer.deinit()
    except Exception as exc:
        print(f"Buzzer deinit error: {exc}", file=sys.stderr)
    try:
        if _green is not None:
            _green.off()
    except Exception as exc:
        print(f"Green LED off error: {exc}", file=sys.stderr)
    try:
        if _blue is not None:
            _blue.off()
    except Exception as exc:
        print(f"Blue LED off error: {exc}", file=sys.stderr)
    try:
        if _i2c is not None:
            _i2c.deinit()
    except Exception as exc:
        print(f"I2C deinit error: {exc}", file=sys.stderr)


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    _running = False


# ---------------------------------------------------------------------------
# Hardware initialisation
# ---------------------------------------------------------------------------
def init_hardware():
    """Initialise all Rainbow HAT peripherals.  Returns True on success."""
    global _i2c, _display, _discrete, _strip, _buzzer, _green, _blue

    # I2C bus for the 14-segment display
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"I2C bus init error: {exc}", file=sys.stderr)
        _i2c = None

    # 14-segment display
    try:
        _display = board.RainbowHAT()
        _display.clear()
    except Exception as exc:
        print(f"14-segment display init error: {exc}", file=sys.stderr)
        _display = None

    # Discrete LEDs
    try:
        _discrete = _display.discrete
    except Exception as exc:
        print(f"Discrete LEDs init error: {exc}", file=sys.stderr)
        _discrete = None

    # APA102 LED strip
    try:
        _strip = board.RainbowHAT().led_strip
        _strip.fill(0)
        _strip.show()
    except Exception as exc:
        print(f"APA102 strip init error: {exc}", file=sys.stderr)
        _strip = None

    # Buzzer
    try:
        _buzzer = pulseio.PWMOut(BUZZER_PIN, frequency=TONE_FREQ)
    except Exception as exc:
        print(f"Buzzer init error: {exc}", file=sys.stderr)
        _buzzer = None

    # Onboard green LED
    try:
        _green = digitalio.DigitalInOut(GREEN_LED_PIN)
        _green.direction = digitalio.Direction.OUTPUT
    except Exception as exc:
        print(f"Green LED init error: {exc}", file=sys.stderr)
        _green = None

    # Onboard blue LED
    try:
        _blue = digitalio.DigitalInOut(BLUE_LED_PIN)
        _blue.direction = digitalio.Direction.OUTPUT
    except Exception as exc:
        print(f"Blue LED init error: {exc}", file=sys.stderr)
        _blue = None

    return _display is not None or _discrete is not None or _strip is not None


# ---------------------------------------------------------------------------
# Bit manipulation
# ---------------------------------------------------------------------------
def calculate_value(bit_states):
    """Return the decimal value of the current bit states."""
    value = 0
    for bit_state, bit_value in zip(bit_states, BIT_VALUES):
        if bit_state:
            value += bit_value
    return value


def update_displays(value, bit_states):
    """Update the 14-segment display, discrete LEDs, and APA102 strip."""
    # 14-segment display
    if _display is not None:
        try:
            _display.display_int(value)
        except Exception as exc:
            print(f"Display update error: {exc}", file=sys.stderr)

    # Discrete LEDs
    if _discrete is not None:
        try:
            for led, bit_state in zip(_discrete, bit_states):
                if bit_state:
                    led.on()
                else:
                    led.off()
        except Exception as exc:
            print(f"Discrete LED update error: {exc}", file=sys.stderr)

    # APA102 strip
    if _strip is not None:
        try:
            _strip.fill(0)
            if value == 0:
                _strip._pixels[0] = (10, 10, 10)   # dim white
            else:
                r = 255 if bit_states[0] else 0
                g = 255 if bit_states[1] else 0
                b = 255 if bit_states[2] else 0
                _strip._pixels[value] = (r, g, b)
            _strip.show()
        except Exception as exc:
            print(f"APA102 update error: {exc}", file=sys.stderr)


def play_tone():
    """Play a 0.5-second tone on the buzzer."""
    if _buzzer is not None:
        try:
            _buzzer.frequency = TONE_FREQ
            _buzzer.value = 0.5   # 50 % duty cycle
            time.sleep(TONE_DURATION)
            _buzzer.value = 0
        except Exception as exc:
            print(f"Tone playback error: {exc}", file=sys.stderr)


def update_onboard_leds(bit_states):
    """Turn on the onboard green and blue LEDs according to bit states."""
    if _green is not None:
        try:
            _green.value = 1 if bit_states[0] else 0
        except Exception as exc:
            print(f"Green LED update error: {exc}", file=sys.stderr)
    if _blue is not None:
        try:
            _blue.value = 1 if bit_states[1] else 0
        except Exception as exc:
            print(f"Blue LED update error: {exc}", file=sys.stderr)


# ---------------------------------------------------------------------------
# Touch handling
# ---------------------------------------------------------------------------
def handle_touch(channel):
    """Toggle the bit corresponding to the touched channel (0=A, 1=B, 2=C)."""
    global bit_states
    if 0 <= channel < NUM_BITS:
        bit_states[channel] = 1 - bit_states[channel]
        value = calculate_value(bit_states)
        update_displays(value, bit_states)
        play_tone()
        update_onboard_leds(bit_states)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    global bit_states

    if not init_hardware():
        print("No Rainbow HAT peripherals available. Exiting.", file=sys.stderr)
        return

    bit_states = [0, 0, 0]
    update_displays(calculate_value(bit_states), bit_states)

    # Touchpad edge detection using GPIO interrupts
    touch_pins = []
    for idx, pin in enumerate(TOUCH_PINS):
        try:
            touch = digitalio.DigitalInOut(getattr(board, f"D{pin}"))
            touch.direction = digitalio.Direction.INPUT
            touch.pull = digitalio.Pull.UP
            touch_pin = touch
            touch_pins.append(touch_pin)
            touch_pin.when_pressed = lambda ch=idx: handle_touch(ch)
        except Exception as exc:
            print(f"Touchpad {idx} init error: {exc}", file=sys.stderr)
            touch_pins.append(None)

    print("Touchpads A/B/C ready. Press Ctrl+C to exit.")

    try:
        while _running:
            time.sleep(0.1)
    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

