import time
import signal
import sys

try:
    from gpiozero import LED
    from gpiozero import Device
    from gpiozero.pins.native import NativeFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17
led = None

def turn_on_led(pin):
    """Turn on the LED connected to the specified pin."""
    global led
    if led is None:
        led = LED(pin)
    led.on()

def turn_off_led(pin):
    """Turn off the LED connected to the specified pin."""
    global led
    if led is not None:
        led.off()

def cleanup():
    """Release GPIO resources and ensure the pin is left LOW."""
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None

def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    print("\nProgram stopped by user.")
    cleanup()
    sys.exit(0)

def main():
    signal.signal(signal.SIGTERM, signal_handler)
    print("Starting LED blink program on GPIO17...")
    try:
        while True:
            turn_on_led(LED_PIN)
            time.sleep(1)
            turn_off_led(LED_PIN)
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

