import time
import sys
import signal

try:
    from driver import LED
except ImportError:
    print("Error: 'driver' library not found. Install or place it in the same directory as this script.")
    sys.exit(0)

LED_PIN = 18
CYCLES = 5
ON_DURATION = 1.0
OFF_DURATION = 1.0

led = None
running = True

def cleanup():
    global led
    if led is not None:
        try:
            led.off()
        except Exception:
            pass
        try:
            led.close()
        except Exception:
            pass
        led = None

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGTERM, signal_handler)

try:
    led = LED(LED_PIN)
    print(f"LED initialized on GPIO{LED_PIN} (BCM). Starting blink sequence ({CYCLES} cycles).")

    for i in range(1, CYCLES + 1):
        if not running:
            break
        print(f"Cycle {i}/{CYCLES}: LED ON")
        led.on()
        time.sleep(ON_DURATION)
        if not running:
            break
        print(f"Cycle {i}/{CYCLES}: LED OFF")
        led.off()
        time.sleep(OFF_DURATION)

    if running:
        print("Blink sequence completed successfully.")
    else:
        print("Blink sequence interrupted.")

except KeyboardInterrupt:
    print("\nProgram interrupted by user (Ctrl+C).")
except PermissionError:
    print("Error: Permission denied accessing GPIO. Run with appropriate privileges or check /dev/gpiomem permissions.")
except Exception as e:
    print(f"Error: {e}")
finally:
    cleanup()

