import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


class LEDController:
    """
    Controls an LED connected to a Raspberry Pi GPIO pin using gpiozero.

    Attributes:
        led (LED): The gpiozero LED object.
        pin (int): The BCM GPIO pin number connected to the LED.
    """

    def __init__(self, pin: int):
        """
        Initializes the LEDController with the specified GPIO pin.

        Args:
            pin (int): The BCM GPIO pin number.

        Raises:
            ValueError: If the pin number is invalid.
            GPIODeviceError: If the pin cannot be claimed by gpiozero.
        """
        if not isinstance(pin, int) or pin < 0:
            raise ValueError(f"Invalid pin number: {pin!r}. Must be a non-negative integer.")

        try:
            self.led = LED(pin)
            self.pin = pin
        except GPIODeviceError as e:
            raise GPIODeviceError(f"Failed to initialize LED on GPIO{pin}: {e}") from e

    def on(self) -> None:
        """Turns the LED on."""
        try:
            self.led.on()
        except GPIOZeroError as e:
            print(f"Error turning LED on: {e}")

    def off(self) -> None:
        """Turns the LED off."""
        try:
            self.led.off()
        except GPIOZeroError as e:
            print(f"Error turning LED off: {e}")

    def blink(self, on_duration: float, off_duration: float) -> None:
        """
        Blinks the LED once with the specified on and off durations.

        Args:
            on_duration (float): The duration (in seconds) the LED stays on.
            off_duration (float): The duration (in seconds) the LED stays off.

        Raises:
            ValueError: If on_duration or off_duration is negative.
        """
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Durations must be non-negative.")

        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

    def cleanup(self) -> None:
        """Turns the LED off and releases the GPIO resource."""
        self.off()
        try:
            self.led.close()
        except Exception:
            pass


def main() -> None:
    """Main function to demonstrate LED blinking with signal handling."""
    led_controller = None

    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}. Exiting gracefully...")
        if led_controller is not None:
            led_controller.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        led_controller = LEDController(25)
        print("LED blinking on GPIO25. Press Ctrl+C to stop.")

        while True:
            led_controller.blink(1.0, 0.5)

    except ValueError as e:
        print(f"Configuration error: {e}")
    except GPIODeviceError as e:
        print(f"Hardware initialization error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if led_controller is not None:
            led_controller.cleanup()


if __name__ == "__main__":
    main()

