import argparse
import datetime
import json
import os
import random
import signal
import threading
import time
import gzip
import shutil
from typing import Dict, List, Optional

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LOG_FILE_SIZE_LIMIT = 1 * 1024 * 1024   # 1 MB
LOG_FILE_PERMISSIONS = 0o600
ACQUISITION_INTERVAL = 5                 # seconds
NUM_SENSORS = 3
SENSOR_ADDRESSES = [0x40, 0x41, 0x42]   # MCP39F511N default I2C addresses

# ---------------------------------------------------------------------------
# Thread-safe data store
# ---------------------------------------------------------------------------
class EnergyMonitor:
    """Simulates MCP39F511N sensors and manages the logging thread."""

    def __init__(self) -> None:
        self._stop_event = threading.Event()
        self._lock = threading.Lock()
        self._readings: List[Dict] = []
        self._thread: Optional[threading.Thread] = None
        self._running = False

    # -- simulation ----------------------------------------------------------
    def _simulate_sensor_reading(self, sensor_id: int) -> Dict:
        """Return a simulated MCP39F511N reading."""
        return {
            "sensor_id": sensor_id,
            "timestamp": datetime.datetime.now().isoformat(),
            "active_power": round(random.uniform(50, 200), 2),
            "voltage": round(random.uniform(220, 240), 2),
            "current": round(random.uniform(0.2, 1.0), 2),
            "frequency": round(random.uniform(59.5, 60.5), 2),
            "power_factor": round(random.uniform(0.8, 1.0), 2),
        }

    # -- logging -------------------------------------------------------------
    def _rotate_log_if_needed(self, log_file_path: str) -> str:
        """Compress and rotate the log file when it exceeds the size limit."""
        try:
            if os.path.exists(log_file_path) and os.path.getsize(log_file_path) > LOG_FILE_SIZE_LIMIT:
                timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H%M%S")
                compressed_path = f"energy_log_{timestamp}.json.gz"
