import random
import time
import signal
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

# Configuration
LED_PIN = 18
NUM_READINGS = 5
DELAY_SECONDS = 2
FAILURE_PROBABILITY = 0.1
RETRY_DELAY_SECONDS = 1

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def read_water_quality():
    """Simulates reading water quality data, returning a percentage (0-100)."""
    return random.randint(0, 100)


def validate_reading(reading):
    """Validates that the reading is within the acceptable range (0-100)."""
    if not isinstance(reading, (int, float)):
        raise ValueError("Invalid reading type. Must be numeric.")
    if not 0 <= reading <= 100:
        raise ValueError(f"Invalid reading value: {reading}. Must be between 0 and 100.")
    return True


def control_led(led, reading):
    """Controls the LED based on the water quality reading."""
    if reading < 50:
        led.on()
        print(f"Water quality low ({reading}%). LED ON.")
    else:
        led.off()
        print(f"Water quality acceptable ({reading}%). LED OFF.")


def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    led = None
    try:
        # Initialize LED with explicit 330 ohm resistor specification
        led = LED(LED_PIN, resistor="330_ohm")
        print(f"LED initialized on GPIO{LED_PIN} with 330 ohm resistor.")

        for i in range(NUM_READINGS):
            if not _running:
                print("\nShutdown requested. Exiting loop.")
                break

            reading = None
            try:
                # Simulate sensor read with failure injection
                if random.random() < FAILURE_PROBABILITY:
                    print("Sensor read failed. Retrying...")
                    time.sleep(RETRY_DELAY_SECONDS)
                    reading = read_water_quality()
                else:
                    reading = read_water_quality()

                # Validate reading
                validate_reading(reading)

                # Control LED based on reading
                control_led(led, reading)

            except ValueError as e:
                print(f"Error: {e}")
            except GPIODeviceError as e:
                print(f"GPIO Device Error: {e}")
            except Exception as e:
                print(f"Unexpected error during reading {i + 1}: {e}")

            # Delay between readings (skip if interrupted)
            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except GPIOZeroError as e:
        print(f"GPIO Initialization Error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Clean resource release on all exit paths
        if led is not None:
            try:
                led.close()
                print("LED resource released.")
            except Exception as e:
                print(f"Error releasing LED: {e}")
        print("Program finished.")


if __name__ == "__main__":
    main()

