import socket
import json
import time
import random
import signal
import sys
import serial

# Configuration
HOST = '127.0.0.1'
PORT = 9099
GPS_TIMEOUT = 2  # seconds
UART_PORT = '/dev/serial0'  # BCM GPIO14/GPIO15 on Raspberry Pi

# Global state
tracking = False
gps_available = False
uart = None
server_socket = None
running = True


def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    global running, server_socket, uart
    running = False
    if server_socket is not None:
        try:
            server_socket.close()
        except Exception:
            pass
    if uart is not None:
        try:
            uart.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def read_gps_position():
    """Reads GPS data from the UART module and returns a dictionary with latitude and longitude.

    Returns:
        dict: A dictionary containing the latitude and longitude, or None if no data is available.
    """
    global gps_available
    if not gps_available:
        return None

    try:
        # Read a line from the UART
        line = uart.readline().decode('utf-8', errors='ignore').strip()
        if not line:
            return None

        # Parse the line as JSON (assuming the GPS module outputs JSON)
        data = json.loads(line)
        if 'lat' in data and 'lon' in data:
            return {'lat': data['lat'], 'lon': data['lon']}
        return None
    except (json.JSONDecodeError, UnicodeDecodeError, serial.SerialException) as e:
        print(f"Error reading GPS data: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading GPS: {e}", file=sys.stderr)
        return None


def handle_command(command):
    """Handles incoming commands from the client.

    Args:
        command (str): The command to handle.

    Returns:
        str: A response message.
    """
    global tracking
    command = command.lower().strip()

    if command == 'start':
        tracking = True
        return "Tracking started."
    elif command == 'stop':
        tracking = False
        return "Tracking stopped."
    elif command == 'report':
        if tracking:
            position = read_gps_position()
            if position:
                return json.dumps(position)
            else:
                return json.dumps({'error': 'No GPS data available.'})
        else:
            return "Tracking is not started."
    else:
        return "Invalid command."


def main():
    """Main function to start the server and handle client connections."""
    global gps_available, uart, server_socket

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize UART for GPS module
    try:
        uart = serial.Serial(
            port=UART_PORT,
            baudrate=9600,
            timeout=GPS_TIMEOUT
        )
        # Test read to verify module is responding
        test_line = uart.readline()
        if test_line:
            gps_available = True
            print("GPS module detected and initialized.", file=sys.stderr)
        else:
            gps_available = False
            print("GPS module not responding; using simulated data.", file=sys.stderr)
    except serial.SerialException as e:
        print(f"Failed to initialize UART for GPS: {e}", file=sys.stderr)
        gps_available = False

    # Create a TCP/IP socket
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((HOST, PORT))
        server_socket.listen(1)
        print(f"Listening on {HOST}:{PORT}", file=sys.stderr)
    except socket.error as e:
        print(f"Failed to create or bind socket: {e}", file=sys.stderr)
        cleanup()
        return

    try:
        while running:
            # Accept a connection
            try:
                connection, client_address = server_socket.accept()
            except socket.error as e:
                if running:
                    print(f"Socket accept error: {e}", file=sys.stderr)
                continue

            try:
                print(f"Connection from {client_address}", file=sys.stderr)
                data = connection.recv(1024).decode('utf-8', errors='ignore').strip()

                if data:
                    response = handle_command(data)
                    connection.sendall(response.encode('utf-8'))
                else:
                    print("No data received from client.", file=sys.stderr)

            except socket.error as e:
