import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root or appropriate permissions. Run with sudo or as root.")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_moisture_level():
    return random.randint(0, 100)

def control_water_pump(moisture_level):
    if moisture_level < MOISTURE_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        return "ON"
    else:
        GPIO.output(PUMP_PIN, GPIO.LOW)
        return "OFF"

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

    try:
        for i in range(1, ITERATIONS + 1):
            if not _running:
                break

            moisture = read_moisture_level()
            pump_state = control_water_pump(moisture)

            reason = "moisture below threshold" if pump_state == "ON" else "moisture adequate"
            print(f"Iteration {i}: Moisture = {moisture}%, Pump {pump_state} ({reason})")

            if i < ITERATIONS and _running:
                time.sleep(DELAY_SECONDS)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        try:
            GPIO.output(PUMP_PIN, GPIO.LOW)
            GPIO.cleanup()
        except Exception:
            pass
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

