import smbus
import time
import signal
import sys

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
LIS3DH_ADDR = 0x18
WHO_AM_I_REG = 0x0F
WHO_AM_I_EXPECTED = 0x3D
CTRL_REG1 = 0x20
CTRL_REG4 = 0x23
OUT_X_L = 0x28
LED_PIN = 21
BUZZER_PIN = 20
SAMPLE_INTERVAL = 0.1
LOOP_INTERVAL = 1.0
LED_THRESHOLD = 0.3
BUZZER_THRESHOLD = 0.7

# --- Globals for cleanup -----------------------------------------------------
led = None
buzzer = None
i2c_bus = None
running = True


def cleanup():
    """Turn off outputs and close the I2C bus; safe to call multiple times."""
    global led, buzzer, i2c_bus
    if led is not None:
        try:
            led.off()
        except Exception:
            pass
    if buzzer is not None:
        try:
            buzzer.off()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global running
    running = False


def init_gpio():
    """Initialize GPIO outputs; return (led, buzzer) or raise on failure."""
    global led, buzzer
    try:
        from gpiozero import LED
    except Exception as exc:
        raise RuntimeError(f"gpiozero not available: {exc}")
    try:
        led = LED(LED_PIN)
        buzzer = LED(BUZZER_PIN)
    except Exception as exc:
        raise RuntimeError(f"Failed to initialize GPIO pins: {exc}")
    return led, buzzer


def init_i2c():
    """Open the I2C bus and verify the LIS3DH WHO_AM_I register."""
    global i2c_bus
    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
    except Exception as exc:
        raise RuntimeError(f"Failed to open I2C bus {I2C_BUS}: {exc}")
    try:
        who_am_i = i2c_bus.read_byte_data(LIS3DH_ADDR, WHO_AM_I_REG)
    except Exception as exc:
        i2c_bus.close()
        raise RuntimeError(f"Failed to read WHO_AM_I from LIS3DH: {exc}")
    if who_am_i != WHO_AM_I_EXPECTED:
        i2c_bus.close()
        raise RuntimeError(
            f"WHO_AM_I mismatch: got 0x{who_am_i:02X}, expected 0x{WHO_AM_I_EXPECTED:02X}"
        )
    try:
        i2c_bus.write_byte_data(LIS3DH_ADDR, CTRL_REG1, 0x27)  # 100 Hz, all axes enabled
        i2c_bus.write_byte_data(LIS3DH_ADDR, CTRL_REG4, 0x08)  # High-resolution mode
    except Exception as exc:
        i2c_bus.close()
        raise RuntimeError(f"Failed to configure LIS3DH: {exc}")
    return i2c_bus


def read_accel_x():
    """Read the X-axis acceleration as a signed 16-bit integer."""
    try:
        low = i2c_bus.read_byte_data(LIS3DH_ADDR, OUT_X_L)
        high = i2c_bus.read_byte_data(LIS3DH_ADDR, OUT_X_L + 1)
    except Exception as exc:
        raise RuntimeError(f"Failed to read X-axis data: {exc}")
    value = (high << 8) | low
    if value >= 0x8000:
        value -= 0x10000
    return value


def main():
    global running
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        init_gpio()
        init_i2c()
    except RuntimeError as exc:
        print(f"Initialization error: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print("LIS3DH accelerometer monitoring started. Press Ctrl+C to exit.")
    last_print = 0.0

    try:
        while running:
            try:
                x = read_accel_x()
                g = x / 256.0
            except RuntimeError as exc:
                print(f"Sensor read error: {exc}", file=sys.stderr)
                led.off()
                buzzer.off()
                time.sleep(0.1)
                continue

            now = time.monotonic()
            if now - last_print >= LOOP_INTERVAL:
                print(f"Acceleration in X: {g:.2f} g")
                last_print = now

            if abs(g) > LED_THRESHOLD:
                led.on()
            else:
                led.off()

            if abs(g) > BUZZER_THRESHOLD:
                buzzer.on()
            else:
                buzzer.off()

            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

