import time
import threading
import signal
import sys
import smbus
from gpiozero import PWMOutputDevice

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
GYRO_XOUT_H = 0x43
LOG_FILE = "log.txt"
LOOP_PERIOD = 0.01          # seconds
PWM_FREQ = 50               # Hz
PWM_MAX = 50.0              # duty-cycle cap (percent)
MOTOR_PINS = [17, 18, 27]   # BCM pin numbers for the three motors

# --- Globals -----------------------------------------------------------------
kp = [1.0, 1.0, 1.0]
angular_displacement = [0.0, 0.0, 0.0]
running = True
bus = None
pwm_devices = []
input_thread = None


def init_mpu6050():
    """Wake the MPU-6050 and verify the I2C bus is alive."""
    global bus
    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        return False
    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
        time.sleep(0.1)
    except OSError as exc:
        print(f"Error: MPU-6050 not responding at 0x{MPU6050_ADDR:02X}: {exc}", file=sys.stderr)
        bus.close()
        bus = None
        return False
    return True


def read_gyro():
    """Return (gx, gy, gz) in degrees/second or (None, None, None) on error."""
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, GYRO_XOUT_H, 6)
    except OSError as exc:
        print(f"I2C read error: {exc}", file=sys.stderr)
        return None, None, None
    raw = [data[i] << 8 | data[i + 1] for i in range(0, 6, 2)]
    # Sensitivity scale factor for ±250 °/s full‑scale (default after reset)
    scale = 131.0
    return tuple(r / scale for r in raw)


def compute_pwm(axis_idx, error):
    """Proportional controller whose magnitude sets duty cycle and sign sets direction."""
    pwm_val = abs(kp[axis_idx] * error)
    pwm_val = min(pwm_val, PWM_MAX)
    if error < 0:
        pwm_devices[axis_idx].value = pwm_val / 100.0
    else:
        pwm_devices[axis_idx].value = -pwm_val / 100.0


def log_data():
    """Append one line to log.txt every second."""
    try:
