        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
        time.sleep(0.1)
    except OSError as exc:
        print(f"Error: MPU-6050 not responding at 0x{MPU6050_ADDR:02X}: {exc}", file=sys.stderr)
