import RPi.GPIO as GPIO
import time
import datetime

RELAY_PIN = 17
SUNRISE_TIME = datetime.time(7, 0, 0)
SUNSET_TIME = datetime.time(19, 0, 0)

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)

def cleanup_gpio():
    GPIO.cleanup()

def main():
    try:
        setup_gpio()
    except RuntimeError as e:
        print(f"GPIO setup failed: {e}")
        return

    try:
        while True:
            now = datetime.datetime.now().time()
            if SUNRISE_TIME <= now <= SUNSET_TIME:
                if GPIO.input(RELAY_PIN) != GPIO.LOW:
                    GPIO.output(RELAY_PIN, GPIO.LOW)
                    print("Door opening (relay LOW)")
            else:
                if GPIO.input(RELAY_PIN) != GPIO.HIGH:
                    GPIO.output(RELAY_PIN, GPIO.HIGH)
                    print("Door closing (relay HIGH)")
            time.sleep(60)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

