import RPi.GPIO as GPIO
import time
import datetime
import sys

PIR_PIN = 4
DEBOUNCE_SECONDS = 60

def is_feeding_time(now):
    """Return True only during the two daily feeding windows: 07:00-08:00 and 18:00-19:00 (24-hour)."""
    hour = now.hour
    return (7 <= hour < 8) or (18 <= hour < 19)

def trigger_feeder():
    """Simulate triggering the feeder mechanism."""
    print("Feeder activated!")

def cleanup_gpio():
    """Safely clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        cleanup_gpio()
        sys.exit(1)

    last_feed_time = 0.0

    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"Error reading PIR pin: {e}")
                time.sleep(1)
                continue

            if motion_detected:
                now = time.time()
                timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                print(f"Motion detected at {timestamp}")

                if is_feeding_time(datetime.datetime.now()) and (now - last_feed_time) >= DEBOUNCE_SECONDS:
                    print("Feeding initiated at", datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
                    trigger_feeder()
                    last_feed_time = time.time()
                else:
                    print("Not feeding time or recently fed.")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program…")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

