import driver_library


class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


class Motor:
    """
    Controls a DC motor via a PWM-capable driver on a Raspberry Pi.

    The driver library exposes:
        - driver_library.pi: the pigpio instance (must be connected)
        - driver_library.DIRECT_OUTPUT: BCM pin mode constant
        - driver_library.PWM_FREQUENCY: default PWM frequency (Hz)
        - driver_library.PWM_DUTY_CYCLE: default duty-cycle value (0)
        - driver_library.MOTOR_PWM_RANGE: duty-cycle range (0-255)
        - driver_library.get_pwm_instance(pin): retrieve the PWM handle for *pin*
        - driver_library.set_pwm_frequency(pwm, freq): set PWM frequency
        - driver_library.set_pwm_dutycycle(pwm, duty): set duty cycle
        - driver_library.get_pwm_frequency(pwm): return current frequency
        - driver_library.get_pwm_dutycycle(pwm): return current duty cycle
        - driver_library.cleanup(pwm): release the PWM handle
    """

    def __init__(self, pi_instance, pin, frequency=driver_library.PWM_FREQUENCY,
                 duty_cycle=driver_library.PWM_DUTY_CYCLE):
        """
        Initialise the motor on *pin*.

        Args:
            pi_instance:  driver_library.pi instance (must be connected).
            pin:          BCM pin number connected to the motor driver PWM input.
            frequency:    Initial PWM frequency in Hz (default 1000).
            duty_cycle:   Initial duty cycle (default 0 = stopped).

        Raises:
            MotorError:  If the driver library is unavailable, the pin is
                          invalid, or the pigpio connection has failed.
        """
        if not hasattr(driver_library, 'pi') or not hasattr(driver_library, 'set_pin_mode'):
            raise MotorError("Driver library missing required functions or constants.")

        if not isinstance(pi_instance, driver_library.pi):
            raise MotorError("Invalid pigpio instance provided.")

        if not pi_instance.connected:
            raise MotorError("pigpio instance is not connected to the daemon.")

        self.pi = pi_instance
        self.pin = pin
        self.pwm = None

        try:
            driver_library.set_pin_mode(self.pin, driver_library.DIRECT_OUTPUT)
        except Exception as exc:
            raise MotorError(f"Failed to set pin {self.pin} mode: {exc}") from exc

        try:
            self.pwm = driver_library.get_pwm_instance(self.pin)
        except Exception as exc:
            raise MotorError(f"Failed to retrieve PWM instance for pin {self.pin}: {exc}") from exc

        self.set_frequency(frequency)
        self.set_duty_cycle(duty_cycle)

    def set_frequency(self, frequency):
        """
        Set the PWM frequency.

        Args:
            frequency: Desired frequency in Hz.

        Raises:
            MotorError: If the driver library call fails.
        """
        if self.pwm is None:
            raise MotorError("PWM instance not initialised.")
        try:
            driver_library.set_pwm_frequency(self.pwm, frequency)
        except Exception as exc:
            raise MotorError(f"Failed to set PWM frequency: {exc}") from exc

    def set_duty_cycle(self, duty_cycle):
        """
        Set the PWM duty cycle.

        Args:
            duty_cycle: Duty cycle value (0-255).

        Raises:
            MotorError: If the value is out of range or the driver call fails.
        """
        if not isinstance(duty_cycle, int) or not (0 <= duty_cycle <= driver_library.MOTOR_PWM_RANGE):
            raise MotorError(
                f"Duty cycle must be an integer in [0, {driver_library.MOTOR_PWM_RANGE}], "
                f"got {duty_cycle!r}."
            )
        if self.pwm is None:
            raise MotorError("PWM instance not initialised.")
        try:
            driver_library.set_pwm_dutycycle(self.pwm, duty_cycle)
        except Exception as exc:
            raise MotorError(f"Failed to set PWM duty cycle: {exc}") from exc

    def stop(self):
        """Safely stop the motor by setting duty cycle to 0."""
        if self.pwm is not None:
            try:
                driver_library.set_pwm_dutycycle(self.pwm, driver_library.PWM_DUTY_CYCLE)
            except Exception as exc:
                raise MotorError(f"Failed to stop motor (set duty cycle to 0): {exc}") from exc

    def close(self):
        """Release the PWM handle and stop the motor."""
        if self.pwm is not None:
            try:
                driver_library.cleanup(self.pwm)
            except Exception as exc:
                print(f"Warning: error during PWM cleanup: {exc}")
            finally:
                self.pwm = None
        self.stop()

    def __del__(self):
        """Destructor: stop the motor and release resources."""
        self.close()

    def get_status(self):
        """Return the current frequency and duty cycle as a dict."""
        if self.pwm is None:
            return {'frequency': None, 'duty_cycle': None}
        try:
            frequency = driver_library.get_pwm_frequency(self.pwm)
            duty_cycle = driver_library.get_pwm_dutycycle(self.pwm)
            return {'frequency': frequency, 'duty_cycle': duty_cycle}
        except Exception as exc:
            raise MotorError(f"Failed to retrieve motor status: {exc}") from exc

