import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    ServoKit = None


MIN_ANGLE = 0
MAX_ANGLE = 180
STEP_DEGREES = 5
STEP_DELAY = 0.04
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150


def _validate_channel(kit, channel):
    if not isinstance(channel, int) or not (0 <= channel < 16):
        raise ValueError(f"Invalid channel {channel}; must be an int in [0, 15].")


def _validate_angle(angle):
    if not isinstance(angle, (int, float)) or not (MIN_ANGLE <= angle <= MAX_ANGLE):
        raise ValueError(f"Invalid angle {angle}; must be in [{MIN_ANGLE}, {MAX_ANGLE}].")


def initialize_servo_kit(i2c_bus=1, address=0x40):
    if ServoKit is None:
        raise RuntimeError("adafruit_servokit is not installed.")
    try:
        return ServoKit(channels=16, i2c=i2c_bus, address=address)
    except OSError as e:
        raise RuntimeError(f"Failed to initialize ServoKit on I2C bus {i2c_bus} at 0x{address:02X}: {e}") from e


def move_servo(kit, channel, target_angle):
    _validate_channel(kit, channel)
    _validate_angle(target_angle)
    try:
        current = kit.servo[channel].angle
        if current is None:
            current = MIN_ANGLE
        current = int(current)
        target = int(target_angle)
        step = STEP_DEGREES if target > current else -STEP_DEGREES
        while abs(current - target) >= STEP_DEGREES:
            current += step
            kit.servo[channel].angle = current
            time.sleep(STEP_DELAY)
        kit.servo[channel].angle = target
    except (OSError, ValueError) as e:
        raise RuntimeError(f"Error moving servo on channel {channel} to {target_angle}: {e}") from e


def grab_object(kit, channel=SERVO_CHANNEL):
    move_servo(kit, channel, GRAB_ANGLE)


def release_object(kit, channel=SERVO_CHANNEL):
    move_servo(kit, channel, RELEASE_ANGLE)


def _cleanup(signum=None, frame=None):
    if signum is not None:
        print(f"\nReceived signal {signum}; exiting gracefully.")
        sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)
    kit = None
    try:
        kit = initialize_servo_kit()
        grab_object(kit)
        time.sleep(1)
        release_object(kit)
    except (RuntimeError, ValueError) as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        if kit is not None:
            try:
                kit.servo[SERVO_CHANNEL].angle = None
            except Exception:
                pass


if __name__ == "__main__":
    main()

