import signal
import sys
import logging
from gpiozero import OutputDevice

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

PUMP_PIN = 20
LIGHT_PIN = 21

pump = None
light = None


def init_devices():
    global pump, light
    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
        logging.info("GPIO devices initialized: pump=BCM%d, light=BCM%d", PUMP_PIN, LIGHT_PIN)
    except Exception as exc:
        logging.error("Failed to initialize GPIO devices: %s", exc)
        raise


def shutdown_devices():
    global pump, light
    for name, dev in (("pump", pump), ("light", light)):
        if dev is not None:
            try:
                dev.close()
            except Exception as exc:
                logging.warning("Error closing %s: %s", name, exc)
    pump = None
    light = None
    logging.info("GPIO devices closed")


def parse_intent(phrase):
    lowered = phrase.lower()
    if "pump on" in lowered:
        return "pump_on"
    if "pump off" in lowered:
        return "pump_off"
    if "light" in lowered:
        return "light_toggle"
    return None


def apply_intent(intent):
    if intent == "pump_on":
        pump.on()
        logging.info("Pump ON")
    elif intent == "pump_off":
        pump.off()
        logging.info("Pump OFF")
    elif intent == "light_toggle":
        light.toggle()
        state = "ON" if light.is_active else "OFF"
        logging.info("Light toggled -> %s", state)
    else:
        logging.warning("Unknown intent: %s", intent)


def handle_phrase(phrase):
    intent = parse_intent(phrase)
    if intent is None:
        logging.warning("Could not parse intent from: %s", phrase)
        return
    logging.info("Phrase: %s -> intent: %s", phrase, intent)
    apply_intent(intent)


def main():
    init_devices()
    test_phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    for p in test_phrases:
        handle_phrase(p)


if __name__ == "__main__":
    signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))
    try:
        main()
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        shutdown_devices()

