import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALERT_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_radiation_level(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None

def convert_to_float(data):
    try:
        return float(data)
    except ValueError:
        print(f"Invalid data received (not a float): '{data}'", file=sys.stderr)
        return None

def control_alert_pin(pin, radiation_level, threshold):
    if radiation_level > threshold:
        GPIO.output(pin, GPIO.HIGH)
    else:
        GPIO.output(pin, GPIO.LOW)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALERT_PIN, GPIO.OUT, initial=GPIO.LOW)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        GPIO.cleanup()
        sys.exit(1)

    try:
        while _running:
            radiation_data = read_radiation_level(serial_connection)
            if radiation_data is not None:
                radiation_level = convert_to_float(radiation_data)
                if radiation_level is not None:
                    print(f"Radiation Level: {radiation_level} µSv/h")
                    control_alert_pin(ALERT_PIN, radiation_level, RADIATION_THRESHOLD)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

