import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
SAMPLE_INTERVAL = 5
LOG_FILE = 'co2_readings_log.txt'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        ser.reset_input_buffer()
        ser.reset_output_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_co2_level(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return int(line)
    except ValueError:
        print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected read error: {e}", file=sys.stderr)
        return None

def log_reading(log_file, co2_level):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - CO2 Level: {co2_level} ppm\n"
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(log_entry)
            f.flush()
    except OSError as e:
        print(f"Error writing to log file {log_file}: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            co2_concentration = read_co2_level(serial_connection)
            if co2_concentration is not None:
                print(f"CO2 Level: {co2_concentration} ppm")
                log_reading(LOG_FILE, co2_concentration)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.", file=sys.stderr)

if __name__ == "__main__":
    main()

