import serial
import pynmea2
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

running = True

def signal_handler(sig, frame):
    global running
    running = False

def log_coordinates(latitude, longitude, altitude):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m\n'
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
    except IOError as e:
        print(f'Error writing to log file: {e}')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}')
        sys.exit(1)

    try:
        while running:
            try:
                raw_line = serial_port.readline()
                if not raw_line:
                    continue

                line = raw_line.decode('ascii', errors='replace').strip()
                if not line.startswith('$GPGGA'):
                    continue

                msg = pynmea2.parse(line)

                if msg.gps_qual == 1:
                    latitude = msg.latitude
                    longitude = msg.longitude
                    altitude = msg.altitude
                    print(f'Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m')
                    log_coordinates(latitude, longitude, altitude)

            except pynmea2.ParseError as e:
                print(f'Error parsing NMEA sentence: {e}')
            except UnicodeDecodeError as e:
                print(f'Error decoding serial data: {e}')
            except Exception as e:
                print(f'Unexpected error: {e}')

    finally:
        if serial_port.is_open:
            serial_port.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

