        try:
            written = self.ser.write(command.encode('ascii'))
            self.ser.flush()
            return written == len(command)
        except serial.SerialException as exc:
            raise serial.SerialException(
                f"Failed to send AT command {command!r}: {exc}"
            ) from exc

