import signal
import sys
import threading
from typing import List, Optional

from flask import Flask, Response, request, jsonify
from flask.helpers import get_root_path
from flask_sockets import Sockets

try:
    import serial
    from serial import Serial, SerialException
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

app = Flask(__name__)
sockets = Sockets(app)

# Thread-safe in-memory data store seeded with two items
DATA_STORE: List[dict] = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": True},
]
DATA_LOCK = threading.Lock()

# Thread-safe UART handle
_UART: Optional[Serial] = None
_UART_LOCK = threading.Lock()


def _open_uart() -> Optional[Serial]:
    """Open /dev/ttyUSB0 at 9600 baud, 8N1, 1 s timeout. Idempotent."""
    global _UART
    with _UART_LOCK:
        if _UART is not None and _UART.is_open:
            return _UART
        try:
            _UART = Serial(
                port="/dev/ttyUSB0",
                baudrate=9600,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            return _UART
        except SerialException as exc:
            print(f"Error opening /dev/ttyUSB0: {exc}", file=sys.stderr)
            _UART = None
            return None


def _close_uart() -> None:
    """Close the UART port if open."""
    global _UART
    with _UART_LOCK:
        if _UART is not None and _UART.is_open:
            try:
                _UART.close()
            except SerialException as exc:
                print(f"Error closing UART: {exc}", file=sys.stderr)
        _UART = None


def _send_command(command: str) -> Optional[str]:
    """Send a command to the UART device and read a line response."""
    ser = _open_uart()
    if ser is None:
        return None
    try:
        ser.write(command.encode("ascii"))
        ser.flush()
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode("ascii", errors="replace").strip()
    except SerialException as exc:
        print(f"UART communication error: {exc}", file=sys.stderr)
        return None
    finally:
        _close_uart()


@app.route("/version", methods=["GET"])
def get_device_version() -> Response:
    """Query the connected device for its identification string."""
    response = _send_command("*IDN?\n")
    if response is None:
        return Response(
            "Error: Could not communicate with the device or no response received.\n",
            status=504,
            mimetype="text/plain",
        )
    return Response(response + "\n", mimetype="text/plain")


@app.route("/data", methods=["GET"])
def get_all_data() -> Response:
    """Return the entire in-memory data store as JSON."""
    with DATA_LOCK:
        return jsonify(DATA_STORE)


@app.route("/data/<int:item_id>", methods=["GET"])
def get_data_by_id(item_id: int) -> Response:
    """Return a single item by id, or 404 if not found."""
    with DATA_LOCK:
        item = next((it for it in DATA_STORE if it["id"] == item_id), None)
    if item is None:
        return Response("Item not found.\n", status=404, mimetype="text/plain")
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_data_item() -> Response:
    """Create a new data item from JSON body."""
    try:
        new_item = request.get_json(silent=True)
        if not new_item or "name" not in new_item or "done" not in new_item:
            return Response(
                "Invalid request: 'name' and 'done' fields are required.\n",
                status=400,
                mimetype="text/plain",
            )
        if not isinstance(new_item["name"], str) or not new_item["name"].strip():
            return Response(
                "Invalid request: 'name' must be a non-empty string.\n",
                status=400,
                mimetype="text/plain",
            )
        if not isinstance(new_item["done"], bool):
            return Response(
                "Invalid request: 'done' must be a boolean.\n",
                status=400,
                mimetype="text/plain",
            )
    except (TypeError, ValueError) as exc:
        return Response(
            f"Invalid JSON body: {exc}\n",
            status=400,
            mimetype="text/plain",
        )

    with DATA_LOCK:
        new_id = (DATA_STORE[-1]["id"] + 1) if DATA_STORE else 1
        new_item_with_id = {"id": new_id, "name": new_item["name"], "done": new_item["done"]}
        DATA_STORE.append(new_item_with_id)

    return jsonify(new_item_with_id), 201


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    _close_uart()
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        _close_uart()

