import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
        )
        if not ser.is_open:
            ser.open()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_sensor_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error reading from serial port: {e}", file=sys.stderr)
        return None

def process_sensor_data(data):
    if not data:
        return None, None
    parts = data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected exactly 2 comma-separated fields, got {len(parts)}: '{data}'")
    try:
        heart_rate = int(parts[0].strip())
        spo2 = int(parts[1].strip())
    except ValueError as e:
        raise ValueError(f"Non-numeric data received: '{data}'") from e
    return heart_rate, spo2

def display_sensor_data(heart_rate, spo2):
    if heart_rate is not None and spo2 is not None:
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2}%")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            sensor_data = read_sensor_data(serial_connection)
            if sensor_data is not None:
                try:
                    heart_rate, spo2 = process_sensor_data(sensor_data)
                    display_sensor_data(heart_rate, spo2)
                except ValueError as e:
                    print(f"Warning: {e}", file=sys.stderr)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

