LOG_FILE = 'power_consumption.log'


def log_power_consumption(power: float) -> None:
    """Append a timestamped power reading to the log file."""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    line = f'{timestamp} – Power: {power} W\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(line)
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)


def process_meter_data(raw: str) -> float:
    """Parse a raw ASCII line into a float power value."""
    data = raw.strip()
    if not data:
        raise ValueError('Empty line received from meter')
    return float(data)


def main() -> None:
    """Open the UART port, read meter lines, and log parsed power values."""
    try:
        with serial.Serial(PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f'Opened {PORT} @ {BAUD_RATE} baud. Reading meter data...')
            while True:
                try:
                    raw = ser.readline()
                    if not raw:
                        continue
                    line = raw.decode('ascii', errors='replace').strip()
                    if not line:
                        continue
                    power = process_meter_data(line)
                    log_power_consumption(power)
                except ValueError as e:
                    print(f'Invalid data received: {e}', file=sys.stderr)
                except serial.SerialException as e:
                    print(f'Serial read error: {e}', file=sys.stderr)
    except KeyboardInterrupt:
        print('\nProgram terminated by user.')
    except OSError as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
        sys.exit(1)


if __name__ == '__main__':
    main()

