import json
import signal
import sys
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

try:
    import serial
except ImportError:
    print("pyserial is required: pip install pyserial", file=sys.stderr)
    sys.exit(1)

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
READ_TIMEOUT = 0.1
RESPONSE_DELAY = 0.1

DATA = [
    {"id": 1, "name": "item1", "done": False},
    {"id": 2, "name": "item2", "done": False},
]

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


class WebhookHandler(BaseHTTPRequestHandler):
    def _send_json(self, status, payload):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except BrokenPipeError:
            pass

    def _send_html(self, status, body):
        self.send_response(status)
        self.send_header("Content-Type", "text/html")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body.encode("utf-8"))
        except BrokenPipeError:
            pass

    def do_GET(self):
        path = urlparse(self.path).path

        if path == "/version":
            self._version()
        elif path == "/getdata":
            self._get_data()
        elif path.startswith("/getset/"):
            self._get_set_item()
        elif path.startswith("/getpost/"):
            self._get_post_item()
        elif path == "/postjson":
            self._post_json()
        else:
            self._send_json(404, {"error": "Not found"})

    def do_POST(self):
        if self.path == "/postjson":
            self._post_json()
        else:
            self._send_json(405, {"error": "Method not allowed"})

    def _version(self):
        ser = None
        try:
            ser = serial.Serial(
                port=SERIAL_PORT,
                baudrate=BAUD_RATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=READ_TIMEOUT,
            )
            ser.write(b"*IDN?\n")
            time.sleep(RESPONSE_DELAY)
            response = ser.read(ser.in_waiting or 1024)
            text = response.decode("utf-8", errors="replace").replace("\n", "<br>")
            self._send_html(200, f"<h1>Device Info</h1><p>{text}</p>")
        except serial.SerialException as e:
            self._send_json(503, {"error": f"Serial error: {e}"})
        except Exception as e:
            self._send_json(500, {"error": f"Internal error: {e}"})
        finally:
            if ser is not None and ser.is_open:
                ser.close()

    def _get_data(self):
        self._send_json(200, DATA)

    def _get_set_item(self):
        try:
            parts = self.path.split("/")
            if len(parts) != 4:
                self._send_json(400, {"error": "Invalid path"})
                return
            item_id = int(parts[2])
        except (ValueError, IndexError):
            self._send_json(400, {"error": "Invalid item ID"})
            return

        item = next((it for it in DATA if it["id"] == item_id), None)
        if item is None:
            self._send_json(404, {"error": "Item not found"})
        else:
            self._send_json(200, item)

    def _get_post_item(self):
        try:
            parts = self.path.split("/")
            if len(parts) != 5:
                self._send_json(400, {"error": "Invalid path"})
                return
            item_id = int(parts[2])
            name = parts[3]
        except (ValueError, IndexError):
            self._send_json(400, {"error": "Invalid item ID or name"})
            return

        new_item = {"id": item_id, "name": name, "done": False}
        DATA.append(new_item)
        self._send_json(200, DATA)

    def _post_json(self):
        content_type = self.headers.get("Content-Type", "")
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length) if length else b""

        if "application/json" in content_type:
            try:
                data = json.loads(body.decode("utf-8"))
            except json.JSONDecodeError:
                self._send_json(400, {"error": "Invalid JSON"})
                return
        elif "application/x-www-form-urlencoded" in content_type:
            try:
                data = parse_qs(body.decode("utf-8"))
            except Exception:
                self._send_json(400, {"error": "Invalid form data"})
                return
        else:
            self._send_json(400, {"error": "Unsupported content type"})
            return

        if not isinstance(data, dict):
            self._send_json(400, {"error": "Expected object"})
            return

        new_id = (DATA[-1]["id"] + 1) if DATA else 1
        name = data.get("name", [""])[0]
        done_str = data.get("done", ["false"])[0].strip().lower()
        done = done_str in ("true", "1", "yes")

        new_item = {"id": new_id, "name": name, "done": done}
        DATA.append(new_item)
        self._send_json(201, DATA)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        server = ThreadingHTTPServer(("0.0.0.0", 8080), WebhookHandler)
    except OSError as e:
        print(f"Failed to bind port 8080: {e}", file=sys.stderr)
        sys.exit(1)

    print("Starting server on 0.0.0.0:8080")
    try:
        while _running:
            server.handle_request()
    except Exception as e:
        print(f"Server error: {e}", file=sys.stderr)
    finally:
        server.server_close()
        print("Server stopped.")


if __name__ == "__main__":
    main()

