import time
import bluetooth

BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400


def create_bluetooth_socket(port, baudrate):
    """Creates and configures a Bluetooth socket.

    Args:
        port (str): The Bluetooth device path.
        baudrate (int): The baud rate for the connection.

    Returns:
        bluetooth.BluetoothSocket: The configured Bluetooth socket.

    Raises:
        RuntimeError: If socket creation or configuration fails.
    """
    try:
        sock = bluetooth.BluetoothSocket(bluetooth.RFCOMM)
        sock.settimeout(10.0)
        return sock
    except bluetooth.btcommon.BluetoothError as e:
        raise RuntimeError(f"Failed to create Bluetooth socket: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error creating socket: {e}")


def connect_bluetooth(sock, port, baudrate):
    """Connects the Bluetooth socket to the specified device.

    Args:
        sock (bluetooth.BluetoothSocket): The Bluetooth socket.
        port (str): The Bluetooth device path.
        baudrate (int): The baud rate for the connection.

    Raises:
        RuntimeError: If the connection fails.
    """
    try:
        sock.connect((port, baudrate))
    except bluetooth.btcommon.BluetoothError as e:
        raise RuntimeError(f"Failed to connect to Bluetooth device: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error connecting: {e}")


def send_command(sock, command):
    """Sends a command over the Bluetooth connection.

    Args:
        sock (bluetooth.BluetoothSocket): The connected Bluetooth socket.
        command (str): The command to send.

    Raises:
        RuntimeError: If sending the command fails.
    """
    try:
        sock.sendall(command.encode("utf-8"))
    except bluetooth.btcommon.BluetoothError as e:
        raise RuntimeError(f"Failed to send command: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error sending command: {e}")


def main():
    """Main function to handle user input and send commands."""
    sock = None
    try:
        sock = create_bluetooth_socket(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)
        connect_bluetooth(sock, BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)

        while True:
            try:
                user_input = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == "exit":
                break

            command = f"X{user_input}\n"
            send_command(sock, command)
            time.sleep(0.1)

    except RuntimeError as e:
        print(f"Error: {e}")
    except KeyboardInterrupt:
        print("\nInterrupted by user, exiting.")
    finally:
        if sock is not None:
            try:
                sock.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

